// subtitles.js — généré depuis paste.txt
// Les balises HTML présentes dans le texte sont conservées.
const SUBTITLES_FR_CH2 = [
{ start: 1.000, end: 3.180, text: 'Bienvenue dans le programme BRIDGE -<font color="#FFFF00"> Bridging Research and Inclusive Digital Education</font>' },

  { start: 3.181, end: 6.947, text: 'Bienvenue dans le module deux de cette présentation,' },
  { start: 7.067, end: 12.050, text: 'consacré aux propriétés clés des polymères en émulsion et des latex.' },
  { start: 12.170, end: 17.287, text: 'Ce cours est présenté par Gérard Bacquet pour la société SciencExpert.' },
  { start: 17.407, end: 20.587, text: '' },
  { start: 20.707, end: 25.820, text: 'Commençons par le phénomène de <font color="#FFFF00">filmification</font>,' },
  { start: 25.940, end: 31.523, text: 'essentiel pour toutes les applications où la formation d\'un film est requise.' },
  { start: 31.643, end: 35.023, text: 'Une série d\'illustrations présente le processus,' },
  { start: 35.143, end: 37.410, text: 'depuis l\'empilement des particules' },
  { start: 37.530, end: 42.180, text: 'sphériques jusqu\'à leur déformation en structures polyédriques.' },
  { start: 42.300, end: 53.280, text: 'Les schémas détaillent aussi l\'<font color="#FFFF00">évaporation</font> <font color="#FFFF00">de l\'eau</font>, les <font color="#FFFF00">forces capillaires</font>' },
  { start: 53.400, end: 60.450, text: 'et la <font color="#FFFF00">coalescence</font> des chaînes de polymères à l\'échelle des particules.' },
  { start: 60.570, end: 63.750, text: '' },
  { start: 63.870, end: 67.937, text: 'Voyons maintenant les étapes successives de la transformation' },
  { start: 68.057, end: 73.307, text: 'des particules de latex en un <font color="#FFFF00">film continu</font>.' },
  { start: 73.427, end: 82.407, text: 'Tout commence par l\'<font color="#FFFF00">évaporation de</font> <font color="#FFFF00">l\'eau</font> et son absorption par le support,' },
  { start: 82.527, end: 87.043, text: 'qui rapprochent les particules jusqu\'à un empilement compact.' },
  { start: 87.163, end: 95.343, text: 'Sous l\'action des <font color="#FFFF00">forces</font> <font color="#FFFF00">capillaires</font>, les sphères se déforment' },
  { start: 95.463, end: 100.647, text: 'progressivement et adoptent une structure en nid d\'abeille polyédrique.' },
  { start: 100.767, end: 107.080, text: 'Enfin, l\'<font color="#FFFF00">interdiffusion</font> des chaînes de polymères aux interfaces' },
  { start: 107.200, end: 116.183, text: 'assure la <font color="#FFFF00">coalescence</font> complète et la formation du <font color="#FFFF00">film homogène</font> final.' },
  { start: 116.303, end: 119.483, text: '' },
  { start: 119.603, end: 125.897, text: 'Pour décrire ce séchage, on s\'appuie sur le <font color="#FFFF00">modèle de Croll</font>,' },
  { start: 126.017, end: 133.267, text: 'qui distingue trois phases dans la vitesse de séchage d\'un <font color="#FFFF00">film de latex</font>.' },
  { start: 133.387, end: 138.813, text: 'Pendant la phase un, une couche poreuse se forme en surface, au-dessus d\'une' },
  { start: 138.933, end: 144.383, text: 'couche de transition plus concentrée et d\'une couche humide restée intacte.' },
  { start: 144.503, end: 148.797, text: 'Lors de la phase deux, la couche humide initiale a disparu,' },
  { start: 148.917, end: 153.850, text: 'et l\'<font color="#FFFF00">évaporation de l\'eau</font> résiduelle provient' },
  { start: 153.970, end: 157.020, text: 'directement de la couche de transition.' },
  { start: 157.140, end: 161.633, text: 'En phase trois, la couche de transition disparaît à son tour :' },
  { start: 161.753, end: 168.737, text: 'le film est alors totalement sec et prêt pour l\'étape de <font color="#FFFF00">coalescence</font>.' },
  { start: 168.857, end: 172.037, text: '' },
  { start: 172.157, end: 176.203, text: 'Ce modèle a été validé sur le plan théorique et cinétique,' },
  { start: 176.323, end: 179.707, text: 'pour les phases un et deux de l\'évaporation.' },
  { start: 179.827, end: 184.653, text: 'Un graphique, à gauche, montre l\'évolution de la fraction volumique' },
  { start: 184.773, end: 189.270, text: 'solide au cours du temps, découpée selon les trois phases.' },
  { start: 189.390, end: 193.683, text: 'Pour la phase un, la vitesse de perte d\'eau est constante :' },
  { start: 193.803, end: 199.253, text: 'elle dépend uniquement de la surface d\'évaporation et du flux évaporatoire.' },
  { start: 199.373, end: 205.067, text: 'Pour la phase deux, la cinétique dépend de la concentration en eau à la surface,' },
  { start: 205.187, end: 208.587, text: 'ce qui réduit progressivement la vitesse de séchage' },
  { start: 208.707, end: 211.490, text: 'en fonction de l\'épaisseur du film.' },
  { start: 211.610, end: 214.790, text: '' },
  { start: 214.910, end: 218.157, text: 'Examinons à présent la phase trois du séchage,' },
  { start: 218.277, end: 223.793, text: 'centrée sur la déformation des particules et l\'éjection de l\'eau résiduelle.' },
  { start: 223.913, end: 231.027, text: 'Les <font color="#FFFF00">forces capillaires</font> favorisent la déformation des particules élastiques,' },
  { start: 231.147, end: 235.597, text: 'tandis que les contraintes élastiques internes s\'y opposent.' },
  { start: 235.717, end: 242.810, text: 'Un schéma, en haut à gauche, montre la différence de <font color="#FFFF00">pression capillaire</font>' },
  { start: 242.930, end: 247.913, text: 'créée par les ménisques d\'eau entre les sphères de latex en contact.' },
  { start: 248.033, end: 252.900, text: 'Un tableau récapitule la <font color="#FFFF00">pression capillaire</font>' },
  { start: 253.020, end: 256.220, text: 'en fonction du rayon des particules et du nombre' },
  { start: 256.340, end: 259.320, text: 'de sphères en contact : les pressions sont' },
  { start: 259.440, end: 262.957, text: 'très élevées pour les plus petites particules.' },
  { start: 263.077, end: 266.257, text: '' },
  { start: 266.377, end: 270.243, text: 'Cette déformation a été observée dans les travaux de thèse' },
  { start: 270.363, end: 274.460, text: 'de François Magnin, soutenus à l\'Université Paris 6.' },
  { start: 274.580, end: 278.607, text: 'Ils portent sur la morphologie, à différentes échelles,' },
  { start: 278.727, end: 282.110, text: 'de films de latex bidisperses après séchage.' },
  { start: 282.230, end: 287.430, text: 'Une image de microscopie à force atomique montre la déformation des particules' },
  { start: 287.550, end: 292.867, text: 'sphériques en un réseau d\'alvéoles polyédriques de deux cents nanomètres.' },
  { start: 292.987, end: 296.167, text: '' },
  { start: 296.287, end: 301.133, text: 'Revenons à la modélisation de l\'équilibre mécanique de la phase trois,' },
  { start: 301.253, end: 308.703, text: 'entre <font color="#FFFF00">forces capillaires</font> déformantes et contraintes élastiques d\'opposition.' },
  { start: 308.823, end: 315.337, text: 'La <font color="#FFFF00">force capillaire</font> favorise la déformation, tandis que la réponse' },
  { start: 315.457, end: 322.640, text: 'élastique des particules est décrite par la <font color="#FFFF00">théorie du contact de Hertz</font>.' },
  { start: 322.760, end: 330.340, text: 'Pour obtenir la <font color="#FFFF00">coalescence</font>, la <font color="#FFFF00">force capillaire</font> doit' },
  { start: 330.460, end: 334.310, text: 'l\'emporter sur la résistance mécanique du polymère.' },
  { start: 334.430, end: 339.963, text: 'Le critère final indique que le <font color="#FFFF00">module de cisaillement</font>' },
  { start: 340.083, end: 343.863, text: 'du polymère doit rester inférieur à une valeur limite,' },
  { start: 343.983, end: 346.717, text: 'proportionnelle à la tension interfaciale' },
  { start: 346.837, end: 351.020, text: 'et inversement proportionnelle au rayon de la particule.' },
  { start: 351.140, end: 354.320, text: '' },
  { start: 354.440, end: 362.687, text: 'Cela nous amène à la <font color="#FFFF00">température</font> <font color="#FFFF00">minimale de formation de film</font>,' },
  { start: 362.807, end: 368.723, text: 'paramètre clé des conditions de <font color="#FFFF00">coalescence</font> du latex.' },
  { start: 368.843, end: 376.290, text: 'Sur un banc thermique vertical, le film est transparent et parfaitement <font color="#FFFF00">coalescé</font>' },
  { start: 376.410, end: 379.057, text: 'à haute température, alors qu\'à basse' },
  { start: 379.177, end: 382.627, text: 'température il devient opaque et pulvérulent.' },
  { start: 382.747, end: 389.660, text: 'La <font color="#FFFF00">coalescence</font> n\'est possible que si les particules et l\'eau coexistent,' },
  { start: 389.780, end: 396.030, text: 'et si le <font color="#FFFF00">module de cisaillement</font> reste suffisamment faible.' },
  { start: 396.150, end: 400.150, text: 'Si la température de séchage est inférieure à la température' },
  { start: 400.270, end: 409.700, text: 'minimale de <font color="#FFFF00">formation de film</font>, le film ne peut pas <font color="#FFFF00">coalescer</font> correctement.' },
  { start: 409.820, end: 413.000, text: '' },
  { start: 413.120, end: 418.853, text: 'Voyons maintenant l\'influence de la <font color="#FFFF00">taille des particules</font>' },
  { start: 418.973, end: 426.757, text: 'sur cette <font color="#FFFF00">température minimale</font> <font color="#FFFF00">de formation de film</font>.' },
  { start: 426.877, end: 434.037, text: 'Un premier graphique, à gauche, montre la chute du <font color="#FFFF00">module de cisaillement</font>' },
  { start: 434.157, end: 438.670, text: 'à la <font color="#FFFF00">transition vitreuse</font>, qui marque' },
  { start: 438.790, end: 446.573, text: 'le passage de l\'<font color="#FFFF00">état vitreux</font> à l\'<font color="#FFFF00">état caoutchouteux</font>.' },
  { start: 446.693, end: 452.453, text: 'Un second graphique, à droite, illustre l\'augmentation de la température minimale' },
  { start: 452.573, end: 458.020, text: 'de <font color="#FFFF00">formation de film</font> avec le rayon des particules,' },
  { start: 458.140, end: 461.123, text: 'de trente à cent cinquante nanomètres.' },
  { start: 461.243, end: 465.910, text: 'Des flacons témoignent qu\'une taille de particule plus petite favorise' },
  { start: 466.030, end: 471.210, text: 'la <font color="#FFFF00">coalescence</font> à des températures plus basses,' },
  { start: 471.330, end: 476.180, text: 'en augmentant les <font color="#FFFF00">forces capillaires</font>.' },
  { start: 476.300, end: 479.480, text: '' },
  { start: 479.600, end: 482.780, text: 'Nous ouvrons maintenant une nouvelle section,' },
  { start: 482.900, end: 488.350, text: 'consacrée aux propriétés mécaniques des polymères en émulsion et des latex.' },
  { start: 488.470, end: 494.870, text: 'Ces propriétés concernent les matériaux <font color="#FFFF00">composites</font> et de nombreuses' },
  { start: 494.990, end: 500.380, text: 'applications industrielles : peintures, papier, textile ou colles.' },
  { start: 500.500, end: 504.593, text: 'Une frise illustrée, en bas de page, rappelle les étapes' },
  { start: 504.713, end: 509.563, text: 'microstructurales de déformation et d\'organisation des particules.' },
  { start: 509.683, end: 512.863, text: '' },
  { start: 512.983, end: 516.297, text: 'Commençons par les états physiques du polymère,' },
  { start: 516.417, end: 521.533, text: 'selon sa <font color="#FFFF00">masse molaire</font> et la température.' },
  { start: 521.653, end: 529.013, text: 'Un premier <font color="#FFFF00">diagramme de phases</font>, à gauche, associe la température et la masse' },
  { start: 529.133, end: 531.780, text: 'molaire moyenne en poids, et délimite' },
  { start: 531.900, end: 535.597, text: 'les zones vitreuse, caoutchoutique et liquide.' },
  { start: 535.717, end: 538.077, text: 'Un second graphique, à droite,' },
  { start: 538.197, end: 545.977, text: 'montre la baisse du <font color="#FFFF00">module de</font> <font color="#FFFF00">Young</font> avec la température,' },
  { start: 546.097, end: 554.993, text: 'du passage de l\'<font color="#FFFF00">état vitreux</font> à l\'<font color="#FFFF00">état caoutchoutique</font>, puis fluide.' },
  { start: 555.113, end: 558.627, text: 'À basse température, le polymère possède un module' },
  { start: 558.747, end: 564.710, text: 'élastique élevé et constant : c\'est l\'<font color="#FFFF00">état vitreux</font>.' },
  { start: 564.830, end: 574.277, text: 'Au-delà de la <font color="#FFFF00">transition vitreuse</font>, le <font color="#FFFF00">plateau caoutchoutique</font> présente des valeurs' },
  { start: 574.397, end: 580.180, text: 'de module comprises entre dix puissance quatre et dix puissance six mégapascals.' },
  { start: 580.300, end: 585.260, text: 'À plus haute température, une transition finale mène à l\'état fluide,' },
  { start: 585.380, end: 590.430, text: 'décrit par des propriétés rhéologiques pseudo-plastiques spécifiques.' },
  { start: 590.550, end: 593.730, text: '' },
  { start: 593.850, end: 597.250, text: 'Voyons maintenant l\'effet des variables principales' },
  { start: 597.370, end: 604.353, text: 'sur le comportement <font color="#FFFF00">thermo-viscoélastique</font> des polymères statistiques.' },
  { start: 604.473, end: 610.673, text: 'Un graphique représente l\'évolution du <font color="#FFFF00">module élastique</font> du latex' },
  { start: 610.793, end: 618.823, text: 'en fonction de la température, pour différentes formulations de <font color="#FFFF00">styrène-butadiène</font>.' },
  { start: 618.943, end: 624.010, text: 'Le <font color="#FFFF00">module de Young</font> peut être modulé en ajustant' },
  { start: 624.130, end: 633.093, text: 'la <font color="#FFFF00">température de transition vitreuse</font>, grâce au ratio de <font color="#FFFF00">monomères</font>.' },
  { start: 633.213, end: 644.593, text: 'Le niveau du <font color="#FFFF00">plateau caoutchoutique</font> dépend de la <font color="#FFFF00">masse molaire</font> ou du <font color="#FFFF00">taux de gel</font>,' },
  { start: 644.713, end: 649.363, text: 'ici comparés pour des taux de trente et soixante-dix pour cent.' },
  { start: 649.483, end: 652.663, text: '' },
  { start: 652.783, end: 659.117, text: 'Comparons maintenant les courbes expérimentales de <font color="#FFFF00">viscoélasticité</font>' },
  { start: 659.237, end: 665.487, text: 'avec les modèles mécaniques de Maxwell et de <font color="#FFFF00">Voigt-Kelvin</font>.' },
  { start: 665.607, end: 671.187, text: 'Les schémas du haut illustrent le <font color="#FFFF00">modèle de Maxwell</font>,' },
  { start: 671.307, end: 676.200, text: 'en série, et le modèle de <font color="#FFFF00">Voigt-Kelvin</font>,' },
  { start: 676.320, end: 681.483, text: 'en parallèle, pour décrire les composantes élastiques et visqueuses.' },
  { start: 681.603, end: 686.917, text: 'À gauche, le graphique du <font color="#FFFF00">module de conservation</font>' },
  { start: 687.037, end: 689.637, text: 'G\' en fonction de la température montre' },
  { start: 689.757, end: 696.823, text: 'la transition entre l\'<font color="#FFFF00">état</font> <font color="#FFFF00">vitreux</font> et le plateau' },
  { start: 696.943, end: 700.127, text: 'caoutchoutique pour différents polymères.' },
  { start: 700.247, end: 708.360, text: 'À droite, le graphique du <font color="#FFFF00">module</font> <font color="#FFFF00">de perte</font> G\'\' met en évidence' },
  { start: 708.480, end: 715.997, text: 'les pics de dissipation d\'énergie caractéristiques de la <font color="#FFFF00">transition vitreuse</font>.' },
  { start: 716.117, end: 719.297, text: '' },
  { start: 719.417, end: 724.930, text: 'Passons à l\'<font color="#FFFF00">équation de Fox</font>, qui permet de calculer' },
  { start: 725.050, end: 735.567, text: 'la <font color="#FFFF00">température de transition</font> <font color="#FFFF00">vitreuse</font> théorique d\'un <font color="#FFFF00">copolymère</font>.' },
  { start: 735.687, end: 742.753, text: 'Elle exprime l\'inverse de la <font color="#FFFF00">Tg</font> globale comme la somme pondérée des fractions' },
  { start: 742.873, end: 752.170, text: 'massiques de chaque <font color="#FFFF00">monomère</font>, divisées par leur <font color="#FFFF00">Tg</font> respective en Kelvin.' },
  { start: 752.290, end: 755.757, text: 'Un tableau récapitule les températures de transition' },
  { start: 755.877, end: 759.943, text: 'vitreuse de divers <font color="#FFFF00">homopolymères</font>' },
  { start: 760.063, end: 763.243, text: 'courants, du polybutadiène à moins cent douze' },
  { start: 763.363, end: 766.613, text: 'degrés au PMMA à cent huit degrés Celsius.' },
  { start: 766.733, end: 769.913, text: '' },
  { start: 770.033, end: 773.680, text: 'Confrontons maintenant cette équation à la réalité :' },
  { start: 773.800, end: 776.600, text: 'voici les données de quatre-vingt-dix-neuf' },
  { start: 776.720, end: 783.550, text: 'latex <font color="#FFFF00">styrène-butadiène</font>, comparées à la courbe théorique de Fox.' },
  { start: 783.670, end: 789.537, text: 'Le graphique présente la <font color="#FFFF00">température de transition vitreuse</font>' },
  { start: 789.657, end: 796.440, text: 'en fonction du pourcentage massique de styrène dans le <font color="#FFFF00">copolymère</font>.' },
  { start: 796.560, end: 801.293, text: 'La formule appliquée aux fractions massiques du butadiène et du styrène' },
  { start: 801.413, end: 805.863, text: 'permet d\'ajuster précisément la ligne de tendance théorique.' },
  { start: 805.983, end: 810.497, text: 'Les points expérimentaux, issus de divers procédés et producteurs' },
  { start: 810.617, end: 814.980, text: 'industriels, montrent un très bon accord avec le modèle.' },
  { start: 815.100, end: 818.280, text: '' },
  { start: 818.400, end: 824.933, text: 'Intéressons-nous ensuite à l\'impact des <font color="#FFFF00">forces de Keesom</font> et du moment' },
  { start: 825.053, end: 832.570, text: 'dipolaire des liaisons secondaires sur la <font color="#FFFF00">température de transition vitreuse</font>.' },
  { start: 832.690, end: 839.070, text: 'Un tableau présente la hausse de la <font color="#FFFF00">Tg</font> selon le motif substitué,' },
  { start: 839.190, end: 845.107, text: 'du polyéthylène à moins cent dix degrés au PTFE à cent vingt-trois degrés Celsius.' },
  { start: 845.227, end: 849.787, text: 'Un graphique, en bas à gauche, montre la corrélation croissante' },
  { start: 849.907, end: 856.640, text: 'entre la <font color="#FFFF00">température de</font> <font color="#FFFF00">transition vitreuse</font>' },
  { start: 856.760, end: 862.057, text: 'et le <font color="#FFFF00">moment dipolaire</font>, exprimé en Debye.' },
  { start: 862.177, end: 867.243, text: 'La formule de l\'énergie d\'interaction de Keesom confirme que le renforcement' },
  { start: 867.363, end: 874.747, text: 'des liaisons dipolaires secondaires augmente directement la <font color="#FFFF00">Tg</font> du polymère.' },
  { start: 874.867, end: 878.047, text: '' },
  { start: 878.167, end: 881.900, text: 'Voyons maintenant l\'influence des transitions thermiques' },
  { start: 882.020, end: 891.137, text: 'sur les matériaux <font color="#FFFF00">thermoformés</font> et <font color="#FFFF00">composites</font> à base de latex SB et SBAn.' },
  { start: 891.257, end: 894.057, text: 'Un graphique compare l\'évolution du module' },
  { start: 894.177, end: 897.177, text: 'de cisaillement en fonction de la température' },
  { start: 897.297, end: 906.347, text: 'pour les systèmes <font color="#FFFF00">styrène-butadiène</font> et <font color="#FFFF00">styrène-butadiène-acrylonitrile</font>.' },
  { start: 906.467, end: 913.267, text: 'L\'ajout d\'<font color="#FFFF00">acrylonitrile</font> modifie la pente de transition et élargit la zone' },
  { start: 913.387, end: 918.883, text: 'de ramollissement mécanique, grâce aux interactions polaires introduites.' },
  { start: 919.003, end: 926.337, text: 'Des exemples d\'applications finales montrent des panneaux décoratifs <font color="#FFFF00">thermoformés</font>' },
  { start: 926.457, end: 931.973, text: 'et des éléments textiles structurés pour l\'aménagement intérieur automobile.' },
  { start: 932.093, end: 935.273, text: '' },
  { start: 935.393, end: 938.527, text: 'Abordons à présent la concentration pigmentaire' },
  { start: 938.647, end: 944.190, text: 'volumique, appelée <font color="#FFFF00">CVP</font>, ou PVC en anglais.' },
  { start: 944.310, end: 947.910, text: 'Sa formule la définit comme le rapport entre le volume' },
  { start: 948.030, end: 953.193, text: 'combiné des pigments et des charges, et le volume total des solides.' },
  { start: 953.313, end: 960.113, text: 'Trois schémas illustrent les régimes de formulation en fonction de la <font color="#FFFF00">CVP</font>' },
  { start: 960.233, end: 964.797, text: 'critique, selon la présence ou l\'absence de liant en excès.' },
  { start: 964.917, end: 969.830, text: 'Lorsque la <font color="#FFFF00">CVP</font> dépasse la valeur critique,' },
  { start: 969.950, end: 972.930, text: 'la quantité de liant devient insuffisante,' },
  { start: 973.050, end: 980.100, text: 'ce qui provoque l\'apparition de <font color="#FFFF00">porosités</font> et de vides au sein du film.' },
  { start: 980.220, end: 983.400, text: '' },
  { start: 983.520, end: 996.033, text: 'Cette <font color="#FFFF00">porosité</font> nous conduit au <font color="#FFFF00">module</font> <font color="#FFFF00">de Young</font> des <font color="#FFFF00">composites</font> poreux,' },
  { start: 996.153, end: 1003.603, text: 'un sujet de nouveau très étudié avec l\'émergence de la <font color="#FFFF00">fabrication additive</font>.' },
  { start: 1003.723, end: 1007.657, text: 'Un graphique compare plusieurs modèles théoriques décrivant' },
  { start: 1007.777, end: 1016.493, text: 'la chute du <font color="#FFFF00">module élastique</font> en fonction de la <font color="#FFFF00">porosité</font> volumique.' },
  { start: 1016.613, end: 1025.480, text: 'Le <font color="#FFFF00">modèle de Bert</font> exprime le rapport des modules en fonction de la <font color="#FFFF00">porosité</font>' },
  { start: 1025.600, end: 1033.563, text: 'relative, de la <font color="#FFFF00">porosité</font> maximale et d\'un facteur de concentration de contrainte.' },
  { start: 1033.683, end: 1037.463, text: 'Ce facteur K varie selon la géométrie des inclusions :' },
  { start: 1037.583, end: 1039.450, text: 'zéro virgule soixante-quinze' },
  { start: 1039.570, end: 1044.733, text: 'pour des particules plates comme l\'argile, et deux pour des sphères.' },
  { start: 1044.853, end: 1048.033, text: '' },
  { start: 1048.153, end: 1053.353, text: 'Appliquons ces notions de <font color="#FFFF00">porosité</font> et de rigidité' },
  { start: 1053.473, end: 1058.503, text: 'à un cas pratique : le <font color="#FFFF00">papier couché</font>.' },
  { start: 1058.623, end: 1063.917, text: 'Un premier graphique, à gauche, montre la diminution polynomiale du module' },
  { start: 1064.037, end: 1070.553, text: 'relatif E\' sur E\' zéro en fonction de la fraction de <font color="#FFFF00">porosité</font>.' },
  { start: 1070.673, end: 1079.587, text: 'Un tableau récapitule l\'évolution de la <font color="#FFFF00">porosité</font> et des <font color="#FFFF00">modules de Young</font>,' },
  { start: 1079.707, end: 1085.803, text: 'vitreux et caoutchoutique, selon le taux de particules de polystyrène et de latex.' },
  { start: 1085.923, end: 1091.350, text: 'Le graphique principal, à droite, confirme la baisse des modules vitreux E\'v' },
  { start: 1091.470, end: 1096.137, text: 'et caoutchoutique E\'c lorsque la <font color="#FFFF00">porosité</font>' },
  { start: 1096.257, end: 1099.707, text: 'passe de vingt-cinq à trente et un pour cent.' },
  { start: 1099.827, end: 1104.967, text: 'Deux vignettes, en bas, relient la rigidité Taber au grammage déposé,' },
  { start: 1105.087, end: 1111.603, text: 'ainsi qu\'à la <font color="#FFFF00">porosité</font> mesurée par densité optique aux encres.' },
  { start: 1111.723, end: 1114.903, text: '' },
  { start: 1115.023, end: 1117.890, text: 'Voyons maintenant le comportement mécanique' },
  { start: 1118.010, end: 1123.527, text: 'des matériaux <font color="#FFFF00">composites</font> contenant du polymère.' },
  { start: 1123.647, end: 1125.513, text: 'Un tableau comparatif montre' },
  { start: 1125.633, end: 1133.100, text: 'que la <font color="#FFFF00">température de transition</font> <font color="#FFFF00">vitreuse</font> du composite' },
  { start: 1133.220, end: 1135.933, text: 'reste identique à celle du latex seul,' },
  { start: 1136.053, end: 1143.437, text: 'bien que son <font color="#FFFF00">module</font> <font color="#FFFF00">élastique</font> soit plus élevé.' },
  { start: 1143.557, end: 1150.957, text: 'Un graphique d\'analyse mécanique dynamique illustre les courbes de <font color="#FFFF00">module de Young</font>' },
  { start: 1151.077, end: 1156.303, text: 'pour trois formulations, de <font color="#FFFF00">Tg</font> moins trente,' },
  { start: 1156.423, end: 1159.673, text: 'moins douze et moins trois degrés Celsius.' },
  { start: 1159.793, end: 1166.593, text: 'Le texte souligne que les <font color="#FFFF00">composites</font> formulés avec un polymère conservent' },
  { start: 1166.713, end: 1173.897, text: 'les mêmes propriétés <font color="#FFFF00">thermo-viscoélastiques</font> que le polymère constitutif.' },
  { start: 1174.017, end: 1177.197, text: '' },
  { start: 1177.317, end: 1180.917, text: 'Changeons de sujet pour définir les notions de rupture' },
  { start: 1181.037, end: 1187.733, text: 'adhésive et de <font color="#FFFF00">rupture cohésive</font>, dans le domaine des adhésifs.' },
  { start: 1187.853, end: 1193.167, text: 'À gauche, lorsque la cohésion interne du polymère est supérieure à l\'adhésion' },
  { start: 1193.287, end: 1201.297, text: 'à la surface, la rupture se produit à l\'interface : c\'est une <font color="#FFFF00">rupture adhésive</font>.' },
  { start: 1201.417, end: 1204.330, text: 'À droite, si l\'adhésion entre le polymère' },
  { start: 1204.450, end: 1207.630, text: 'et la surface excède la cohésion du polymère,' },
  { start: 1207.750, end: 1214.913, text: 'la rupture survient au cœur du matériau : c\'est une <font color="#FFFF00">rupture cohésive</font>.' },
  { start: 1215.033, end: 1218.500, text: 'Des schémas illustrent ces deux modes de défaillance' },
  { start: 1218.620, end: 1221.670, text: 'mécanique entre deux substrats solides.' },
  { start: 1221.790, end: 1224.970, text: '' },
  { start: 1225.090, end: 1229.003, text: 'Regardons maintenant l\'effet de la rigidité du polymère,' },
  { start: 1229.123, end: 1236.820, text: 'représentée par sa <font color="#FFFF00">Tg</font>, sur l\'<font color="#FFFF00">énergie de rupture</font>.' },
  { start: 1236.940, end: 1243.500, text: 'Le premier graphique, à gauche, indique que l\'<font color="#FFFF00">énergie de rupture</font>' },
  { start: 1243.620, end: 1252.737, text: 'adhésive diminue lorsque la <font color="#FFFF00">température</font> <font color="#FFFF00">de transition vitreuse</font> augmente.' },
  { start: 1252.857, end: 1256.017, text: 'Le deuxième, à droite, montre au contraire' },
  { start: 1256.137, end: 1266.453, text: 'une augmentation de l\'<font color="#FFFF00">énergie de</font> <font color="#FFFF00">rupture</font> cohésive avec la <font color="#FFFF00">Tg</font>.' },
  { start: 1266.573, end: 1271.840, text: 'Le graphique du bas superpose ces deux mécanismes et met en évidence un optimum' },
  { start: 1271.960, end: 1279.323, text: 'd\'<font color="#FFFF00">énergie d\'adhésion</font>, au point d\'intersection des deux modes de rupture.' },
  { start: 1279.443, end: 1282.623, text: '' },
  { start: 1282.743, end: 1287.610, text: 'Poursuivons avec l\'effet de la <font color="#FFFF00">carboxylation</font>' },
  { start: 1287.730, end: 1292.643, text: 'du latex sur la cohésion du <font color="#FFFF00">papier couché</font>,' },
  { start: 1292.763, end: 1300.613, text: 'en fonction de la <font color="#FFFF00">température</font> <font color="#FFFF00">de transition vitreuse</font>.' },
  { start: 1300.733, end: 1304.533, text: 'Un graphique représente la résistance à l\'arrachage à sec' },
  { start: 1304.653, end: 1313.350, text: 'en fonction de la <font color="#FFFF00">Tg</font>, pour différents niveaux de <font color="#FFFF00">carboxylation</font>.' },
  { start: 1313.470, end: 1320.203, text: 'Une <font color="#FFFF00">carboxylation</font> accrue améliore la cohésion du papier lorsque le latex' },
  { start: 1320.323, end: 1329.733, text: 'est rigide, c\'est-à-dire dans la zone de <font color="#FFFF00">rupture adhésive</font>, à <font color="#FFFF00">Tg</font> élevée.' },
  { start: 1329.853, end: 1338.527, text: 'En revanche, à basse <font color="#FFFF00">Tg</font>, dans le domaine de la <font color="#FFFF00">rupture cohésive</font>,' },
  { start: 1338.647, end: 1345.830, text: 'la <font color="#FFFF00">carboxylation</font> n\'a pas d\'effet significatif sur la cohésion du papier.' },
  { start: 1345.950, end: 1349.130, text: '' },
  { start: 1349.250, end: 1354.517, text: 'Voyons ensuite l\'effet de la <font color="#FFFF00">taille des particules</font>' },
  { start: 1354.637, end: 1359.953, text: 'de latex dans le cas d\'une <font color="#FFFF00">rupture adhésive</font>.' },
  { start: 1360.073, end: 1364.987, text: 'Deux schémas comparatifs montrent que plus les particules sont grosses,' },
  { start: 1365.107, end: 1370.023, text: 'plus la surface de contact entre le polymère et le pigment diminue.' },
  { start: 1370.143, end: 1374.143, text: 'Le graphique de gauche illustre la décroissance de l\'énergie' },
  { start: 1374.263, end: 1382.113, text: 'd\'adhésion lorsque la <font color="#FFFF00">taille</font> <font color="#FFFF00">des particules</font> augmente.' },
  { start: 1382.233, end: 1387.327, text: 'Cette relation, inversement proportionnelle au diamètre des particules,' },
  { start: 1387.447, end: 1392.030, text: 'régit la résistance mécanique lors d\'une défaillance adhésive.' },
  { start: 1392.150, end: 1395.330, text: '' },
  { start: 1395.450, end: 1406.363, text: 'Voici maintenant le passage d\'une <font color="#FFFF00">rupture</font> <font color="#FFFF00">cohésive</font> à une <font color="#FFFF00">rupture adhésive</font>,' },
  { start: 1406.483, end: 1413.247, text: 'par <font color="#FFFF00">plastification</font> de l\'interface, notamment en présence d\'eau.' },
  { start: 1413.367, end: 1418.613, text: 'À sec, les fortes interactions acide-base entre les groupements carboxylates' },
  { start: 1418.733, end: 1426.563, text: 'et le pigment assurent une adhésion élevée, qui conduit à une <font color="#FFFF00">rupture cohésive</font>.' },
  { start: 1426.683, end: 1431.663, text: 'En milieu humide, la présence de molécules d\'eau à l\'interface affaiblit' },
  { start: 1431.783, end: 1438.367, text: 'l\'adhésion et provoque une transition vers la <font color="#FFFF00">rupture adhésive</font>.' },
  { start: 1438.487, end: 1443.733, text: 'Le graphique du bas compare les niveaux d\'énergie à sec et en milieu humide,' },
  { start: 1443.853, end: 1449.237, text: 'et met en évidence la baisse d\'énergie globale due aux effets d\'interface.' },
  { start: 1449.357, end: 1452.537, text: '' },
  { start: 1452.657, end: 1456.323, text: 'Introduisons maintenant l\'équivalence entre température' },
  { start: 1456.443, end: 1463.740, text: 'et vitesse de sollicitation, selon la théorie de <font color="#FFFF00">Williams-Landel-Ferry</font>.' },
  { start: 1463.860, end: 1469.860, text: 'Un graphique du <font color="#FFFF00">module de Young</font> en fonction de la température' },
  { start: 1469.980, end: 1472.513, text: 'montre le déplacement de la transition' },
  { start: 1472.633, end: 1475.633, text: 'vitreuse vers les hautes températures lorsque' },
  { start: 1475.753, end: 1479.070, text: 'la fréquence passe de un à dix mille hertz.' },
  { start: 1479.190, end: 1485.523, text: 'L\'équation exprime la <font color="#FFFF00">Tg</font> à une fréquence donnée comme une fonction' },
  { start: 1485.643, end: 1491.227, text: 'logarithmique du rapport entre cette fréquence et une fréquence de référence.' },
  { start: 1491.347, end: 1496.127, text: 'Le coefficient k est proche de dix pour les polymères conventionnels,' },
  { start: 1496.247, end: 1502.430, text: 'tels que les systèmes <font color="#FFFF00">styrène-butadiène</font> ou les acrylates.' },
  { start: 1502.550, end: 1505.730, text: '' },
  { start: 1505.850, end: 1508.783, text: 'Combinons à présent température et fréquence' },
  { start: 1508.903, end: 1512.087, text: 'pour décrire l\'état physique du polymère.' },
  { start: 1512.207, end: 1517.653, text: 'Un diagramme schématique divise le comportement en trois zones : un état rigide' },
  { start: 1517.773, end: 1525.650, text: 'à haut module, un état intermédiaire, et un <font color="#FFFF00">état caoutchoutique</font> à bas module.' },
  { start: 1525.770, end: 1531.463, text: 'Le texte, à droite, rappelle l\'importance de définir précisément l\'environnement' },
  { start: 1531.583, end: 1537.793, text: 'd\'utilisation, en température et en fréquence, pour concevoir le polymère adapté.' },
  { start: 1537.913, end: 1540.847, text: 'La question posée en bas invite à déterminer' },
  { start: 1540.967, end: 1544.550, text: 'explicitement ces deux variables d\'application.' },
  { start: 1544.670, end: 1547.850, text: '' },
  { start: 1547.970, end: 1555.667, text: 'Voyons une application pratique : la conception de latex pour l\'<font color="#FFFF00">héliogravure</font>.' },
  { start: 1555.787, end: 1559.100, text: 'À gauche, des illustrations et une vue en coupe' },
  { start: 1559.220, end: 1562.487, text: 'au microscope électronique à balayage d\'un papier' },
  { start: 1562.607, end: 1567.540, text: '<font color="#FFFF00">héliogravure</font> mettent en évidence le phénomène' },
  { start: 1567.660, end: 1571.243, text: 'des points manquants à la surface de l\'imprimé.' },
  { start: 1571.363, end: 1576.763, text: 'Des schémas du procédé d\'impression montrent comment le manque de compressibilité' },
  { start: 1576.883, end: 1582.600, text: 'locale empêche le transfert parfait de l\'encre depuis les alvéoles du cylindre.' },
  { start: 1582.720, end: 1585.653, text: 'Le graphique de droite montre l\'amélioration' },
  { start: 1585.773, end: 1589.420, text: 'de l\'imprimabilité avec le pourcentage de butadiène,' },
  { start: 1589.540, end: 1594.390, text: 'qui accroît la souplesse et la compressibilité dynamique du latex.' },
  { start: 1594.510, end: 1597.690, text: '' },
  { start: 1597.810, end: 1600.857, text: 'Place maintenant à l\'émulsion intelligente,' },
  { start: 1600.977, end: 1606.893, text: 'dotée d\'une <font color="#FFFF00">réticulation</font> stimulée par la température.' },
  { start: 1607.013, end: 1610.593, text: 'Les schémas du haut montrent les étapes du séchage,' },
  { start: 1610.713, end: 1618.297, text: 'de l\'<font color="#FFFF00">évaporation de l\'eau</font> à la déformation hexagonale des particules de latex.' },
  { start: 1618.417, end: 1623.330, text: 'Des zooms mettent en évidence des fonctionnalités réactives distinctes,' },
  { start: 1623.450, end: 1626.497, text: 'comme des groupements hydroxyle et époxyde,' },
  { start: 1626.617, end: 1629.933, text: 'portées par des particules complémentaires.' },
  { start: 1630.053, end: 1639.187, text: 'Le graphique du bas montre l\'augmentation de la <font color="#FFFF00">masse molaire</font> et du <font color="#FFFF00">taux de gel</font>' },
  { start: 1639.307, end: 1648.917, text: 'avec la température, au-delà de la <font color="#FFFF00">Tg</font>, signe d\'une <font color="#FFFF00">réticulation</font> effective.' },
  { start: 1649.037, end: 1652.217, text: '' },
  { start: 1652.337, end: 1657.870, text: 'Voyons quel est l\'effet de cette <font color="#FFFF00">réticulation</font> stimulée' },
  { start: 1657.990, end: 1663.507, text: 'sur les propriétés <font color="#FFFF00">viscoélastiques</font> du polymère.' },
  { start: 1663.627, end: 1672.160, text: 'Un graphique compare le <font color="#FFFF00">module</font> <font color="#FFFF00">élastique</font> en fonction de la température' },
  { start: 1672.280, end: 1679.330, text: 'pour un polymère standard et pour un polymère à <font color="#FFFF00">réticulation</font> stimulée.' },
  { start: 1679.450, end: 1685.783, text: 'Le polymère réticulé maintient un <font color="#FFFF00">plateau caoutchoutique</font> nettement' },
  { start: 1685.903, end: 1690.487, text: 'plus élevé aux températures supérieures à cent degrés Celsius.' },
  { start: 1690.607, end: 1695.340, text: 'Cette meilleure tenue thermique s\'explique par la formation de liaisons' },
  { start: 1695.460, end: 1699.777, text: 'covalentes entre les chaînes lors du traitement thermique.' },
  { start: 1699.897, end: 1703.077, text: '' },
  { start: 1703.197, end: 1706.443, text: 'Nous entamons maintenant une nouvelle section,' },
  { start: 1706.563, end: 1713.413, text: 'consacrée à la <font color="#FFFF00">stabilité</font> des latex en écoulement et en formulation.' },
  { start: 1713.533, end: 1716.180, text: 'Elle vise les domaines des matériaux,' },
  { start: 1716.300, end: 1719.817, text: 'de la cosmétique et des sciences agronomiques.' },
  { start: 1719.937, end: 1727.563, text: 'Une frise d\'illustrations présente les mécanismes clés : <font color="#FFFF00">agrégation</font> dendritique,' },
  { start: 1727.683, end: 1736.447, text: '<font color="#FFFF00">floculation</font> anionique ou cationique, <font color="#FFFF00">potentiel zêta</font> et synérèse.' },
  { start: 1736.567, end: 1743.433, text: 'Ces phénomènes physico-chimiques conditionnent le contrôle de la <font color="#FFFF00">rhéologie</font>' },
  { start: 1743.553, end: 1749.403, text: 'et la <font color="#FFFF00">stabilité colloïdale</font> des systèmes en émulsion.' },
  { start: 1749.523, end: 1752.703, text: '' },
  { start: 1752.823, end: 1756.023, text: 'Rappelons d\'abord que la thermodynamique indique' },
  { start: 1756.143, end: 1762.260, text: 'une <font color="#FFFF00">instabilité</font> fondamentale des latex et des émulsions.' },
  { start: 1762.380, end: 1766.580, text: 'Un diagramme énergétique montre que la fragmentation du système' },
  { start: 1766.700, end: 1771.597, text: 'par agitation nécessite un apport d\'énergie élevé, noté Delta E.' },
  { start: 1771.717, end: 1776.677, text: 'Le système tend naturellement vers un état d\'énergie plus bas, E ref,' },
  { start: 1776.797, end: 1781.713, text: 'ce qui rend l\'état dispersé intrinsèquement instable dans le temps.' },
  { start: 1781.833, end: 1786.060, text: 'Plusieurs voies d\'évolution, réversibles ou irréversibles,' },
  { start: 1786.180, end: 1790.673, text: 'sont illustrées : la <font color="#FFFF00">floculation</font>,' },
  { start: 1790.793, end: 1800.133, text: 'la <font color="#FFFF00">sédimentation</font>, le <font color="#FFFF00">crémage</font>, la <font color="#FFFF00">coalescence</font>,' },
  { start: 1800.253, end: 1807.837, text: 'le <font color="#FFFF00">mûrissement d\'Ostwald</font> et l\'<font color="#FFFF00">inversion de phase</font>.' },
  { start: 1807.957, end: 1811.137, text: '' },
  { start: 1811.257, end: 1816.703, text: 'Détaillons ces phénomènes d\'<font color="#FFFF00">instabilité</font> des latex,' },
  { start: 1816.823, end: 1820.607, text: 'classés en processus réversibles et irréversibles.' },
  { start: 1820.727, end: 1827.753, text: 'La partie supérieure rassemble les phénomènes réversibles : le <font color="#FFFF00">crémage</font>,' },
  { start: 1827.873, end: 1834.253, text: 'la <font color="#FFFF00">sédimentation</font> et la <font color="#FFFF00">floculation</font>,' },
  { start: 1834.373, end: 1840.357, text: 'avec une attention particulière portée à la <font color="#FFFF00">déplétion</font>.' },
  { start: 1840.477, end: 1844.657, text: 'La partie inférieure présente les mécanismes irréversibles :' },
  { start: 1844.777, end: 1855.140, text: 'le <font color="#FFFF00">mûrissement d\'Ostwald</font>, la <font color="#FFFF00">coalescence</font> et la <font color="#FFFF00">coagulation</font>.' },
  { start: 1855.260, end: 1859.793, text: 'L\'évolution de ces dégradations irréversibles conduit inévitablement' },
  { start: 1859.913, end: 1864.163, text: 'à une séparation de phases complète du système colloïdal.' },
  { start: 1864.283, end: 1867.463, text: '' },
  { start: 1867.583, end: 1872.563, text: 'Pour contrôler cette <font color="#FFFF00">stabilité</font>, on s\'appuie' },
  { start: 1872.683, end: 1878.933, text: 'sur la <font color="#FFFF00">théorie DLVO</font> appliquée à une dispersion colloïdale.' },
  { start: 1879.053, end: 1881.920, text: 'Le graphique présente l\'énergie potentielle' },
  { start: 1882.040, end: 1884.953, text: 'd\'interaction en fonction de la distance,' },
  { start: 1885.073, end: 1898.370, text: 'avec un <font color="#FFFF00">minimum primaire</font>, un <font color="#FFFF00">minimum</font> <font color="#FFFF00">secondaire</font> et une <font color="#FFFF00">barrière d\'énergie</font>.' },
  { start: 1898.490, end: 1903.403, text: 'Pour éviter l\'agglomération irréversible, il faut augmenter la barrière' },
  { start: 1903.523, end: 1908.287, text: 'd\'énergie, par des mécanismes électrostatiques ou entropiques.' },
  { start: 1908.407, end: 1916.967, text: 'Pour prévenir la <font color="#FFFF00">floculation</font> réversible, notamment par <font color="#FFFF00">déplétion</font>,' },
  { start: 1917.087, end: 1923.403, text: 'il convient de réduire la profondeur du <font color="#FFFF00">minimum secondaire</font>.' },
  { start: 1923.523, end: 1926.703, text: '' },
  { start: 1926.823, end: 1933.003, text: 'Revenons sur les hypothèses fondamentales de la <font color="#FFFF00">théorie DLVO</font>,' },
  { start: 1933.123, end: 1937.467, text: 'développée par Derjaguin, Landau, Verwey et Overbeek.' },
  { start: 1937.587, end: 1942.367, text: 'Le graphique de gauche montre la courbe d\'énergie potentielle totale,' },
  { start: 1942.487, end: 1946.337, text: 'somme des forces répulsives U R et attractives U A.' },
  { start: 1946.457, end: 1951.503, text: 'Les hypothèses stipulent que la surface est rigide et de charge uniforme,' },
  { start: 1951.623, end: 1954.137, text: 'et que le potentiel reste constant,' },
  { start: 1954.257, end: 1958.640, text: 'sans redistribution de charges ni variation de contre-ions.' },
  { start: 1958.760, end: 1963.453, text: 'Enfin, le solvant n\'intervient que par sa constante diélectrique,' },
  { start: 1963.573, end: 1967.490, text: 'sans réaction chimique ni gonflement des particules.' },
  { start: 1967.610, end: 1970.790, text: '' },
  { start: 1970.910, end: 1977.643, text: 'Examinons maintenant la force d\'attraction par <font color="#FFFF00">déplétion</font> et le potentiel' },
  { start: 1977.763, end: 1984.307, text: 'd\'énergie associé, U D, dans le cadre de la <font color="#FFFF00">théorie DLVO</font>.' },
  { start: 1984.427, end: 1987.360, text: 'Le phénomène survient lorsque des particules' },
  { start: 1987.480, end: 1990.013, text: 'de rayon a et des micelles de taille L' },
  { start: 1990.133, end: 1993.133, text: 's\'approchent à une distance interparticulaire' },
  { start: 1993.253, end: 1996.370, text: 'R inférieure à la condition géométrique.' },
  { start: 1996.490, end: 2001.623, text: 'L\'exclusion des micelles de la zone interparticulaire crée un appel osmotique' },
  { start: 2001.743, end: 2007.240, text: 'entropique, qui induit une force d\'attraction nette entre les particules.' },
  { start: 2007.360, end: 2013.427, text: 'Le potentiel de <font color="#FFFF00">déplétion</font> s\'exprime en fonction de la pression' },
  { start: 2013.547, end: 2017.663, text: 'osmotique Pi et des dimensions géométriques du système.' },
  { start: 2017.783, end: 2020.963, text: '' },
  { start: 2021.083, end: 2026.397, text: 'Illustrons la <font color="#FFFF00">déplétion</font> par un exemple concret :' },
  { start: 2026.517, end: 2031.680, text: 'un système de caséine et d\'émulsion d\'huile, selon la concentration.' },
  { start: 2031.800, end: 2036.800, text: 'Un graphique d\'énergie potentielle montre l\'évolution du puits d\'attraction' },
  { start: 2036.920, end: 2040.033, text: 'pour des concentrations en caséine de vingt,' },
  { start: 2040.153, end: 2043.537, text: 'quarante et soixante grammes par kilogramme.' },
  { start: 2043.657, end: 2049.703, text: 'À vingt grammes par kilogramme, la <font color="#FFFF00">pression osmotique</font> reste' },
  { start: 2049.823, end: 2056.120, text: 'faible et la dispersion demeure stable, sans <font color="#FFFF00">agrégation</font>.' },
  { start: 2056.240, end: 2059.487, text: 'À quarante et soixante grammes par kilogramme,' },
  { start: 2059.607, end: 2066.740, text: 'la forte hausse de <font color="#FFFF00">pression</font> <font color="#FFFF00">osmotique</font> approfondit' },
  { start: 2066.860, end: 2072.373, text: 'le <font color="#FFFF00">minimum secondaire</font>, ce qui entraîne la formation' },
  { start: 2072.493, end: 2075.790, text: 'd\'agglomérats, puis d\'un réseau floculé.' },
  { start: 2075.910, end: 2079.090, text: '' },
  { start: 2079.210, end: 2084.943, text: 'Passons à l\'impact de la concentration en <font color="#FFFF00">méthylcellulose</font>' },
  { start: 2085.063, end: 2090.513, text: 'sur la morphologie des <font color="#FFFF00">flocs</font> au sein de latex.' },
  { start: 2090.633, end: 2095.747, text: 'Une grille d\'images microscopiques compare des concentrations croissantes,' },
  { start: 2095.867, end: 2102.917, text: 'de zéro virgule un à zéro virgule quatre pour cent de <font color="#FFFF00">méthylcellulose</font>.' },
  { start: 2103.037, end: 2107.637, text: 'Les trois séries de clichés permettent de visualiser la structuration' },
  { start: 2107.757, end: 2112.520, text: 'du réseau avant séchage, puis après un séchage lent ou rapide.' },
  { start: 2112.640, end: 2117.573, text: 'L\'augmentation de la concentration et la cinétique d\'évaporation modifient' },
  { start: 2117.693, end: 2123.190, text: 'significativement la taille, la cohésion et le motif des agrégats formés.' },
  { start: 2123.310, end: 2126.490, text: '' },
  { start: 2126.610, end: 2130.343, text: 'Intéressons-nous maintenant aux origines de la répulsion' },
  { start: 2130.463, end: 2134.447, text: 'électrostatique à la surface des particules de latex.' },
  { start: 2134.567, end: 2137.500, text: 'Trois mécanismes principaux de stabilisation' },
  { start: 2137.620, end: 2140.670, text: 'de la charge de surface sont présentés.' },
  { start: 2140.790, end: 2146.323, text: 'L\'adsorption de <font color="#FFFF00">tensioactifs</font> anioniques ou cationiques' },
  { start: 2146.443, end: 2150.493, text: 'apporte une charge superficielle négative ou positive.' },
  { start: 2150.613, end: 2157.527, text: 'L\'incorporation de <font color="#FFFF00">comonomères</font> ionogènes greffe directement des charges,' },
  { start: 2157.647, end: 2162.343, text: 'comme des groupements carboxylates, à la surface du polymère.' },
  { start: 2162.463, end: 2165.643, text: '' },
  { start: 2165.763, end: 2171.297, text: 'Poursuivons avec le rôle indispensable des <font color="#FFFF00">comonomères</font>' },
  { start: 2171.417, end: 2175.867, text: 'acides ionomères dans la stabilisation électrique des latex.' },
  { start: 2175.987, end: 2179.387, text: 'La répartition à la surface dépend de la solubilité' },
  { start: 2179.507, end: 2181.907, text: 'relative dans l\'eau et dans la phase' },
  { start: 2182.027, end: 2187.590, text: 'organique, tandis que le pKa et la dissociation influent sur la cinétique.' },
  { start: 2187.710, end: 2190.710, text: 'Un tableau comparatif détaille les propriétés' },
  { start: 2190.830, end: 2193.543, text: 'physiques et chimiques de six acides :' },
  { start: 2193.663, end: 2199.633, text: 'fumarique, maléique, itaconique, méthacrylique, acrylique et crotonique.' },
  { start: 2199.753, end: 2204.067, text: 'L\'acide acrylique s\'impose comme l\'un des meilleurs candidats,' },
  { start: 2204.187, end: 2209.637, text: 'en raison de sa miscibilité dans l\'eau et de sa solubilité dans le toluène.' },
  { start: 2209.757, end: 2212.937, text: '' },
  { start: 2213.057, end: 2216.723, text: 'Voyons à présent l\'expression mathématique du potentiel' },
  { start: 2216.843, end: 2225.253, text: 'de <font color="#FFFF00">répulsion électrostatique</font>, U R, dans la <font color="#FFFF00">théorie DLVO</font>.' },
  { start: 2225.373, end: 2230.867, text: 'Un schéma, à gauche, montre l\'interpénétration et le recouvrement des doubles' },
  { start: 2230.987, end: 2236.483, text: 'couches électriques autour de deux particules de rayon a, distantes de R.' },
  { start: 2236.603, end: 2242.250, text: 'L\'équation exprime l\'énergie potentielle en fonction de la permittivité du milieu,' },
  { start: 2242.370, end: 2249.020, text: 'du potentiel de surface psi zéro et de la <font color="#FFFF00">taille des particules</font>.' },
  { start: 2249.140, end: 2257.520, text: 'Elle fait intervenir la <font color="#FFFF00">longueur</font> <font color="#FFFF00">de Debye</font> lambda, et reste valide' },
  { start: 2257.640, end: 2264.690, text: 'pour un rapport du rayon sur la <font color="#FFFF00">longueur de Debye</font> très supérieur à un.' },
  { start: 2264.810, end: 2267.990, text: '' },
  { start: 2268.110, end: 2272.110, text: 'Cela met en lumière l\'importance de l\'épaisseur de la double' },
  { start: 2272.230, end: 2282.773, text: 'couche électrique, ou <font color="#FFFF00">longueur</font> <font color="#FFFF00">de Debye</font>, pour la <font color="#FFFF00">stabilité</font>.' },
  { start: 2282.893, end: 2285.740, text: 'À droite, un schéma représente la couche' },
  { start: 2285.860, end: 2289.573, text: 'rigide de Stern et la couche diffuse de Gouy-Chapman,' },
  { start: 2289.693, end: 2296.677, text: 'avec la décroissance du potentiel électrique jusqu\'au <font color="#FFFF00">potentiel zêta</font>.' },
  { start: 2296.797, end: 2300.863, text: 'L\'équation exprime la décroissance exponentielle du potentiel' },
  { start: 2300.983, end: 2306.167, text: 'électrique psi de x en fonction de la distance x et du paramètre kappa.' },
  { start: 2306.287, end: 2311.220, text: 'Le graphique de gauche montre que la réduction de l\'épaisseur de la double' },
  { start: 2311.340, end: 2320.970, text: 'couche abaisse la <font color="#FFFF00">barrière d\'énergie</font> Phi max, ce qui favorise la <font color="#FFFF00">floculation</font>.' },
  { start: 2321.090, end: 2324.270, text: '' },
  { start: 2324.390, end: 2327.990, text: 'Voyons comment la présence d\'ions écrante la répulsion' },
  { start: 2328.110, end: 2334.540, text: 'électrostatique, en réduisant la <font color="#FFFF00">longueur de Debye</font> lambda.' },
  { start: 2334.660, end: 2336.927, text: 'La formule générale exprime lambda' },
  { start: 2337.047, end: 2340.740, text: 'en fonction de la permittivité, de la température,' },
  { start: 2340.860, end: 2345.510, text: 'ainsi que de la charge et de la concentration des ions opposés.' },
  { start: 2345.630, end: 2349.943, text: 'Pour un sel monovalent dans l\'eau à vingt-cinq degrés Celsius,' },
  { start: 2350.063, end: 2355.693, text: 'l\'expression se simplifie : zéro virgule trois divisé par la racine de c i.' },
  { start: 2355.813, end: 2365.440, text: 'Un tableau illustre l\'effet de la <font color="#FFFF00">force</font> <font color="#FFFF00">ionique</font> : plus la concentration augmente,' },
  { start: 2365.560, end: 2371.457, text: 'plus l\'épaisseur de la double couche diminue fortement, de cent à un nanomètre.' },
  { start: 2371.577, end: 2374.757, text: '' },
  { start: 2374.877, end: 2378.143, text: 'Étudions maintenant l\'effet de l\'ajout de cations' },
  { start: 2378.263, end: 2386.740, text: 'divalents <font color="#FFFF00">calcium</font>, Ca 2 plus, sur la <font color="#FFFF00">stabilité</font> des latex.' },
  { start: 2386.860, end: 2391.087, text: 'Trois états du système sont schématisés : le latex stable,' },
  { start: 2391.207, end: 2395.657, text: 'la formation de coagulats et la gélification des particules.' },
  { start: 2395.777, end: 2398.443, text: 'Deux images au microscope montrent qu\'en' },
  { start: 2398.563, end: 2405.877, text: 'présence de chlorure de <font color="#FFFF00">calcium</font> sans <font color="#FFFF00">tensioactif</font>,' },
  { start: 2405.997, end: 2412.357, text: 'le latex coagule, alors qu\'avec dix pour cent de <font color="#FFFF00">tensioactif</font>,' },
  { start: 2412.477, end: 2414.727, text: 'la dispersion reste stable.' },
  { start: 2414.847, end: 2418.407, text: 'Des paramètres extérieurs, comme la température,' },
  { start: 2418.527, end: 2423.507, text: 'l\'agitation et la présence de <font color="#FFFF00">tensioactifs</font>,' },
  { start: 2423.627, end: 2430.010, text: 'influent fortement sur le type et la cinétique d\'<font color="#FFFF00">agrégation</font>.' },
  { start: 2430.130, end: 2433.310, text: '' },
  { start: 2433.430, end: 2441.297, text: 'Un <font color="#FFFF00">diagramme de phase</font> illustre ensuite la <font color="#FFFF00">stabilité</font> du latex' },
  { start: 2441.417, end: 2448.513, text: 'en présence de cations <font color="#FFFF00">calcium</font>, selon la teneur en acide de surface.' },
  { start: 2448.633, end: 2454.500, text: 'Le graphique rapporte le pourcentage de chlorure de <font color="#FFFF00">calcium</font>' },
  { start: 2454.620, end: 2460.450, text: 'en fonction du taux de groupes acides, exprimé en microéquivalents par gramme.' },
  { start: 2460.570, end: 2465.663, text: 'Trois domaines sont identifiés : une zone de gel à faible taux d\'acide,' },
  { start: 2465.783, end: 2473.280, text: 'une zone intermédiaire de coagulats ou grumeaux, et une zone de <font color="#FFFF00">stabilité</font>.' },
  { start: 2473.400, end: 2477.667, text: 'L\'augmentation de la densité d\'acide à la surface des particules' },
  { start: 2477.787, end: 2484.503, text: 'élargit le domaine de <font color="#FFFF00">stabilité</font> face à l\'ajout de sels divalents.' },
  { start: 2484.623, end: 2487.803, text: '' },
  { start: 2487.923, end: 2492.990, text: 'Ajoutons maintenant l\'influence conjointe du <font color="#FFFF00">pH</font>' },
  { start: 2493.110, end: 2501.493, text: 'et de la concentration en <font color="#FFFF00">calcium</font> sur la <font color="#FFFF00">stabilité</font> des latex.' },
  { start: 2501.613, end: 2508.373, text: 'Un diagramme trace la concentration en <font color="#FFFF00">calcium</font>, en moles par litre,' },
  { start: 2508.493, end: 2515.457, text: 'en fonction du <font color="#FFFF00">pH</font>, et définit différentes régions d\'état physique.' },
  { start: 2515.577, end: 2519.957, text: 'À faible concentration en <font color="#FFFF00">calcium</font>,' },
  { start: 2520.077, end: 2523.970, text: 'le système reste stable ; à des valeurs plus élevées,' },
  { start: 2524.090, end: 2528.737, text: 'et selon le <font color="#FFFF00">pH</font>, apparaissent des zones' },
  { start: 2528.857, end: 2532.620, text: 'métastables, de gel ou de grumeaux inhabituels.' },
  { start: 2532.740, end: 2543.187, text: 'À <font color="#FFFF00">pH</font> acide et forte teneur en <font color="#FFFF00">calcium</font>, une <font color="#FFFF00">floculation</font> suivie d\'une' },
  { start: 2543.307, end: 2548.223, text: 'réorganisation homogène permet une fluidification de la suspension.' },
  { start: 2548.343, end: 2551.523, text: '' },
  { start: 2551.643, end: 2554.890, text: 'Nous abordons maintenant une nouvelle section,' },
  { start: 2555.010, end: 2559.860, text: 'intitulée « Protection des latex par rapport à leur application ».' },
  { start: 2559.980, end: 2563.847, text: 'Elle annonce le traitement des mécanismes de stabilisation' },
  { start: 2563.967, end: 2568.797, text: 'et de protection colloïdale, d\'origine osmotique et électrique.' },
  { start: 2568.917, end: 2576.057, text: 'Une frise visuelle, en bas de page, rappelle les notions d\'<font color="#FFFF00">agrégation</font>,' },
  { start: 2576.177, end: 2584.607, text: 'de <font color="#FFFF00">potentiel zêta</font>, de contrôle rhéologique et de <font color="#FFFF00">déplétion</font>.' },
  { start: 2584.727, end: 2588.727, text: 'Ce chapitre traite de l\'ajustement des propriétés de surface' },
  { start: 2588.847, end: 2594.030, text: 'pour adapter le comportement du latex aux contraintes de l\'application.' },
  { start: 2594.150, end: 2597.330, text: '' },
  { start: 2597.450, end: 2603.430, text: 'Revenons sur les origines de la <font color="#FFFF00">répulsion électrostatique</font>,' },
  { start: 2603.550, end: 2607.400, text: 'cette fois sous l\'angle de la protection des latex.' },
  { start: 2607.520, end: 2613.967, text: 'Trois voies de charge de surface sont illustrées : le <font color="#FFFF00">tensioactif</font>' },
  { start: 2614.087, end: 2622.783, text: 'anionique, le <font color="#FFFF00">tensioactif</font> cationique et le <font color="#FFFF00">comonomère</font> ionogène.' },
  { start: 2622.903, end: 2628.683, text: 'L\'adsorption de <font color="#FFFF00">tensioactifs</font> offre une charge amovible,' },
  { start: 2628.803, end: 2636.653, text: 'tandis que l\'incorporation de <font color="#FFFF00">comonomères</font> crée des charges covalentes permanentes.' },
  { start: 2636.773, end: 2642.773, text: 'Ces mécanismes conditionnent la <font color="#FFFF00">stabilité</font> de la double couche' },
  { start: 2642.893, end: 2647.410, text: 'électrique lors du stockage et des procédés de mise en œuvre.' },
  { start: 2647.530, end: 2650.710, text: '' },
  { start: 2650.830, end: 2656.747, text: 'Voyons maintenant le rôle des macromolécules à la surface des particules de latex.' },
  { start: 2656.867, end: 2661.200, text: 'Deux représentations de particules entourées de chaînes polymères' },
  { start: 2661.320, end: 2665.970, text: 'illustrent les différentes méthodes de modification de surface.' },
  { start: 2666.090, end: 2673.337, text: 'À gauche, la couche macromoléculaire provient de l\'adsorption de <font color="#FFFF00">tensioactifs</font>' },
  { start: 2673.457, end: 2677.907, text: 'non ioniques ou du greffage chimique d\'alcool polyvinylique.' },
  { start: 2678.027, end: 2685.207, text: 'À droite, la <font color="#FFFF00">stabilisation</font> <font color="#FFFF00">stérique</font> est obtenue' },
  { start: 2685.327, end: 2689.840, text: 'grâce à des <font color="#FFFF00">comonomères</font> spécifiques,' },
  { start: 2689.960, end: 2695.077, text: 'tels que des macromères de polyoxyéthylène ou d\'esters méthacryliques.' },
  { start: 2695.197, end: 2698.377, text: '' },
  { start: 2698.497, end: 2706.677, text: 'Détaillons à présent la <font color="#FFFF00">stabilisation</font> <font color="#FFFF00">stérique</font>, à travers deux' },
  { start: 2706.797, end: 2715.427, text: 'contributions : l\'<font color="#FFFF00">effet osmotique</font> et la <font color="#FFFF00">restriction de volume</font>.' },
  { start: 2715.547, end: 2722.613, text: 'L\'<font color="#FFFF00">effet osmotique</font> génère une surconcentration locale en polymère dans la zone' },
  { start: 2722.733, end: 2728.297, text: 'd\'interaction, provoquant un appel de solvant qui repousse les particules.' },
  { start: 2728.417, end: 2734.883, text: 'La <font color="#FFFF00">restriction de volume</font> induit une perte d\'entropie de conformation' },
  { start: 2735.003, end: 2740.500, text: 'des macromolécules hydrophiles, et crée des forces élastiques répulsives.' },
  { start: 2740.620, end: 2745.533, text: 'L\'énergie libre de <font color="#FFFF00">stabilisation stérique</font>,' },
  { start: 2745.653, end: 2748.680, text: 'Delta G ST, combine le terme de mélange,' },
  { start: 2748.800, end: 2753.610, text: 'Delta G M, et le terme de restriction volumique, Delta G RV.' },
  { start: 2753.730, end: 2756.910, text: '' },
  { start: 2757.030, end: 2759.897, text: 'Faisons le point avec un tableau comparatif' },
  { start: 2760.017, end: 2763.150, text: 'des avantages et inconvénients des trois grands' },
  { start: 2763.270, end: 2767.097, text: 'modes de stabilisation colloïdale : électrostatique,' },
  { start: 2767.217, end: 2772.200, text: 'osmotique et par <font color="#FFFF00">restriction de volume</font>.' },
  { start: 2772.320, end: 2775.453, text: 'La stabilisation électrostatique est insensible' },
  { start: 2775.573, end: 2779.553, text: 'aux variations de température et à la qualité du solvant,' },
  { start: 2779.673, end: 2785.323, text: 'mais son point faible majeur est une extrême sensibilité à la présence d\'ions.' },
  { start: 2785.443, end: 2788.377, text: 'La stabilisation osmotique n\'est affectée ni' },
  { start: 2788.497, end: 2793.477, text: 'par la <font color="#FFFF00">force ionique</font> ni par la température,' },
  { start: 2793.597, end: 2796.663, text: 'mais elle est vulnérable au choix des solvants' },
  { start: 2796.783, end: 2801.967, text: 'et à la compétition avec les <font color="#FFFF00">tensioactifs</font>.' },
  { start: 2802.087, end: 2807.467, text: 'Enfin, la stabilisation par <font color="#FFFF00">restriction de volume</font>' },
  { start: 2807.587, end: 2811.367, text: 'est insensible aux ions comme à la qualité du solvant,' },
  { start: 2811.487, end: 2814.687, text: 'mais subit l\'influence directe de la température' },
  { start: 2814.807, end: 2817.590, text: 'et des contraintes de cisaillement.' },
  { start: 2817.710, end: 2820.890, text: '' },
  { start: 2821.010, end: 2825.677, text: 'Passons maintenant au modèle d\'<font color="#FFFF00">agrégation</font>' },
  { start: 2825.797, end: 2831.093, text: 'd\'amas limitée par la diffusion, ou <font color="#FFFF00">DLCA</font>.' },
  { start: 2831.213, end: 2834.393, text: 'Dans ce processus, la croissance des agrégats' },
  { start: 2834.513, end: 2837.760, text: 'est contrôlée par la diffusion des particules,' },
  { start: 2837.880, end: 2842.130, text: 'et s\'effectue par collision d\'amas de tailles similaires.' },
  { start: 2842.250, end: 2845.450, text: 'Cette cinétique d\'association par paires conduit' },
  { start: 2845.570, end: 2850.020, text: 'à des structures dont la distribution de taille est étroite.' },
  { start: 2850.140, end: 2854.787, text: 'L\'amas fractal formé suit la loi d\'échelle M égale R g puissance d,' },
  { start: 2854.907, end: 2861.023, text: 'avec une <font color="#FFFF00">dimension fractale</font> d d\'environ un virgule huit.' },
  { start: 2861.143, end: 2864.323, text: '' },
  { start: 2864.443, end: 2874.273, text: 'Poursuivons avec le régime d\'<font color="#FFFF00">agrégation</font> d\'amas limitée par la réaction, ou <font color="#FFFF00">RLCA</font>.' },
  { start: 2874.393, end: 2879.773, text: 'L\'<font color="#FFFF00">agrégation</font> n\'est plus limitée par la diffusion,' },
  { start: 2879.893, end: 2885.143, text: 'mais par la cinétique du processus chimique ou physique d\'agglomération.' },
  { start: 2885.263, end: 2890.997, text: 'La probabilité de franchissement de la <font color="#FFFF00">barrière d\'énergie</font>' },
  { start: 2891.117, end: 2895.167, text: 'E b suit une loi exponentielle de moins E b sur k B T.' },
  { start: 2895.287, end: 2900.287, text: 'Ce régime conduit à une distribution de taille plus large et à des agrégats' },
  { start: 2900.407, end: 2907.503, text: 'plus compacts, de <font color="#FFFF00">dimension fractale</font> d proche de deux virgule trois.' },
  { start: 2907.504, end: 2910.000, text: 'Merci pour votre attention. Allez au chapitre 3.' },


];

const SUBTITLES_EN_CH2 = [
{ start: 1.000, end: 2.000, text: 'Welcome to the BRIDGE programme -<font color="#FFFF00"> Bridging Research and Inclusive Digital Education</font>' },

  { start: 2.001, end: 2.621, text: 'Welcome to' },
  { start: 2.741, end: 5.479, text: 'module two of this presentation, focusing on' },
  { start: 5.599, end: 9.058, text: 'the key properties of emulsion polymers and latexes.' },
  { start: 9.178, end: 13.813, text: 'This course is presented by Gérard Bacquet for the company SciencExpert.' },
  { start: 13.933, end: 15.906, text: '' },
  { start: 16.026, end: 20.765, text: 'Let\'s start with the phenomenon of <font color="#FFFF00">filmification</font>,' },
  { start: 20.885, end: 25.579, text: 'essential for all applications where the formation of a film is required.' },
  { start: 25.699, end: 27.758, text: 'A series of illustrations shows the' },
  { start: 27.878, end: 29.910, text: 'process, from stacking spherical' },
  { start: 30.030, end: 33.665, text: 'particles to deforming them into polyhedral structures.' },
  { start: 33.785, end: 40.112, text: 'The diagrams also detail the <font color="#FFFF00">evaporation</font> <font color="#FFFF00">water</font>,' },
  { start: 40.232, end: 48.808, text: 'the <font color="#FFFF00">capillary forces</font> and the <font color="#FFFF00">coalescence</font> of polymer chains at the particle scale.' },
  { start: 48.928, end: 50.902, text: '' },
  { start: 51.022, end: 54.963, text: 'Let\'s now see the successive stages of transforming latex particles' },
  { start: 55.083, end: 58.542, text: 'into a <font color="#FFFF00">continuous film</font>.' },
  { start: 58.662, end: 66.812, text: 'It all starts with the <font color="#FFFF00">evaporation of</font> <font color="#FFFF00">water</font> and its absorption by the support,' },
  { start: 66.932, end: 70.685, text: 'which brings the particles together into a compact stack.' },
  { start: 70.805, end: 76.661, text: 'Under the action of <font color="#FFFF00">forces</font> <font color="#FFFF00">capillaries</font>,' },
  { start: 76.781, end: 81.416, text: 'the spheres gradually deform and adopt a polyhedral honeycomb structure.' },
  { start: 81.536, end: 88.333, text: 'Finally, the <font color="#FFFF00">interdiffusion</font> of the polymer chains at the interfaces ensures complete' },
  { start: 88.453, end: 95.794, text: '<font color="#FFFF00">coalescence</font> and the formation of the final <font color="#FFFF00">homogeneous film</font>.' },
  { start: 95.914, end: 98.064, text: 'Pause 5 seconds, change of slide' },
  { start: 98.184, end: 104.778, text: 'To describe this drying, we rely on the <font color="#FFFF00">Croll model</font>, which distinguishes three' },
  { start: 104.898, end: 109.534, text: 'phases in the drying speed of a <font color="#FFFF00">latex film</font>.' },
  { start: 109.654, end: 113.130, text: 'During phase one, a porous layer forms on the surface,' },
  { start: 113.250, end: 118.297, text: 'above a more concentrated transition layer and a wet layer that remains intact.' },
  { start: 118.417, end: 121.776, text: 'In phase two, the initial wet layer has disappeared,' },
  { start: 121.896, end: 124.543, text: 'and the remaining <font color="#FFFF00">water' },
  { start: 124.663, end: 128.592, text: 'evaporation</font> comes directly from the transition layer.' },
  { start: 128.712, end: 132.306, text: 'In phase three, the transition layer disappears in turn:' },
  { start: 132.426, end: 138.474, text: 'the film is then completely dry and ready for the <font color="#FFFF00">coalescence</font> step.' },
  { start: 138.594, end: 140.567, text: '' },
  { start: 140.687, end: 143.452, text: 'This model has been validated theoretically and' },
  { start: 143.572, end: 147.122, text: 'kinetically, for phases one and two of evaporation.' },
  { start: 147.242, end: 152.456, text: 'A graph, on the left, shows the evolution of the solid volume fraction over time,' },
  { start: 152.576, end: 154.506, text: 'divided into three phases.' },
  { start: 154.626, end: 155.599, text: 'For phase one,' },
  { start: 155.719, end: 162.387, text: 'the rate of water loss is constant: it depends only on the evaporation surface and the evaporative flux.' },
  { start: 162.507, end: 165.422, text: 'For phase two, the kinetics depend on the water' },
  { start: 165.542, end: 168.339, text: 'concentration at the surface, which gradually' },
  { start: 168.459, end: 172.153, text: 'reduces the drying rate as a function of film thickness.' },
  { start: 172.273, end: 174.246, text: '' },
  { start: 174.366, end: 177.516, text: 'Now let\'s look at phase three of drying, focused on' },
  { start: 177.636, end: 181.095, text: 'particle deformation and ejection of residual water.' },
  { start: 181.215, end: 186.601, text: '<font color="#FFFF00">capillary forces</font> favor the deformation of elastic particles,' },
  { start: 186.721, end: 189.591, text: 'while internal elastic stresses oppose it.' },
  { start: 189.711, end: 194.482, text: 'A diagram, top left, shows the difference in <font color="#FFFF00">capillary' },
  { start: 194.602, end: 199.355, text: 'pressure</font> created by water menisci between contacting latex spheres.' },
  { start: 199.475, end: 201.122, text: 'A table summarizes the <font' },
  { start: 201.242, end: 203.948, text: 'color="#FFFF00">capillary pressure</font> as a' },
  { start: 204.068, end: 206.950, text: 'function of the particle radius and the number of' },
  { start: 207.070, end: 212.032, text: 'spheres in contact: the pressures are very high for the smallest particles.' },
  { start: 212.152, end: 214.125, text: '' },
  { start: 214.245, end: 216.775, text: 'This distortion was observed in thesis work' },
  { start: 216.895, end: 220.915, text: 'by François Magnin, supported at the University of Paris 6.' },
  { start: 221.035, end: 224.100, text: 'They relate to morphology, at different scales,' },
  { start: 224.220, end: 226.914, text: 'of bidisperse latex films after drying.' },
  { start: 227.034, end: 231.799, text: 'An atomic force microscopy image shows the deformation of the spherical particles' },
  { start: 231.919, end: 236.319, text: 'into a network of polyhedral cells measuring two hundred nanometers.' },
  { start: 236.439, end: 238.589, text: 'Pause 5 seconds, change of slide' },
  { start: 238.709, end: 244.388, text: 'Let\'s return to the modeling of the mechanical balance of phase three, between deforming <font' },
  { start: 244.508, end: 249.202, text: 'color="#FFFF00">capillary forces</font> and opposing elastic constraints.' },
  { start: 249.322, end: 254.708, text: 'The <font color="#FFFF00">capillary force</font> promotes deformation, while the response' },
  { start: 254.828, end: 260.992, text: 'The elasticity of particles is described by the <font color="#FFFF00">Hertz contact theory</font>.' },
  { start: 261.112, end: 264.262, text: 'To obtain <font color="#FFFF00">coalescence</font>,' },
  { start: 264.382, end: 271.135, text: 'the <font color="#FFFF00">capillary force</font> must prevail over the mechanical resistance of the polymer.' },
  { start: 271.255, end: 273.844, text: 'The final criterion indicates that the <font' },
  { start: 273.964, end: 277.258, text: 'color="#FFFF00">shear modulus</font> of the polymer must' },
  { start: 277.378, end: 280.469, text: 'remain below a limiting value, proportional to the' },
  { start: 280.589, end: 285.518, text: 'interfacial tension and inversely proportional to the radius of the particle.' },
  { start: 285.638, end: 287.612, text: '' },
  { start: 287.732, end: 294.646, text: 'This brings us to the <font color="#FFFF00">temperature</font> <font color="#FFFF00">minimum film formation</font>,' },
  { start: 294.766, end: 299.578, text: 'key parameter of latex <font color="#FFFF00">coalescence</font> conditions.' },
  { start: 299.698, end: 303.142, text: 'On a vertical thermal bench, the film is transparent and' },
  { start: 303.262, end: 306.556, text: 'perfectly <font color="#FFFF00">coalesced</font> at high' },
  { start: 306.676, end: 311.344, text: 'temperatures, while at low temperatures it becomes opaque and powdery.' },
  { start: 311.464, end: 316.849, text: '<font color="#FFFF00">coalescence</font> is only possible if particles and water coexist,' },
  { start: 316.969, end: 322.016, text: 'and if the <font color="#FFFF00">shear modulus</font> remains sufficiently low.' },
  { start: 322.136, end: 328.522, text: 'If the drying temperature is lower than the minimum <font color="#FFFF00">film forming temperature</font>,' },
  { start: 328.642, end: 332.748, text: 'the film cannot <font color="#FFFF00">coalesce</font> properly.' },
  { start: 332.868, end: 334.841, text: '' },
  { start: 334.961, end: 340.314, text: 'Let\'s now see the influence of the <font color="#FFFF00">particle size</font> on this <font' },
  { start: 340.434, end: 345.952, text: 'color="#FFFF00">minimum temperature</font> <font color="#FFFF00">film formation</font>.' },
  { start: 346.072, end: 351.784, text: 'A first graph, on the left, shows the drop in the <font color="#FFFF00">shear modulus</font>' },
  { start: 351.904, end: 357.348, text: 'at the <font color="#FFFF00">glassy transition</font>, which marks the transition from the' },
  { start: 357.468, end: 363.279, text: '<font color="#FFFF00">glassy state</font> to the <font color="#FFFF00">rubbery state</font>.' },
  { start: 363.399, end: 368.229, text: 'A second graph, on the right, illustrates the increase in minimum temperature' },
  { start: 368.349, end: 372.734, text: 'of <font color="#FFFF00">film formation</font> with the particle radius,' },
  { start: 372.854, end: 376.078, text: 'from thirty to one hundred and fifty nanometers.' },
  { start: 376.198, end: 379.433, text: 'Vials demonstrate that a smaller particle size promotes' },
  { start: 379.553, end: 382.435, text: '<font color="#FFFF00">coalescence</font> at lower' },
  { start: 382.555, end: 387.458, text: 'temperatures, by increasing <font color="#FFFF00">capillary forces</font>.' },
  { start: 387.578, end: 389.552, text: '' },
  { start: 389.672, end: 392.881, text: 'We now open a new section, devoted to the mechanical' },
  { start: 393.001, end: 395.989, text: 'properties of emulsion polymers and latexes.' },
  { start: 396.109, end: 403.174, text: 'These properties concern <font color="#FFFF00">composite</font> materials and many industrial applications: paints,' },
  { start: 403.294, end: 405.314, text: 'paper, textiles or glues.' },
  { start: 405.434, end: 408.616, text: 'An illustrated frieze, at the bottom of the page,' },
  { start: 408.736, end: 413.842, text: 'recalls the microstructural stages of deformation and organization of particles.' },
  { start: 413.962, end: 415.936, text: '' },
  { start: 416.056, end: 420.265, text: 'Let\'s start with the physical states of the polymer, according to its' },
  { start: 420.385, end: 424.079, text: '<font color="#FFFF00">molar mass</font> and temperature.' },
  { start: 424.199, end: 427.761, text: 'A first <font color="#FFFF00">phase diagram</font>, on the' },
  { start: 427.881, end: 431.148, text: 'left, combines the temperature and the weight average' },
  { start: 431.268, end: 435.615, text: 'molar mass, and delimits the glassy zones, rubbery and liquid.' },
  { start: 435.735, end: 437.741, text: 'A second graph, on the right,' },
  { start: 437.861, end: 444.894, text: 'shows the drop in the <font color="#FFFF00">module of</font> <font color="#FFFF00">Young</font> with the temperature,' },
  { start: 445.014, end: 453.328, text: 'from the transition from the <font color="#FFFF00">glassy state</font> to the <font color="#FFFF00">rubber state</font>, then fluid.' },
  { start: 453.448, end: 458.042, text: 'At low temperatures, the polymer has a high and constant elastic modulus:' },
  { start: 458.162, end: 461.739, text: 'this is the <font color="#FFFF00">glassy state</font>.' },
  { start: 461.859, end: 465.362, text: 'Beyond the <font color="#FFFF00">glass transition</font>,' },
  { start: 465.482, end: 474.117, text: 'the <font color="#FFFF00">rubber plate</font> has modulus values ​​between ten to the power of four and ten to the power of six megapascals.' },
  { start: 474.237, end: 478.537, text: 'At higher temperatures, a final transition leads to the fluid state,' },
  { start: 478.657, end: 482.586, text: 'described by specific pseudo-plastic rheological properties.' },
  { start: 482.706, end: 484.680, text: '' },
  { start: 484.800, end: 489.741, text: 'Let us now see the effect of the main variables on the <font color="#FFFF00">thermo-' },
  { start: 489.861, end: 493.379, text: 'viscoelastic behavior</font> of statistical polymers.' },
  { start: 493.499, end: 501.119, text: 'A graph represents the evolution of the <font color="#FFFF00">elastic modulus</font> of the latex as a function of temperature,' },
  { start: 501.239, end: 506.169, text: 'for different formulations of <font color="#FFFF00">styrene-butadiene</font>.' },
  { start: 506.289, end: 511.112, text: 'The <font color="#FFFF00">Young\'s modulus</font> can be modulated by adjusting the' },
  { start: 511.232, end: 518.841, text: '<font color="#FFFF00">glass transition temperature</font>, thanks to the ratio of <font color="#FFFF00">monomers</font>.' },
  { start: 518.961, end: 528.464, text: 'The level of the <font color="#FFFF00">rubber plate</font> depends on the <font color="#FFFF00">molar mass</font> or the <font color="#FFFF00">gel rate</font>,' },
  { start: 528.584, end: 532.161, text: 'here compared for rates of thirty and seventy percent.' },
  { start: 532.281, end: 534.254, text: '' },
  { start: 534.374, end: 540.139, text: 'Let us now compare the experimentalcurves of <font color="#FFFF00">viscoelasticity</font> with the' },
  { start: 540.259, end: 545.071, text: 'mechanical models of Maxwell and <font color="#FFFF00">Voigt-Kelvin</font>.' },
  { start: 545.191, end: 550.549, text: 'The top diagrams illustrate the <font color="#FFFF00">Maxwell model</font>, in series,' },
  { start: 550.669, end: 554.114, text: 'and the <font color="#FFFF00">Voigt-Kelvin model</font>,' },
  { start: 554.234, end: 558.313, text: 'in parallel, to describe the elastic and viscous components.' },
  { start: 558.433, end: 562.054, text: 'On the left, the plot of <font color="#FFFF00">preservation' },
  { start: 562.174, end: 565.526, text: 'modulus</font> G\' versus temperature shows the transition' },
  { start: 565.646, end: 568.705, text: 'between the <font color="#FFFF00">state</font> <font' },
  { start: 568.825, end: 573.755, text: 'color="#FFFF00">glassy</font> and the rubbery plateau for different polymers.' },
  { start: 573.875, end: 579.378, text: 'On the right, the <font color="#FFFF00">module</font> <font color="#FFFF00">loss</font> G\'\'' },
  { start: 579.498, end: 586.604, text: 'graph highlights the energy dissipation peaks characteristic of the <font color="#FFFF00">glass transition</font>.' },
  { start: 586.724, end: 588.697, text: '' },
  { start: 588.817, end: 592.673, text: 'Let\'s move on to the <font color="#FFFF00">Fox equation</font>,' },
  { start: 592.793, end: 604.075, text: 'which makes it possible to calculate the theoretical <font color="#FFFF00">transition temperature</font> <font color="#FFFF00">glassy</font> of a <font color="#FFFF00">copolymer</font>.' },
  { start: 604.195, end: 613.698, text: 'It expresses the inverse of the overall <font color="#FFFF00">Tg</font> as the weighted sum of the mass fractions of each <font color="#FFFF00">monomer</font>,' },
  { start: 613.818, end: 618.336, text: 'divided by their respective <font color="#FFFF00">Tg</font> in Kelvin.' },
  { start: 618.456, end: 621.515, text: 'A table summarizes the glass transition temperatures' },
  { start: 621.635, end: 622.988, text: 'of various common <font' },
  { start: 623.108, end: 628.375, text: 'color="#FFFF00">homopolymers</font>, from polybutadiene to minus one hundred and twelve' },
  { start: 628.495, end: 632.248, text: 'degrees to PMMA at one hundred and eight degrees Celsius.' },
  { start: 632.368, end: 634.342, text: '' },
  { start: 634.462, end: 638.376, text: 'Now let\'s face this equation with reality: here are the data for' },
  { start: 638.496, end: 639.496, text: 'ninety-nine <font' },
  { start: 639.616, end: 645.343, text: 'color="#FFFF00">styrene-butadiene</font> latexes, compared to the theoretical Fox curve.' },
  { start: 645.463, end: 650.345, text: 'The graph presents the <font color="#FFFF00">glass transition temperature</font> as' },
  { start: 650.465, end: 656.218, text: 'a function of the mass percentage of styrene in the <font color="#FFFF00">copolymer</font>.' },
  { start: 656.338, end: 660.221, text: 'The formula applied to the mass fractions of butadiene and styrene' },
  { start: 660.341, end: 664.211, text: 'allows the theoretical trend line to be precisely adjusted.' },
  { start: 664.331, end: 667.834, text: 'Experimental points, from various processes and producers' },
  { start: 667.954, end: 671.563, text: 'industrial, show very good agreement with the model.' },
  { start: 671.683, end: 673.833, text: 'Pause 5 seconds, change of slide' },
  { start: 673.953, end: 680.306, text: 'Let\'s then look at the impact of the <font color="#FFFF00">Keesom forces</font> and the dipole moment of the' },
  { start: 680.426, end: 685.591, text: 'secondary bonds on the <font color="#FFFF00">glass transition temperature</font>.' },
  { start: 685.711, end: 692.096, text: 'A table presents the increase in the <font color="#FFFF00">Tg</font> according to the substituted pattern,' },
  { start: 692.216, end: 699.145, text: 'from polyethylene at minus one hundred and ten degrees to PTFE at one hundred and twenty-three degrees Celsius.' },
  { start: 699.265, end: 702.036, text: 'A graph, bottom left, shows the increasing' },
  { start: 702.156, end: 708.803, text: 'correlation between the <font color="#FFFF00">temperature of</font> <font color="#FFFF00">glass transition</font>' },
  { start: 708.923, end: 713.708, text: 'and the <font color="#FFFF00">dipolar moment</font>, expressed in Debye.' },
  { start: 713.828, end: 718.887, text: 'The formula for the interaction energy of Keesom confirms that strengthening secondary' },
  { start: 719.007, end: 724.348, text: 'dipolar bonds directly increases the <font color="#FFFF00">Tg</font> of the polymer.' },
  { start: 724.468, end: 726.618, text: 'Pause 5 seconds, change of slide' },
  { start: 726.738, end: 732.562, text: 'Let\'s now see the influence of thermal transitions on <font color="#FFFF00">thermoformed</font> and' },
  { start: 732.682, end: 737.552, text: '<font color="#FFFF00">composite</font> materials based on SB and SBAn latex.' },
  { start: 737.672, end: 739.849, text: 'A graph compares the evolution of the' },
  { start: 739.969, end: 742.439, text: 'shear modulus as a function of temperature' },
  { start: 742.559, end: 750.254, text: 'for <font color="#FFFF00">styrene-butadiene</font> and <font color="#FFFF00">styrene-butadiene-acrylonitrile</font> systems.' },
  { start: 750.374, end: 758.171, text: 'The addition of <font color="#FFFF00">acrylonitrile</font> modifies the transition slope and widens the mechanical softening zone,' },
  { start: 758.291, end: 761.279, text: 'thanks to the polar interactions introduced.' },
  { start: 761.399, end: 766.340, text: 'Final application examples show <font color="#FFFF00">thermoformed</font> decorative' },
  { start: 766.460, end: 770.978, text: 'panels and structured textile elements for automotive interior design.' },
  { start: 771.098, end: 773.071, text: '' },
  { start: 773.191, end: 776.929, text: 'Let\'s now look at the pigment concentration by volume, called' },
  { start: 777.049, end: 780.658, text: '<font color="#FFFF00">CVP</font>, or PVC in English.' },
  { start: 780.778, end: 786.105, text: 'Its formula defines it as the ratio between the combined volume of pigments and fillers,' },
  { start: 786.225, end: 788.448, text: 'and the total volume of solids.' },
  { start: 788.568, end: 795.130, text: 'Three diagrams illustrate the formulation regimes according to the critical <font color="#FFFF00">CVP</font>,' },
  { start: 795.250, end: 798.826, text: 'depending on the presence or absence of excess binder.' },
  { start: 798.946, end: 803.155, text: 'When the <font color="#FFFF00">CVP</font> exceeds the critical value,' },
  { start: 803.275, end: 807.014, text: 'the quantity of binder becomes insufficient, which causes the' },
  { start: 807.134, end: 812.239, text: 'appearance of <font color="#FFFF00">porosities</font> and voids within the film.' },
  { start: 812.359, end: 814.333, text: '' },
  { start: 814.453, end: 825.368, text: 'This <font color="#FFFF00">porosity</font> leads us to the <font color="#FFFF00">module</font> <font color="#FFFF00">de Young</font> of porous <font color="#FFFF00">composites</font>,' },
  { start: 825.488, end: 832.829, text: 'a subject that is once again widely studied with the emergence of <font color="#FFFF00">additive manufacturing</font>.' },
  { start: 832.949, end: 837.184, text: 'A graph compares several theoretical models describing the drop in <font' },
  { start: 837.304, end: 843.645, text: 'color="#FFFF00">elastic modulus</font> as a function of volume <font color="#FFFF00">porosity</font>.' },
  { start: 843.765, end: 851.824, text: 'The <font color="#FFFF00">Bert model</font> expresses the ratio of the modules as a function of the <font color="#FFFF00">porosity</font>' },
  { start: 851.944, end: 858.024, text: 'relative, the maximum <font color="#FFFF00">porosity</font> and a stress concentration factor.' },
  { start: 858.144, end: 860.849, text: 'This K factor varies depending on the geometry' },
  { start: 860.969, end: 863.825, text: 'of the inclusions: zero point seventy-five for' },
  { start: 863.945, end: 867.201, text: 'flat particles like clay, and two for spheres.' },
  { start: 867.321, end: 869.295, text: '' },
  { start: 869.415, end: 874.238, text: 'Let\'s apply these notions of <font color="#FFFF00">porosity</font> and rigidity to' },
  { start: 874.358, end: 878.438, text: 'a practical case: <font color="#FFFF00">coated paper</font>.' },
  { start: 878.558, end: 884.152, text: 'A first graph, on the left, shows the polynomial decrease of the relative modulus E\' on E\'' },
  { start: 884.272, end: 889.142, text: 'zero as a function of the fraction of <font color="#FFFF00">porosity</font>.' },
  { start: 889.262, end: 897.059, text: 'A table summarizes the evolution of the <font color="#FFFF00">porosity</font> and the <font color="#FFFF00">Young\'s moduli</font>,' },
  { start: 897.179, end: 902.259, text: 'glassy and rubbery, according to the rate of polystyrene and latex particles.' },
  { start: 902.379, end: 906.032, text: 'The main graph, on the right, confirms the drop in glassy' },
  { start: 906.152, end: 908.916, text: 'moduli E\'v and rubber moduli E\'c when the <font' },
  { start: 909.036, end: 914.201, text: 'color="#FFFF00">porosity</font> increases from twenty-five to thirty-one percent.' },
  { start: 914.321, end: 919.359, text: 'Two vignettes, at the bottom, link the Taber rigidity to the weight deposited,' },
  { start: 919.479, end: 925.644, text: 'as well as to the <font color="#FFFF00">porosity</font> measured by optical density with the inks.' },
  { start: 925.764, end: 927.738, text: 'Pause 5 seconds, slide change' },
  { start: 927.858, end: 930.034, text: 'Let\'s now see the mechanical behavior' },
  { start: 930.154, end: 934.554, text: '<font color="#FFFF00">composite</font> materials containing polymer.' },
  { start: 934.674, end: 938.615, text: 'A comparative table shows that the <font color="#FFFF00">transition' },
  { start: 938.735, end: 942.324, text: 'temperature</font> <font color="#FFFF00">glassy</font> of the' },
  { start: 942.444, end: 946.652, text: 'composite remains the same as that of latex alone, although its <font' },
  { start: 946.772, end: 951.761, text: 'color="#FFFF00">modulus</font> <font color="#FFFF00">elastic</font> is higher.' },
  { start: 951.881, end: 955.234, text: 'A dynamic mechanical analysis graph illustrates the <font' },
  { start: 955.354, end: 959.504, text: 'color="#FFFF00">Young\'s modulus curves for three formulations, <font' },
  { start: 959.624, end: 965.174, text: 'color="#FFFF00">Tg</font> minus thirty, minus twelve and minus three degrees Celsius.' },
  { start: 965.294, end: 973.294, text: 'The text emphasizes that <font color="#FFFF00">composites</font> formulated with a polymer retain the same <font color="#FFFF00">thermo-' },
  { start: 973.414, end: 977.225, text: 'viscoelastic properties</font> as the constituent polymer.' },
  { start: 977.345, end: 979.495, text: 'Pause 5 seconds, change of slide' },
  { start: 979.615, end: 983.851, text: 'Let\'s change subject to define the notions of adhesive failure and <font' },
  { start: 983.971, end: 988.462, text: 'color="#FFFF00">cohesive failure</font>, in the field of adhesives.' },
  { start: 988.582, end: 994.705, text: 'On the left, when the internal cohesion of the polymer is greater than the adhesion to the surface,' },
  { start: 994.825, end: 1000.787, text: 'the rupture occurs at the interface: it is an <font color="#FFFF00">adhesive rupture</font>.' },
  { start: 1000.907, end: 1003.939, text: 'On the right, if the adhesion between the polymer' },
  { start: 1004.059, end: 1007.268, text: 'and the surface exceeds the cohesion of the polymer,' },
  { start: 1007.388, end: 1013.997, text: 'the rupture occurs at the heart of the material : it\'s a <font color="#FFFF00">cohesive rupture</font>.' },
  { start: 1014.117, end: 1016.470, text: 'Diagrams illustrate these two mechanical' },
  { start: 1016.590, end: 1019.519, text: 'failure modes between two solid substrates.' },
  { start: 1019.639, end: 1021.613, text: '' },
  { start: 1021.733, end: 1026.883, text: 'Let\'s now look at the effect of the rigidity of the polymer, represented by its <font' },
  { start: 1027.003, end: 1032.141, text: 'color="#FFFF00">Tg</font>, on the <font color="#FFFF00">rupture energy</font>.' },
  { start: 1032.261, end: 1038.091, text: 'The first graph, on the left, indicates that the <font color="#FFFF00">breakdown energy</font>' },
  { start: 1038.211, end: 1045.846, text: 'adhesive decreases as the <font color="#FFFF00">temperature</font> <font color="#FFFF00">glass transition</font> increases.' },
  { start: 1045.966, end: 1047.736, text: 'The second, on the right,' },
  { start: 1047.856, end: 1058.080, text: 'shows on the contrary an increase in the <font color="#FFFF00">energy of</font> <font color="#FFFF00">rupture</font> cohesive with the <font color="#FFFF00">Tg</font>.' },
  { start: 1058.200, end: 1065.526, text: 'The bottom graph superimposes these two mechanisms and highlights an optimum <font color="#FFFF00">adhesion energy</font>,' },
  { start: 1065.646, end: 1069.223, text: 'at the point of intersection of the two failure modes.' },
  { start: 1069.343, end: 1071.316, text: '' },
  { start: 1071.436, end: 1075.907, text: 'Let\'s continue with the effect of <font color="#FFFF00">carboxylation</font>' },
  { start: 1076.027, end: 1080.530, text: 'of latex on the cohesion of the <font color="#FFFF00">coated paper</font>,' },
  { start: 1080.650, end: 1087.168, text: 'depending on the <font color="#FFFF00">temperature</font> <font color="#FFFF00">glass transition</font>.' },
  { start: 1087.288, end: 1091.908, text: 'A graph represents dry peel strength versus <font color="#FFFF00">Tg</font>,' },
  { start: 1092.028, end: 1096.369, text: 'for different levels of <font color="#FFFF00">carboxylation</font>.' },
  { start: 1096.489, end: 1103.228, text: 'Increased <font color="#FFFF00">carboxylation</font> improves the cohesion of the paper when the latex is rigid,' },
  { start: 1103.348, end: 1110.780, text: 'that is to say in the zone of <font color="#FFFF00">adhesive failure</font>, at high <font color="#FFFF00">Tg</font>.' },
  { start: 1110.900, end: 1118.526, text: 'On the other hand, at low <font color="#FFFF00">Tg</font>, in the domain of <font color="#FFFF00">cohesive rupture</font>,' },
  { start: 1118.646, end: 1124.811, text: '<font color="#FFFF00">carboxylation</font> has no significant effect on the cohesion of the paper.' },
  { start: 1124.931, end: 1126.905, text: '' },
  { start: 1127.025, end: 1131.907, text: 'Let\'s then see the effect of <font color="#FFFF00">particle size</font> of latex in' },
  { start: 1132.027, end: 1135.839, text: 'the case of <font color="#FFFF00">adhesive failure</font>.' },
  { start: 1135.959, end: 1139.638, text: 'Two comparative diagrams show that the larger the particles,' },
  { start: 1139.758, end: 1144.570, text: 'the more the contact surface between the polymer and the pigment decreases.' },
  { start: 1144.690, end: 1147.808, text: 'The graph on the left illustrates the decay of energy' },
  { start: 1147.928, end: 1154.269, text: 'adhesion when the <font color="#FFFF00">size</font> <font color="#FFFF00">particles</font> increases.' },
  { start: 1154.389, end: 1158.395, text: 'This relationship, inversely proportional to particle diameter,' },
  { start: 1158.515, end: 1161.974, text: 'governs mechanical strength during adhesive failure.' },
  { start: 1162.094, end: 1164.244, text: 'Pause 5 seconds, change of slide' },
  { start: 1164.364, end: 1171.422, text: 'Here is now the transition from a <font color="#FFFF00">rupture</font> <font color="#FFFF00">cohesive</font> to an <font' },
  { start: 1171.542, end: 1180.595, text: 'color="#FFFF00">adhesive rupture</font>, by <font color="#FFFF00">plasticization</font> of the interface, especially in the presence of water.' },
  { start: 1180.715, end: 1185.218, text: 'When dry, the strong acid-base interactions between the carboxylate groups' },
  { start: 1185.338, end: 1191.947, text: 'and the pigment ensure high adhesion, which leads to a <font color="#FFFF00">cohesive breakdown</font>.' },
  { start: 1192.067, end: 1197.452, text: 'In a humid environment, the presence of water molecules at the interface weakens adhesion' },
  { start: 1197.572, end: 1202.266, text: 'and causes a transition to <font color="#FFFF00">adhesive failure</font>.' },
  { start: 1202.386, end: 1206.772, text: 'The bottom graph compares the energy levels in dry and wet environments,' },
  { start: 1206.892, end: 1211.056, text: 'and highlights the overall energy drop due to interface effects.' },
  { start: 1211.176, end: 1213.150, text: '' },
  { start: 1213.270, end: 1217.949, text: 'Let\'s now introduce the equivalence between temperature and speed of loading,' },
  { start: 1218.069, end: 1223.058, text: 'according to the theory of <font color="#FFFF00">Williams-Landel-Ferry</font>.' },
  { start: 1223.178, end: 1225.472, text: 'A plot of <font color="#FFFF00">Young\'s' },
  { start: 1225.592, end: 1228.474, text: 'modulus</font> versus temperature shows the shift' },
  { start: 1228.594, end: 1230.771, text: 'of the glass transition toward higher' },
  { start: 1230.891, end: 1235.467, text: 'temperatures as the frequency increases from one to ten thousand hertz.' },
  { start: 1235.587, end: 1240.234, text: 'The equation expresses the <font color="#FFFF00">Tg</font> at a given frequency' },
  { start: 1240.354, end: 1245.931, text: 'as a logarithmic function of the ratio between this frequency and a reference frequency.' },
  { start: 1246.051, end: 1249.730, text: 'The coefficient k is close to ten for conventional polymers,' },
  { start: 1249.850, end: 1254.721, text: 'such as <font color="#FFFF00">styrene-butadiene</font> systems or acrylates.' },
  { start: 1254.841, end: 1256.814, text: '' },
  { start: 1256.934, end: 1259.640, text: 'Now let\'s combine temperature and frequency to' },
  { start: 1259.760, end: 1262.689, text: 'describe the physical state of the polymer.' },
  { start: 1262.809, end: 1268.168, text: 'A schematic diagram divides the behavior into three zones: a high-modulus rigid state,' },
  { start: 1268.288, end: 1273.721, text: 'an intermediate state, and a low-modulus <font color="#FFFF00">rubber state</font>.' },
  { start: 1273.841, end: 1279.702, text: 'The text, on the right, recalls the importance of precisely defining the environment of use,' },
  { start: 1279.822, end: 1284.666, text: 'in terms of temperature and frequency, to design the appropriate polymer.' },
  { start: 1284.786, end: 1287.551, text: 'The question asked at the bottom invites you to' },
  { start: 1287.671, end: 1291.189, text: 'explicitly determine these two application variables.' },
  { start: 1291.309, end: 1293.282, text: '' },
  { start: 1293.402, end: 1299.835, text: 'Let\'s look at a practical application: designing latex for <font color="#FFFF00">rotogravure</font>.' },
  { start: 1299.955, end: 1302.869, text: 'On the left, illustrations and a sectional view' },
  { start: 1302.989, end: 1305.754, text: 'using a scanning electron microscope on a <font' },
  { start: 1305.874, end: 1308.815, text: 'color="#FFFF00">rotogravure paper</font> highlight' },
  { start: 1308.935, end: 1312.806, text: 'the phenomenon of missing dots on the surface of the print.' },
  { start: 1312.926, end: 1316.396, text: 'Diagrams of the printing process show how the lack of local' },
  { start: 1316.516, end: 1321.211, text: 'compressibility prevents perfect transfer of ink from the cylinder cells.' },
  { start: 1321.331, end: 1324.095, text: 'The graph on the right shows the improvement in' },
  { start: 1324.215, end: 1327.424, text: 'printability with the percentage of butadiene, which' },
  { start: 1327.544, end: 1331.885, text: 'increases the flexibility and dynamic compressibility of the latex.' },
  { start: 1332.005, end: 1333.979, text: '' },
  { start: 1334.099, end: 1336.837, text: 'Now for the intelligent emulsion, with <font' },
  { start: 1336.957, end: 1341.004, text: 'color="#FFFF00">crosslinking</font> stimulated by temperature.' },
  { start: 1341.124, end: 1343.804, text: 'The top diagrams show the stages of drying,' },
  { start: 1343.924, end: 1350.441, text: 'from <font color="#FFFF00">water evaporation</font> to the hexagonal deformation of the latex particles.' },
  { start: 1350.561, end: 1352.502, text: 'Zooms highlight distinct reactive' },
  { start: 1352.622, end: 1354.949, text: 'functionalities, such as hydroxyl and' },
  { start: 1355.069, end: 1358.619, text: 'epoxide groups, carried by complementary particles.' },
  { start: 1358.739, end: 1367.006, text: 'The bottom graph shows the increase in <font color="#FFFF00">molar mass</font> and <font color="#FFFF00">gel rate</font> with temperature,' },
  { start: 1367.126, end: 1373.794, text: 'beyond the <font color="#FFFF00">Tg</font>, sign of effective <font color="#FFFF00">crosslinking</font>.' },
  { start: 1373.914, end: 1375.888, text: '' },
  { start: 1376.008, end: 1381.066, text: 'Let\'s see what effect this stimulated <font color="#FFFF00">crosslinking</font> has on' },
  { start: 1381.186, end: 1385.822, text: 'the <font color="#FFFF00">viscoelastic</font> properties of the polymer.' },
  { start: 1385.942, end: 1392.412, text: 'A graph compares the <font color="#FFFF00">module</font> <font color="#FFFF00">elastic</font> as a function of' },
  { start: 1392.532, end: 1399.521, text: 'temperature for a standard polymer and for a polymer with stimulated <font color="#FFFF00">cross-linking</font>.' },
  { start: 1399.641, end: 1404.699, text: 'The cross-linked polymer maintains a significantly higher <font color="#FFFF00">rubber' },
  { start: 1404.819, end: 1409.043, text: 'plateau</font> at temperatures above one hundred degrees Celsius.' },
  { start: 1409.163, end: 1413.222, text: 'This better thermal resistance is explained by the formation of bonds' },
  { start: 1413.342, end: 1416.683, text: 'covalent between the chains during heat treatment.' },
  { start: 1416.803, end: 1418.953, text: 'Pause 5 seconds, change of slide' },
  { start: 1419.073, end: 1422.046, text: 'We now begin a new section, devoted to the <font' },
  { start: 1422.166, end: 1426.566, text: 'color="#FFFF00">stability</font> of latexes in flow and formulation.' },
  { start: 1426.686, end: 1428.895, text: 'It targets the fields of materials,' },
  { start: 1429.015, end: 1431.533, text: 'cosmetics and agricultural sciences.' },
  { start: 1431.653, end: 1438.188, text: 'A frieze of illustrations presents the key mechanisms: dendritic <font color="#FFFF00">aggregation</font>,' },
  { start: 1438.308, end: 1445.976, text: '<font color="#FFFF00">flocculation</font> anionic or cationic, <font color="#FFFF00">zeta potential</font> and syneresis.' },
  { start: 1446.096, end: 1451.625, text: 'These physicochemical phenomena condition the control of <font color="#FFFF00">rheology</font>' },
  { start: 1451.745, end: 1456.675, text: 'and the <font color="#FFFF00">colloidal stability</font> of emulsion systems.' },
  { start: 1456.795, end: 1458.768, text: '' },
  { start: 1458.888, end: 1462.947, text: 'Let us first recall that thermodynamics indicates a fundamental <font' },
  { start: 1463.067, end: 1466.996, text: 'color="#FFFF00">instability</font> of latexes and emulsions.' },
  { start: 1467.116, end: 1470.646, text: 'An energy diagram shows that the fragmentation of the system' },
  { start: 1470.766, end: 1474.669, text: 'by agitation requires a high energy input, noted Delta E.' },
  { start: 1474.789, end: 1478.795, text: 'The system naturally tends towards a lower energy state, E ref,' },
  { start: 1478.915, end: 1483.138, text: 'which makes the dispersed state intrinsically unstable over time.' },
  { start: 1483.258, end: 1487.944, text: 'Several paths of evolution, reversible or irreversible, are illustrated:' },
  { start: 1488.064, end: 1490.684, text: '<font color="#FFFF00">flocculation</font>,' },
  { start: 1490.804, end: 1498.548, text: '<font color="#FFFF00">sedimentation</font>, <font color="#FFFF00">creaming</font>, <font color="#FFFF00">coalescence</font>,' },
  { start: 1498.668, end: 1504.656, text: '<font color="#FFFF00">Ostwald ripening</font> and <font color="#FFFF00">phase inversion</font>.' },
  { start: 1504.776, end: 1506.750, text: '' },
  { start: 1506.870, end: 1511.105, text: 'Let\'s detail these <font color="#FFFF00">instability</font> phenomena of' },
  { start: 1511.225, end: 1515.481, text: 'latexes, classified into reversible and irreversible processes.' },
  { start: 1515.601, end: 1521.489, text: 'The upper part brings together the reversible phenomena: <font color="#FFFF00">creaming</font>,' },
  { start: 1521.609, end: 1526.995, text: '<font color="#FFFF00">sedimentation</font> and <font color="#FFFF00">flocculation</font>,' },
  { start: 1527.115, end: 1531.809, text: 'with particular attention paid to <font color="#FFFF00">depletion</font>.' },
  { start: 1531.929, end: 1538.052, text: 'The lower part presents the irreversible mechanisms: <font color="#FFFF00">Ostwald ripening</font>,' },
  { start: 1538.172, end: 1543.631, text: '<font color="#FFFF00">coalescence</font> and <font color="#FFFF00">coagulation</font>.' },
  { start: 1543.751, end: 1547.575, text: 'The evolution of these irreversible degradations inevitably leads' },
  { start: 1547.695, end: 1551.330, text: 'to a complete phase separation of the colloidal system.' },
  { start: 1551.450, end: 1553.424, text: '' },
  { start: 1553.544, end: 1558.164, text: 'To control this <font color="#FFFF00">stability</font>, we rely on the <font' },
  { start: 1558.284, end: 1562.743, text: 'color="#FFFF00">DLVO theory</font> applied to a colloidal dispersion.' },
  { start: 1562.863, end: 1564.981, text: 'The graph shows the potential energy' },
  { start: 1565.101, end: 1567.662, text: 'of interaction depending on the distance,' },
  { start: 1567.782, end: 1578.979, text: 'with a <font color="#FFFF00">primary minimum</font>, a <font color="#FFFF00">minimum</font> <font color="#FFFF00">secondary</font> and a <font color="#FFFF00">energy barrier</font>.' },
  { start: 1579.099, end: 1584.341, text: 'To avoid irreversible agglomeration, it is necessary to increase the energy barrier,' },
  { start: 1584.461, end: 1587.214, text: 'by electrostatic or entropic mechanisms.' },
  { start: 1587.334, end: 1594.751, text: 'To prevent reversible <font color="#FFFF00">flocculation</font>, in particular by <font color="#FFFF00">depletion</font>,' },
  { start: 1594.871, end: 1600.095, text: 'the depth of the <font color="#FFFF00">secondary minimum</font> should be reduced.' },
  { start: 1600.215, end: 1602.188, text: '' },
  { start: 1602.308, end: 1607.811, text: 'Let\'s return to the fundamental hypotheses of the <font color="#FFFF00">DLVO theory</font>,' },
  { start: 1607.931, end: 1611.690, text: 'developed by Derjaguin, Landau, Verwey and Overbeek.' },
  { start: 1611.810, end: 1615.548, text: 'The graph on the left shows the total potential energy curve,' },
  { start: 1615.668, end: 1619.068, text: 'sum of the repulsive forces U R and attractive U A.' },
  { start: 1619.188, end: 1622.424, text: 'The assumptions stipulate that the surface is rigid and' },
  { start: 1622.544, end: 1626.314, text: 'uniformly charged, and that the potential remains constant,' },
  { start: 1626.434, end: 1630.481, text: 'without redistribution of charges or variation of counterions.' },
  { start: 1630.601, end: 1634.960, text: 'Finally, the solvent only intervenes through its dielectric constant,' },
  { start: 1635.080, end: 1638.715, text: 'without chemical reaction or swelling of the particles.' },
  { start: 1638.835, end: 1640.809, text: '' },
  { start: 1640.929, end: 1646.870, text: 'Let\'s now examine the force of attraction by <font color="#FFFF00">depletion</font> and the potential' },
  { start: 1646.990, end: 1653.161, text: 'associated energy, U D, within the framework of the <font color="#FFFF00">DLVO theory</font>.' },
  { start: 1653.281, end: 1655.398, text: 'The phenomenon occurs when particles' },
  { start: 1655.518, end: 1657.518, text: 'of radius a and micelles of size L' },
  { start: 1657.638, end: 1659.285, text: 'approach at an interparticle' },
  { start: 1659.405, end: 1662.452, text: 'distance R less than the geometric condition.' },
  { start: 1662.572, end: 1667.840, text: 'The exclusion of micelles from the interparticle zone creates an entropic osmotic call,' },
  { start: 1667.960, end: 1671.595, text: 'which induces a net attractive force between particles.' },
  { start: 1671.715, end: 1676.362, text: 'The <font color="#FFFF00">depletion potential</font> is expressed as a function' },
  { start: 1676.482, end: 1681.000, text: 'of the osmotic pressure Pi and the geometric dimensions of the system.' },
  { start: 1681.120, end: 1683.094, text: '' },
  { start: 1683.214, end: 1688.069, text: 'Let\'s illustrate <font color="#FFFF00">depletion</font> with a concrete example:' },
  { start: 1688.189, end: 1692.328, text: 'a casein and oil emulsion system, depending on concentration.' },
  { start: 1692.448, end: 1695.212, text: 'A potential energy graph shows the evolution of' },
  { start: 1695.332, end: 1697.274, text: 'the well of attraction for casein' },
  { start: 1697.394, end: 1701.532, text: 'concentrations of twenty, forty and sixty grams per kilogram.' },
  { start: 1701.652, end: 1709.364, text: 'At twenty grams per kilogram, the <font color="#FFFF00">osmotic pressure</font> remains low and the dispersion remains stable,' },
  { start: 1709.484, end: 1712.766, text: 'without <font color="#FFFF00">aggregation</font>.' },
  { start: 1712.886, end: 1716.683, text: 'At forty and sixty grams per kilogram, the sharp rise in <font' },
  { start: 1716.803, end: 1720.803, text: 'color="#FFFF00">pressure</font> <font color="#FFFF00">osmotic</font>' },
  { start: 1720.923, end: 1726.132, text: 'deepens the <font color="#FFFF00">secondary minimum</font>, resulting in the formation' },
  { start: 1726.252, end: 1729.214, text: 'agglomerates, then a flocculated network.' },
  { start: 1729.334, end: 1731.484, text: 'Pause 5 seconds, change of slide' },
  { start: 1731.604, end: 1737.251, text: 'Let\'s move on to the impact of the concentration of <font color="#FFFF00">methylcellulose</font>' },
  { start: 1737.371, end: 1741.829, text: 'on the morphology of <font color="#FFFF00">flocs</font> within latex.' },
  { start: 1741.949, end: 1745.864, text: 'A grid of microscopic images compares increasing concentrations,' },
  { start: 1745.984, end: 1751.972, text: 'from zero point one to zero point four percent of <font color="#FFFF00">methylcellulose</font>.' },
  { start: 1752.092, end: 1758.125, text: 'The three series of images make it possible to visualize the structure of the network before drying,' },
  { start: 1758.245, end: 1760.527, text: 'then after slow or rapid drying.' },
  { start: 1760.647, end: 1764.647, text: 'The increase in concentration and the kinetics of evaporation modify' },
  { start: 1764.767, end: 1769.435, text: 'significantly the size, cohesion and pattern of the aggregates formed.' },
  { start: 1769.555, end: 1771.528, text: '' },
  { start: 1771.648, end: 1774.354, text: 'Let\'s now look at the origins of electrostatic' },
  { start: 1774.474, end: 1777.462, text: 'repulsion on the surface of latex particles.' },
  { start: 1777.582, end: 1779.876, text: 'Three main surface charge stabilization' },
  { start: 1779.996, end: 1781.867, text: 'mechanisms are presented.' },
  { start: 1781.987, end: 1786.575, text: 'The adsorption of anionic or cationic <font color="#FFFF00">surfactants</font>' },
  { start: 1786.695, end: 1789.860, text: 'provides a negative or positive surface charge.' },
  { start: 1789.980, end: 1795.718, text: 'The incorporation of ionogenic <font color="#FFFF00">comonomers</font> directly grafts charges,' },
  { start: 1795.838, end: 1799.800, text: 'such as carboxylate groups, on the surface of the polymer.' },
  { start: 1799.920, end: 1801.894, text: '' },
  { start: 1802.014, end: 1806.837, text: 'Let us continue with the essential role of <font color="#FFFF00">comonomers</font>' },
  { start: 1806.957, end: 1810.828, text: 'ionomeric acids in the electrical stabilization of latexes.' },
  { start: 1810.948, end: 1813.771, text: 'The surface distribution depends on the relative' },
  { start: 1813.891, end: 1816.688, text: 'solubility in water and in the organic phase,' },
  { start: 1816.808, end: 1820.149, text: 'while pKa and dissociation influence the kinetics.' },
  { start: 1820.269, end: 1822.858, text: 'A comparative table details the physical and' },
  { start: 1822.978, end: 1825.748, text: 'chemical properties of six acids: fumaric,' },
  { start: 1825.868, end: 1829.777, text: 'maleic, itaconic, methacrylic, acrylic and crotonic.' },
  { start: 1829.897, end: 1833.224, text: 'Acrylic acid stands out as one of the best candidates,' },
  { start: 1833.344, end: 1837.391, text: 'due to its miscibility in water and its solubility in toluene.' },
  { start: 1837.511, end: 1839.484, text: '' },
  { start: 1839.604, end: 1846.401, text: 'Let us now see the mathematical expression of the <font color="#FFFF00">electrostatic repulsion potential</font>,' },
  { start: 1846.521, end: 1850.189, text: 'U R, in the <font color="#FFFF00">DLVO theory</font>.' },
  { start: 1850.309, end: 1854.668, text: 'A diagram, on the left, shows the interpenetration and overlapping of' },
  { start: 1854.788, end: 1859.573, text: 'electric double layers around two particles of radius a, separated by R.' },
  { start: 1859.693, end: 1865.255, text: 'The equation expresses the potential energy as a function of the permittivity of the medium,' },
  { start: 1865.375, end: 1870.807, text: 'the zero psi surface potential, and the <font color="#FFFF00">particle size</font>.' },
  { start: 1870.927, end: 1877.665, text: 'It involves the <font color="#FFFF00">length</font> <font color="#FFFF00">Debye</font> lambda, and remains valid' },
  { start: 1877.785, end: 1883.891, text: 'for a ratio of the radius to the <font color="#FFFF00">Debye length</font> much greater than one.' },
  { start: 1884.011, end: 1885.985, text: '' },
  { start: 1886.105, end: 1891.431, text: 'This highlights the importance of the thickness of the electrical double layer, or <font' },
  { start: 1891.551, end: 1898.513, text: 'color="#FFFF00">length</font> <font color="#FFFF00">Debye</font>, for <font color="#FFFF00">stability</font>.' },
  { start: 1898.633, end: 1902.312, text: 'On the right, a diagram represents the rigid Stern layer and' },
  { start: 1902.432, end: 1906.229, text: 'the diffuse Gouy-Chapman layer, with the decay of the electric' },
  { start: 1906.349, end: 1910.514, text: 'potential up to the <font color="#FFFF00">zeta potential</font>.' },
  { start: 1910.634, end: 1914.222, text: 'The equation expresses the exponential decay of the potential' },
  { start: 1914.342, end: 1919.213, text: 'electrical psi of x as a function of the distance x and the kappa parameter.' },
  { start: 1919.333, end: 1927.659, text: 'The graph on the left shows that reducing the thickness of the double layer lowers the <font color="#FFFF00">energy barrier</font> Phi max,' },
  { start: 1927.779, end: 1931.532, text: 'which promotes <font color="#FFFF00">flocculation</font>.' },
  { start: 1931.652, end: 1933.626, text: '' },
  { start: 1933.746, end: 1938.014, text: 'Let\'s see how the presence of ions screens electrostatic repulsion, by' },
  { start: 1938.134, end: 1942.181, text: 'reducing the <font color="#FFFF00">Debye length</font> lambda.' },
  { start: 1942.301, end: 1944.712, text: 'The general formula expresses lambda as a' },
  { start: 1944.832, end: 1947.838, text: 'function of permittivity, temperature, as well' },
  { start: 1947.958, end: 1951.476, text: 'as the charge and concentration of the opposite ions.' },
  { start: 1951.596, end: 1955.393, text: 'For a monovalent salt in water at twenty-five degrees Celsius,' },
  { start: 1955.513, end: 1960.239, text: 'the expression simplifies: zero point three divided by the root of c i.' },
  { start: 1960.359, end: 1969.012, text: 'A table illustrates the effect of <font color="#FFFF00">force</font> <font color="#FFFF00">ionic</font>: the more the concentration increases,' },
  { start: 1969.132, end: 1975.329, text: 'the more the thickness of the double layer decreases sharply, from one hundred to one nanometer.' },
  { start: 1975.449, end: 1977.423, text: '' },
  { start: 1977.543, end: 1983.046, text: 'Let\'s now study the effect of adding divalent cations <font color="#FFFF00">calcium</font>,' },
  { start: 1983.166, end: 1987.716, text: 'Ca 2 plus, on the <font color="#FFFF00">stability</font> of latexes.' },
  { start: 1987.836, end: 1991.489, text: 'Three states of the system are schematized: stable latex,' },
  { start: 1991.609, end: 1995.421, text: 'the formation of coagulates and the gelation of particles.' },
  { start: 1995.541, end: 1998.835, text: 'Two microscope images show that in the presence of <font' },
  { start: 1998.955, end: 2002.072, text: 'color="#FFFF00">calcium chloride</font> without <font' },
  { start: 2002.192, end: 2006.257, text: 'color="#FFFF00">surfactant</font>, the latex coagulates, whereas' },
  { start: 2006.377, end: 2012.280, text: 'with ten percent of <font color="#FFFF00">surfactant</font>, the dispersion remains stable.' },
  { start: 2012.400, end: 2016.171, text: 'External parameters, such as temperature, agitation and the' },
  { start: 2016.291, end: 2020.088, text: 'presence of <font color="#FFFF00">surfactants</font>, strongly' },
  { start: 2020.208, end: 2025.078, text: 'influence the type and kinetics of <font color="#FFFF00">aggregation</font>.' },
  { start: 2025.198, end: 2027.172, text: '' },
  { start: 2027.292, end: 2033.409, text: 'A <font color="#FFFF00">phase diagram</font> then illustrates the <font color="#FFFF00">stability</font>' },
  { start: 2033.529, end: 2040.903, text: 'of the latex in the presence of <font color="#FFFF00">calcium</font> cations, depending on the surface acid content.' },
  { start: 2041.023, end: 2048.408, text: 'The graph reports the percentage of <font color="#FFFF00">calcium</font> chloride as a function of the rate of acid groups,' },
  { start: 2048.528, end: 2051.222, text: 'expressed in microequivalents per gram.' },
  { start: 2051.342, end: 2055.407, text: 'Three areas are identified: a zone of gel with low acid content,' },
  { start: 2055.527, end: 2061.842, text: 'an intermediate zone of coagulates or lumps, and a zone of <font color="#FFFF00">stability</font>.' },
  { start: 2061.962, end: 2065.021, text: 'The increase in acid density on the particle surface' },
  { start: 2065.141, end: 2071.894, text: 'broadens the range of <font color="#FFFF00">stability</font> when faced with the addition of divalent salts.' },
  { start: 2072.014, end: 2074.164, text: 'Pause 5 seconds, change of slide' },
  { start: 2074.284, end: 2080.107, text: 'Let\'s now add the joint influence of <font color="#FFFF00">pH</font> and the concentration of <font' },
  { start: 2080.227, end: 2085.804, text: 'color="#FFFF00">calcium</font> on the <font color="#FFFF00">stability</font> of latexes.' },
  { start: 2085.924, end: 2091.341, text: 'A diagram plots <font color="#FFFF00">calcium</font> concentration, in moles per liter,' },
  { start: 2091.461, end: 2097.011, text: 'versus <font color="#FFFF00">pH</font>, and defines different physical state regions.' },
  { start: 2097.131, end: 2100.869, text: 'At low concentration of <font color="#FFFF00">calcium</font>,' },
  { start: 2100.989, end: 2103.878, text: 'the system remains stable; at higher values,' },
  { start: 2103.998, end: 2107.265, text: 'and depending on the <font color="#FFFF00">pH</font>,' },
  { start: 2107.385, end: 2110.641, text: 'metastable areas, gel or unusual lumps appear.' },
  { start: 2110.761, end: 2116.558, text: 'At acidic <font color="#FFFF00">pH</font> and high <font color="#FFFF00">calcium</font> content,' },
  { start: 2116.678, end: 2124.196, text: '<font color="#FFFF00">flocculation</font> followed by homogeneous reorganization allows fluidification of the suspension.' },
  { start: 2124.316, end: 2126.466, text: 'Pause 5 seconds, change of slide' },
  { start: 2126.586, end: 2129.442, text: 'We are now approaching a new section, entitled' },
  { start: 2129.562, end: 2133.315, text: '“Protection of latexes in relation to their application”.' },
  { start: 2133.435, end: 2138.291, text: 'It announces the treatment of stabilization and colloidal protection mechanisms,' },
  { start: 2138.411, end: 2140.752, text: 'of osmotic and electrical origin.' },
  { start: 2140.872, end: 2147.675, text: 'A visual frieze, at the bottom of the page, recalls the notions of <font color="#FFFF00">aggregation</font>,' },
  { start: 2147.795, end: 2154.698, text: '<font color="#FFFF00">zeta potential</font>, rheological control and <font color="#FFFF00">depletion</font>.' },
  { start: 2154.818, end: 2158.288, text: 'This chapter covers the adjustment of surface properties to' },
  { start: 2158.408, end: 2162.926, text: 'adapt the behavior of the latex to the constraints of the application.' },
  { start: 2163.046, end: 2165.019, text: '' },
  { start: 2165.139, end: 2169.022, text: 'Let\'s return to the origins of <font color="#FFFF00">electrostatic' },
  { start: 2169.142, end: 2173.398, text: 'repulsion</font>, this time from the angle of latex protection.' },
  { start: 2173.518, end: 2178.726, text: 'Three surface charge pathways are illustrated: <font color="#FFFF00">surfactant</font>' },
  { start: 2178.846, end: 2186.396, text: 'anionic, the cationic <font color="#FFFF00">surfactant</font> and the ionogenic <font color="#FFFF00">comonomer</font>.' },
  { start: 2186.516, end: 2191.549, text: 'Adsorption of <font color="#FFFF00">surfactants</font> provides a removable charge,' },
  { start: 2191.669, end: 2197.834, text: 'while incorporation of <font color="#FFFF00">comonomers</font> creates permanent covalent charges.' },
  { start: 2197.954, end: 2202.189, text: 'These mechanisms determine the <font color="#FFFF00">stability</font> of' },
  { start: 2202.309, end: 2206.944, text: 'the electrical double layer during storage and implementation processes.' },
  { start: 2207.064, end: 2208.979, text: 'Pause 5 seconds,change slide' },
  { start: 2209.099, end: 2214.146, text: 'Let\'s now look at the role of macromolecules on the surface of latex particles.' },
  { start: 2214.266, end: 2217.854, text: 'Two representations of particles surrounded by polymer chains' },
  { start: 2217.974, end: 2221.551, text: 'illustrate the different surface modification methods.' },
  { start: 2221.671, end: 2226.585, text: 'On the left, the macromolecular layer comes from the adsorption of nonionic <font' },
  { start: 2226.705, end: 2232.164, text: 'color="#FFFF00">surfactants</font> or from the chemical grafting of polyvinyl alcohol.' },
  { start: 2232.284, end: 2236.081, text: 'On the right, <font color="#FFFF00">stabilization</font> <font' },
  { start: 2236.201, end: 2239.848, text: 'color="#FFFF00">steric</font> is achieved using specific <font' },
  { start: 2239.968, end: 2245.812, text: 'color="#FFFF00">comonomers</font>, such as polyoxyethylene or methacrylic ester macromers.' },
  { start: 2245.932, end: 2247.906, text: '' },
  { start: 2248.026, end: 2254.764, text: 'Let\'s now detail the <font color="#FFFF00">stabilization</font> <font color="#FFFF00">steric</font>, through two' },
  { start: 2254.884, end: 2262.434, text: 'contributions: the <font color="#FFFF00">osmotic effect</font> and the <font color="#FFFF00">volume restriction</font>.' },
  { start: 2262.554, end: 2269.704, text: 'The <font color="#FFFF00">osmotic effect</font> generates a local overconcentration of polymer in the interaction zone,' },
  { start: 2269.824, end: 2273.401, text: 'causing a call for solvent which repels the particles.' },
  { start: 2273.521, end: 2280.906, text: 'The <font color="#FFFF00">volume restriction</font> induces a loss of conformational entropy of hydrophilic macromolecules,' },
  { start: 2281.026, end: 2283.602, text: 'and creates repulsive elastic forces.' },
  { start: 2283.722, end: 2286.487, text: 'The free energy of <font color="#FFFF00">steric' },
  { start: 2286.607, end: 2290.025, text: 'stabilization</font>, Delta G ST, combines the mixing' },
  { start: 2290.145, end: 2294.583, text: 'term, Delta G M, and the volume restriction term, Delta G RV.' },
  { start: 2294.703, end: 2296.853, text: 'Pause 5 seconds, change of slide' },
  { start: 2296.973, end: 2300.444, text: 'Let\'s take stock with a comparative table of the advantages' },
  { start: 2300.564, end: 2303.269, text: 'and disadvantages of the three main methods of' },
  { start: 2303.389, end: 2306.454, text: 'colloidal stabilization: electrostatic, osmotic' },
  { start: 2306.574, end: 2310.209, text: 'and by <font color="#FFFF00">volume restriction</font>.' },
  { start: 2310.329, end: 2313.682, text: 'Electrostatic stabilization is insensitive to temperature' },
  { start: 2313.802, end: 2317.246, text: 'variations and the quality of the solvent, but its major' },
  { start: 2317.366, end: 2321.178, text: 'weak point is extreme sensitivity to the presence of ions.' },
  { start: 2321.298, end: 2324.239, text: 'Osmotic stabilization is affected neither by <font' },
  { start: 2324.359, end: 2326.948, text: 'color="#FFFF00">ionic strength</font> nor by' },
  { start: 2327.068, end: 2329.982, text: 'temperature, but is vulnerable to the choice of' },
  { start: 2330.102, end: 2334.679, text: 'solvents and competition with <font color="#FFFF00">surfactants</font>.' },
  { start: 2334.799, end: 2336.772, text: 'Finally, stabilization by <font' },
  { start: 2336.892, end: 2339.481, text: 'color="#FFFF00">volume restriction</font> is' },
  { start: 2339.601, end: 2342.248, text: 'insensitive to ions and to the quality of the' },
  { start: 2342.368, end: 2347.741, text: 'solvent, but is subject to the direct influence of temperature and shear stresses.' },
  { start: 2347.861, end: 2349.835, text: '' },
  { start: 2349.955, end: 2354.190, text: 'Let\'s now move on to the diffusion-limited <font color="#FFFF00">cluster' },
  { start: 2354.310, end: 2358.566, text: 'aggregation</font>, or <font color="#FFFF00">DLCA</font> model.' },
  { start: 2358.686, end: 2361.424, text: 'In this process, the growth of aggregates is' },
  { start: 2361.544, end: 2364.518, text: 'controlled by the diffusion of particles, and is' },
  { start: 2364.638, end: 2368.214, text: 'carried out by collision of clusters of similar sizes.' },
  { start: 2368.334, end: 2370.687, text: 'These pairwise association kinetics lead' },
  { start: 2370.807, end: 2373.913, text: 'to structures with a narrow size distribution.' },
  { start: 2374.033, end: 2379.006, text: 'The fractal cluster formed follows the scaling law M equals R g to the power of d,' },
  { start: 2379.126, end: 2384.762, text: 'with a <font color="#FFFF00">fractal dimension</font> d of approximately one point eight.' },
  { start: 2384.882, end: 2386.855, text: '' },
  { start: 2386.975, end: 2395.466, text: 'Let\'s continue with the reaction-limited <font color="#FFFF00">cluster aggregation</font>, or <font color="#FFFF00">RLCA</font> regime.' },
  { start: 2395.586, end: 2400.148, text: '<font color="#FFFF00">aggregation</font> is no longer limited by diffusion,' },
  { start: 2400.268, end: 2404.786, text: 'but by the kinetics of the chemical or physical agglomeration process.' },
  { start: 2404.906, end: 2408.435, text: 'The probability of crossing the <font color="#FFFF00">energy' },
  { start: 2408.555, end: 2413.073, text: 'barrier</font> E b follows an exponential law of minus E b over k B T.' },
  { start: 2413.193, end: 2417.755, text: 'This regime leads to a wider size distribution and more compact aggregates,' },
  { start: 2417.875, end: 2422.804, text: 'of <font color="#FFFF00">fractal dimension</font> d close to two point three.' },


  { start: 2422.804, end: 2425.000, text: 'Thank you for your attention. Go to Chapter 3.' },

];








const SUBTITLES_ES_CH2 = [
{ start: 1.000, end: 2.000, text: 'Bienvenido al programa BRIDGE -<font color="#FFFF00"> Bridging Research and Inclusive Digital Education</font>' },
  

  { start: 0.000, end: 2.133, text: 'Bienvenido al módulo dos de esta' },
  { start: 2.253, end: 4.700, text: 'presentación, que se centra en las' },
  { start: 4.820, end: 9.203, text: 'propiedades clave de los látex y los polímeros en emulsión.' },
  { start: 9.323, end: 14.640, text: 'Este curso es presentado por Gérard Bacquet para la empresa SciencExpert.' },
  { start: 14.760, end: 15.660, text: '' },
  { start: 15.780, end: 20.960, text: 'Empecemos por el fenómeno de la <font color="#FFFF00">filmificación</font>,' },
  { start: 21.080, end: 27.330, text: 'fundamental para todas las aplicaciones donde se requiere la formación de una película.' },
  { start: 27.450, end: 29.917, text: 'Una serie de ilustraciones muestra el' },
  { start: 30.037, end: 33.017, text: 'proceso, desde apilar partículas esféricas' },
  { start: 33.137, end: 36.587, text: 'hasta deformarlas en estructuras poliédricas.' },
  { start: 36.707, end: 44.153, text: 'Los diagramas también detallan la <font color="#FFFF00">evaporación</font> <font color="#FFFF00">agua</font>,' },
  { start: 44.273, end: 54.390, text: 'las <font color="#FFFF00">fuerzas capilares</font> y la <font color="#FFFF00">coalescencia</font> de cadenas de polímeros a escala de partículas.' },
  { start: 54.510, end: 55.410, text: '' },
  { start: 55.530, end: 60.330, text: 'Veamos ahora las sucesivas etapas de transformación de las partículas de' },
  { start: 60.450, end: 64.900, text: 'látex en una <font color="#FFFF00">película continua</font>.' },
  { start: 65.020, end: 73.600, text: 'Todo comienza con la <font color="#FFFF00">evaporación</font> <font color="#FFFF00">agua</font> y su absorción por el soporte,' },
  { start: 73.720, end: 77.237, text: 'que reúne las partículas en una pila compacta.' },
  { start: 77.357, end: 83.803, text: 'Bajo la acción de <font color="#FFFF00">fuerzas</font> <font color="#FFFF00">capilares</font>,' },
  { start: 83.923, end: 89.840, text: 'las esferas se deforman gradualmente y adoptan una estructura poliédrica de panal.' },
  { start: 89.960, end: 97.940, text: 'Finalmente, la <font color="#FFFF00">interdifusión</font> de las cadenas de polímeros en las interfaces garantiza una' },
  { start: 98.060, end: 106.910, text: '<font color="#FFFF00">coalescencia</font> completa y la formación de la <font color="#FFFF00">película homogénea</font> final.' },
  { start: 107.030, end: 107.930, text: '' },
  { start: 108.050, end: 114.277, text: 'Para describir este secado, nos basamos en el <font color="#FFFF00">modelo Croll</font>,' },
  { start: 114.397, end: 121.847, text: 'que distingue tres fases en la velocidad de secado de una <font color="#FFFF00">película de látex</font>.' },
  { start: 121.967, end: 126.527, text: 'Durante la fase uno, se forma una capa porosa en la superficie,' },
  { start: 126.647, end: 133.030, text: 'encima de una capa de transición más concentrada y una capa húmeda que permanece intacta.' },
  { start: 133.150, end: 136.930, text: 'En la fase dos, la capa húmeda inicial ha desaparecido' },
  { start: 137.050, end: 139.717, text: 'y el <font color="#FFFF00">agua restante' },
  { start: 139.837, end: 144.887, text: 'la evaporación</font> proviene directamente de la capa de transición.' },
  { start: 145.007, end: 146.253, text: 'En la fase tres,' },
  { start: 146.373, end: 156.670, text: 'la capa de transición desaparece a su vez: la película está completamente seca y lista para el paso de <font color="#FFFF00">coalescencia</font>.' },
  { start: 156.790, end: 157.690, text: '' },
  { start: 157.810, end: 161.523, text: 'Este modelo ha sido validado teórica y cinéticamente,' },
  { start: 161.643, end: 164.760, text: 'para las fases uno y dos de evaporación.' },
  { start: 164.880, end: 172.420, text: 'Un gráfico, a la izquierda, muestra la evolución de la fracción volumétrica sólida a lo largo del tiempo,' },
  { start: 172.540, end: 174.523, text: 'dividida en tres fases.' },
  { start: 174.643, end: 175.957, text: 'Para la fase uno,' },
  { start: 176.077, end: 184.640, text: 'la tasa de pérdida de agua es constante: depende únicamente de la superficie de evaporación y del flujo de evaporación.' },
  { start: 184.760, end: 188.740, text: 'Para la fase dos, la cinética depende de la concentración' },
  { start: 188.860, end: 192.707, text: 'de agua en la superficie, lo que reduce gradualmente la' },
  { start: 192.827, end: 197.143, text: 'velocidad de secado en función del espesor de la película.' },
  { start: 197.263, end: 198.163, text: '' },
  { start: 198.283, end: 200.930, text: 'Ahora veamos la fase tres del secado,' },
  { start: 201.050, end: 206.367, text: 'centrada en la deformación de partículas y la expulsión de agua residual.' },
  { start: 206.487, end: 213.600, text: 'Las <font color="#FFFF00">fuerzas capilares</font> favorecen la deformación de las partículas elásticas,' },
  { start: 213.720, end: 218.370, text: 'mientras que las tensiones elásticas internas se oponen a ella.' },
  { start: 218.490, end: 221.183, text: 'Un diagrama, arriba a la izquierda,' },
  { start: 221.303, end: 231.353, text: 'muestra la diferencia en la <font color="#FFFF00">presión capilar</font> creada por los meniscos de agua entre las esferas de látex en contacto.' },
  { start: 231.473, end: 234.740, text: 'Una tabla resume la <font color="#FFFF00">presión' },
  { start: 234.860, end: 237.593, text: 'capilar</font> en función del radio de la' },
  { start: 237.713, end: 241.227, text: 'partícula y del número de esferas en contacto: las' },
  { start: 241.347, end: 245.597, text: 'presiones son muy altas para las partículas más pequeñas.' },
  { start: 245.717, end: 246.617, text: '' },
  { start: 246.737, end: 249.603, text: 'Esta distorsión se observó en el trabajo de' },
  { start: 249.723, end: 254.553, text: 'tesis de François Magnin, apoyado en la Universidad de París 6.' },
  { start: 254.673, end: 258.633, text: 'Se relacionan con la morfología, a diferentes escalas,' },
  { start: 258.753, end: 262.737, text: 'de películas de látex bidispersas después del secado.' },
  { start: 262.857, end: 268.457, text: 'Una imagen de microscopía de fuerza atómica muestra la deformación de las partículas' },
  { start: 268.577, end: 274.093, text: 'esféricas en una red de células poliédricas que miden doscientos nanómetros.' },
  { start: 274.213, end: 275.113, text: '' },
  { start: 275.233, end: 279.480, text: 'Volvamos al modelado del equilibrio mecánico de la fase tres,' },
  { start: 279.600, end: 287.250, text: 'entre las <font color="#FFFF00">fuerzas capilares</font> deformantes y las restricciones elásticas opuestas.' },
  { start: 287.370, end: 292.283, text: 'La <font color="#FFFF00">fuerza capilar</font> promueve la deformación,' },
  { start: 292.403, end: 302.253, text: 'mientras que la respuesta La elasticidad de las partículas se describe mediante la <font color="#FFFF00">teoría del contacto de Hertz</font>.' },
  { start: 302.373, end: 306.220, text: 'Para obtener <font color="#FFFF00">coalescencia</font>,' },
  { start: 306.340, end: 313.857, text: 'la <font color="#FFFF00">fuerza capilar</font> debe prevalecer sobre la resistencia mecánica del polímero.' },
  { start: 313.977, end: 316.443, text: 'El criterio final indica que el <font' },
  { start: 316.563, end: 320.297, text: 'color="#FFFF00">módulo de corte</font> del polímero debe' },
  { start: 320.417, end: 324.330, text: 'permanecer por debajo de un valor límite, proporcional a' },
  { start: 324.450, end: 329.967, text: 'la tensión interfacial e inversamente proporcional al radio de la partícula.' },
  { start: 330.087, end: 330.987, text: '' },
  { start: 331.107, end: 339.220, text: 'Esto nos lleva a la <font color="#FFFF00">temperatura</font> <font color="#FFFF00">formación mínima de película</font>,' },
  { start: 339.340, end: 345.790, text: 'parámetro clave de las condiciones de <font color="#FFFF00">coalescencia</font> del látex.' },
  { start: 345.910, end: 348.223, text: 'Sobre un banco térmico vertical,' },
  { start: 348.343, end: 354.477, text: 'la película es transparente y perfectamente <font color="#FFFF00">fusionada</font> en altura' },
  { start: 354.597, end: 360.427, text: 'temperaturas, mientras que a bajas temperaturas se vuelve opaco y polvoriento.' },
  { start: 360.547, end: 367.080, text: 'La <font color="#FFFF00">coalescencia</font> solo es posible si las partículas y el agua coexisten' },
  { start: 367.200, end: 373.450, text: 'y si el <font color="#FFFF00">módulo de corte</font> permanece lo suficientemente bajo.' },
  { start: 373.570, end: 381.617, text: 'Si la temperatura de secado es inferior a la <font color="#FFFF00">temperatura de formación de película</font> mínima,' },
  { start: 381.737, end: 387.187, text: 'la película no puede <font color="#FFFF00">fusionarse</font> correctamente.' },
  { start: 387.307, end: 388.207, text: '' },
  { start: 388.327, end: 394.527, text: 'Veamos ahora la influencia del <font color="#FFFF00">tamaño de partícula</font> en esta <font' },
  { start: 394.647, end: 401.297, text: 'color="#FFFF00">temperatura mínima</font> <font color="#FFFF00">formación de película</font>.' },
  { start: 401.417, end: 407.710, text: 'Un primer gráfico, a la izquierda, muestra la caída en el <font color="#FFFF00">módulo de' },
  { start: 407.830, end: 414.010, text: 'corte</font> en la <font color="#FFFF00">transición vítrea</font>, que marca la transición' },
  { start: 414.130, end: 420.780, text: 'del <font color="#FFFF00">estado vítreo</font> al <font color="#FFFF00">estado gomoso</font>.' },
  { start: 420.900, end: 425.127, text: 'Un segundo gráfico, a la derecha, ilustra el aumento de la' },
  { start: 425.247, end: 428.980, text: 'temperatura mínima de <font color="#FFFF00">formación de' },
  { start: 429.100, end: 435.530, text: 'película</font> con el radio de la partícula, de treinta a ciento cincuenta nanómetros.' },
  { start: 435.650, end: 439.650, text: 'Los viales demuestran que un tamaño de partícula más pequeño' },
  { start: 439.770, end: 444.303, text: 'promueve la <font color="#FFFF00">coalescencia</font> a temperaturas' },
  { start: 444.423, end: 449.987, text: 'más bajas, al aumentar las <font color="#FFFF00">fuerzas capilares</font>.' },
  { start: 450.107, end: 451.007, text: '' },
  { start: 451.127, end: 453.440, text: 'Abrimos ahora una nueva sección,' },
  { start: 453.560, end: 458.677, text: 'dedicada a las propiedades mecánicas de polímeros y látex en emulsión.' },
  { start: 458.797, end: 466.977, text: 'Estas propiedades se refieren a materiales <font color="#FFFF00">compuestos</font> y a muchas aplicaciones industriales:' },
  { start: 467.097, end: 470.173, text: 'pinturas, papel, textiles o colas.' },
  { start: 470.293, end: 473.453, text: 'Un friso ilustrado, al final de la página,' },
  { start: 473.573, end: 479.823, text: 'recuerda las etapas microestructurales de deformación y organización de las partículas.' },
  { start: 479.943, end: 480.843, text: '' },
  { start: 480.963, end: 484.277, text: 'Empecemos por los estados físicos del polímero,' },
  { start: 484.397, end: 489.047, text: 'según su <font color="#FFFF00">masa molar</font> y temperatura.' },
  { start: 489.167, end: 493.147, text: 'Un primer <font color="#FFFF00">diagrama de fases</font>,' },
  { start: 493.267, end: 497.047, text: 'a la izquierda, combina la temperatura y la masa molar' },
  { start: 497.167, end: 502.110, text: 'media en peso, y delimita las zonas vítreas, gomoso y líquido.' },
  { start: 502.230, end: 508.257, text: 'Un segundo gráfico, a la derecha, muestra la caída en el <font color="#FFFF00">módulo' },
  { start: 508.377, end: 514.423, text: 'de</font> <font color="#FFFF00">Joven</font> con la temperatura, desde la transición del' },
  { start: 514.543, end: 522.107, text: '<font color="#FFFF00">estado vítreo</font> al <font color="#FFFF00">estado de goma</font>, luego fluido.' },
  { start: 522.227, end: 527.653, text: 'A bajas temperaturas, el polímero tiene un módulo elástico alto y constante:' },
  { start: 527.773, end: 531.823, text: 'este es el <font color="#FFFF00">estado vítreo</font>.' },
  { start: 531.943, end: 536.257, text: 'Más allá de la <font color="#FFFF00">transición vítrea</font>,' },
  { start: 536.377, end: 545.693, text: 'la <font color="#FFFF00">placa de goma</font> tiene valores de módulo entre diez elevado a cuatro y diez elevado a seis megapascales.' },
  { start: 545.813, end: 550.973, text: 'A temperaturas más altas, una transición final conduce al estado fluido,' },
  { start: 551.093, end: 555.810, text: 'descrito por propiedades reológicas pseudoplásticas específicas.' },
  { start: 555.930, end: 556.830, text: '' },
  { start: 556.950, end: 563.883, text: 'Veamos ahora el efecto de las principales variables sobre el <font color="#FFFF00">comportamiento termo-' },
  { start: 564.003, end: 567.853, text: 'viscoelástico</font> de los polímeros estadísticos.' },
  { start: 567.973, end: 576.353, text: 'Un gráfico representa la evolución del <font color="#FFFF00">módulo elástico</font> del látex en función de la temperatura,' },
  { start: 576.473, end: 582.323, text: 'para diferentes formulaciones de <font color="#FFFF00">estireno-butadieno</font>.' },
  { start: 582.443, end: 591.957, text: 'El <font color="#FFFF00">módulo de Young</font> se puede modular ajustando la <font color="#FFFF00">temperatura de transición vítrea</font>,' },
  { start: 592.077, end: 596.927, text: 'gracias a la proporción de <font color="#FFFF00">monómeros</font>.' },
  { start: 597.047, end: 607.960, text: 'El nivel de la <font color="#FFFF00">placa de goma</font> depende de la <font color="#FFFF00">masa molar</font> o de la <font color="#FFFF00">tasa de gel</font>,' },
  { start: 608.080, end: 612.263, text: 'aquí se comparan tasas del treinta y setenta por ciento.' },
  { start: 612.383, end: 613.283, text: '' },
  { start: 613.403, end: 619.737, text: 'Comparemos ahora las curvas experimentales de <font color="#FFFF00">viscoelasticidad</font> con' },
  { start: 619.857, end: 625.440, text: 'los modelos mecánicos de Maxwell y <font color="#FFFF00">Voigt-Kelvin</font>.' },
  { start: 625.560, end: 629.893, text: 'Los diagramas superiores ilustran el <font color="#FFFF00">modelo' },
  { start: 630.013, end: 634.307, text: 'Maxwell</font>, en serie, y el <font color="#FFFF00">modelo' },
  { start: 634.427, end: 640.837, text: 'Voigt-Kelvin</font>, en paralelo, para describir los componentes elástico y viscoso.' },
  { start: 640.957, end: 645.270, text: 'A la izquierda, la trama de <font color="#FFFF00">preservación' },
  { start: 645.390, end: 648.990, text: 'El módulo</font> G\' frente a la temperatura muestra la' },
  { start: 649.110, end: 653.177, text: 'transición entre el <font color="#FFFF00">estado</font> <font' },
  { start: 653.297, end: 658.747, text: 'color="#FFFF00">vítreo</font> y la meseta gomosa para diferentes polímeros.' },
  { start: 658.867, end: 665.780, text: 'A la derecha, el gráfico del <font color="#FFFF00">módulo</font> <font color="#FFFF00">pérdida</font>' },
  { start: 665.900, end: 674.083, text: 'G\'\' resalta los picos de disipación de energía característicos de la <font color="#FFFF00">transición vítrea</font>.' },
  { start: 674.203, end: 675.103, text: '' },
  { start: 675.223, end: 679.270, text: 'Pasemos a la <font color="#FFFF00">ecuación de Fox</font>,' },
  { start: 679.390, end: 690.573, text: 'que permite calcular la <font color="#FFFF00">temperatura de transición</font> <font color="#FFFF00">vítrea</font> de un <font color="#FFFF00">copolímero</font>.' },
  { start: 690.693, end: 701.540, text: 'Expresa la inversa de la <font color="#FFFF00">Tg</font> general como la suma ponderada de las fracciones de masa de cada <font color="#FFFF00">monómero</font>,' },
  { start: 701.660, end: 706.843, text: 'dividida por sus respectivas <font color="#FFFF00">Tg</font> en Kelvin.' },
  { start: 706.963, end: 710.097, text: 'Una tabla resume las temperaturas de transición' },
  { start: 710.217, end: 711.683, text: 'vítrea de varios <font' },
  { start: 711.803, end: 715.383, text: 'color="#FFFF00">homopolímeros</font> comunes, desde' },
  { start: 715.503, end: 721.620, text: 'polibutadieno hasta menos ciento doce grados hasta PMMA a ciento ocho grados Celsius.' },
  { start: 721.740, end: 722.640, text: '' },
  { start: 722.760, end: 727.140, text: 'Ahora enfrentemos esta ecuación con la realidad: aquí están los' },
  { start: 727.260, end: 729.860, text: 'datos de noventa y nueve látex de <font' },
  { start: 729.980, end: 736.343, text: 'color="#FFFF00">estireno-butadieno</font>, en comparación con la curva teórica de Fox.' },
  { start: 736.463, end: 742.397, text: 'El gráfico presenta la <font color="#FFFF00">temperatura de transición vítrea</font> como' },
  { start: 742.517, end: 749.167, text: 'una función del porcentaje en masa de estireno en el <font color="#FFFF00">copolímero</font>.' },
  { start: 749.287, end: 753.820, text: 'La fórmula aplicada a las fracciones de masa de butadieno y estireno' },
  { start: 753.940, end: 758.390, text: 'permite ajustar con precisión la línea de tendencia teórica.' },
  { start: 758.510, end: 764.670, text: 'Los puntos experimentales, procedentes de diversos procesos y productores industriales,' },
  { start: 764.790, end: 768.307, text: 'muestran muy buena concordancia con el modelo.' },
  { start: 768.427, end: 769.327, text: '' },
  { start: 769.447, end: 776.960, text: 'Luego, observemos el impacto de las <font color="#FFFF00">fuerzas de Keesom</font> y el momento dipolar de los' },
  { start: 777.080, end: 783.397, text: 'enlaces secundarios en la <font color="#FFFF00">temperatura de transición vítrea</font>.' },
  { start: 783.517, end: 790.030, text: 'Una tabla presenta el aumento en el <font color="#FFFF00">Tg</font> según el patrón sustituido,' },
  { start: 790.150, end: 796.933, text: 'desde polietileno a menos ciento diez grados hasta PTFE a ciento veintitrés grados centígrados.' },
  { start: 797.053, end: 802.880, text: 'Un gráfico, en la parte inferior izquierda, muestra la creciente correlación entre' },
  { start: 803.000, end: 808.267, text: 'la <font color="#FFFF00">temperatura de</font> <font color="#FFFF00">transición' },
  { start: 808.387, end: 814.617, text: 'vítrea</font> y el <font color="#FFFF00">momento dipolar</font>, expresado en Debye.' },
  { start: 814.737, end: 820.537, text: 'La fórmula para la energía de interacción de Keesom confirma que fortalecer los enlaces' },
  { start: 820.657, end: 827.173, text: 'dipolares secundarios aumenta directamente la <font color="#FFFF00">Tg</font> del polímero.' },
  { start: 827.293, end: 828.193, text: '' },
  { start: 828.313, end: 835.780, text: 'Veamos ahora la influencia de las transiciones térmicas en materiales <font color="#FFFF00">termoformados</font>' },
  { start: 835.900, end: 840.883, text: 'y <font color="#FFFF00">compuestos</font> a base de látex SB y SBAn.' },
  { start: 841.003, end: 845.537, text: 'Un gráfico compara la evolución del módulo de corte en función de la' },
  { start: 845.657, end: 847.990, text: 'temperatura para los sistemas <font' },
  { start: 848.110, end: 855.627, text: 'color="#FFFF00">estireno-butadieno</font> y <font color="#FFFF00">estireno-butadieno-acrilonitrilo</font>.' },
  { start: 855.747, end: 865.193, text: 'La adición de <font color="#FFFF00">acrilonitrilo</font> modifica la pendiente de transición y amplía la zona de reblandecimiento mecánico,' },
  { start: 865.313, end: 869.030, text: 'gracias a las interacciones polares introducidas.' },
  { start: 869.150, end: 876.350, text: 'Los ejemplos de aplicaciones finales muestran paneles decorativos <font color="#FFFF00">termoformados</font>' },
  { start: 876.470, end: 882.187, text: 'y elementos textiles estructurados para el diseño de interiores de automóviles.' },
  { start: 882.307, end: 883.207, text: '' },
  { start: 883.327, end: 887.107, text: 'Veamos ahora la concentración de pigmento por volumen,' },
  { start: 887.227, end: 891.723, text: 'llamada <font color="#FFFF00">CVP</font>, o PVC en inglés.' },
  { start: 891.843, end: 897.823, text: 'Su fórmula lo define como la relación entre el volumen combinado de pigmentos y cargas,' },
  { start: 897.943, end: 900.393, text: 'y el volumen total de sólidos.' },
  { start: 900.513, end: 907.560, text: 'Tres diagramas ilustran los regímenes de formulación según el <font color="#FFFF00">CVP</font> crítico,' },
  { start: 907.680, end: 912.530, text: 'dependiendo de la presencia o ausencia de exceso de conglomerante.' },
  { start: 912.650, end: 917.497, text: 'Cuando el <font color="#FFFF00">CVP</font> excede el valor crítico, la' },
  { start: 917.617, end: 922.130, text: 'cantidad de aglutinante se vuelve insuficiente, lo que provoca la' },
  { start: 922.250, end: 928.367, text: 'aparición de <font color="#FFFF00">porosidades</font> y huecos dentro de la película.' },
  { start: 928.487, end: 929.387, text: '' },
  { start: 929.507, end: 942.087, text: 'Esta <font color="#FFFF00">porosidad</font> nos lleva al <font color="#FFFF00">módulo</font> <font color="#FFFF00">de Young</font> de los <font color="#FFFF00">composites</font> porosos,' },
  { start: 942.207, end: 950.590, text: 'un tema que vuelve a ser ampliamente estudiado con la aparición de la <font color="#FFFF00">fabricación aditiva</font>.' },
  { start: 950.710, end: 955.710, text: 'Un gráfico compara varios modelos teóricos que describen la caída del <font' },
  { start: 955.830, end: 963.013, text: 'color="#FFFF00">módulo elástico</font> en función del volumen <font color="#FFFF00">porosidad</font>.' },
  { start: 963.133, end: 972.067, text: 'El <font color="#FFFF00">modelo Bert</font> expresa la relación de los módulos en función de la <font color="#FFFF00">porosidad</font>' },
  { start: 972.187, end: 979.550, text: 'relativa, la <font color="#FFFF00">porosidad</font> máxima y un factor de concentración de tensiones.' },
  { start: 979.670, end: 983.003, text: 'Este factor K varía dependiendo de la geometría de' },
  { start: 983.123, end: 986.437, text: 'las inclusiones: cero coma setenta y cinco para' },
  { start: 986.557, end: 990.787, text: 'partículas planas como la arcilla, y dos para esferas.' },
  { start: 990.907, end: 991.807, text: '' },
  { start: 991.927, end: 998.573, text: 'Apliquemos estas nociones de <font color="#FFFF00">porosidad</font> y rigidez a un caso práctico:' },
  { start: 998.693, end: 1002.077, text: '<font color="#FFFF00">papel estucado</font>.' },
  { start: 1002.197, end: 1008.623, text: 'Un primer gráfico, a la izquierda, muestra la disminución polinómica del módulo relativo E\'' },
  { start: 1008.743, end: 1014.660, text: 'sobre E\' cero en función de la fracción de <font color="#FFFF00">porosidad</font>.' },
  { start: 1014.780, end: 1020.713, text: 'Una tabla resume la evolución de la <font color="#FFFF00">porosidad</font> y de los <font' },
  { start: 1020.833, end: 1029.510, text: 'color="#FFFF00">módulos de Young</font>, vítreos y gomosos, según la proporción de partículas de poliestireno y látex.' },
  { start: 1029.630, end: 1034.523, text: 'El gráfico principal, a la derecha, confirma la caída en los módulos' },
  { start: 1034.643, end: 1038.510, text: 'vítreos E\'v y en los módulos de caucho E\'c cuando la <font' },
  { start: 1038.630, end: 1044.747, text: 'color="#FFFF00">porosidad</font> aumenta del veinticinco al treinta y uno por ciento.' },
  { start: 1044.867, end: 1051.140, text: 'Dos viñetas, en la parte inferior, vinculan la Rigidez taberal al peso depositado, así' },
  { start: 1051.260, end: 1057.777, text: 'como a la <font color="#FFFF00">porosidad</font> medida por densidad óptica con las tintas.' },
  { start: 1057.897, end: 1061.193, text: 'Pausa 5 segundos, cambio de diapositiva.' },
  { start: 1061.313, end: 1064.430, text: 'Veamos ahora el comportamiento mecánico.' },
  { start: 1064.550, end: 1070.000, text: 'Materiales <font color="#FFFF00">compuestos</font> que contienen polímeros.' },
  { start: 1070.120, end: 1074.787, text: 'Una tabla comparativa muestra que la <font color="#FFFF00">temperatura' },
  { start: 1074.907, end: 1079.573, text: 'de transición</font> <font color="#FFFF00">vítrea</font> del composite' },
  { start: 1079.693, end: 1083.873, text: 'sigue siendo la misma que la del látex solo, aunque su <font' },
  { start: 1083.993, end: 1089.577, text: 'color="#FFFF00">módulo</font> <font color="#FFFF00">elástico</font> es mayor.' },
  { start: 1089.697, end: 1093.563, text: 'Un gráfico de análisis mecánico dinámico ilustra las <font' },
  { start: 1093.683, end: 1098.330, text: 'color="#FFFF00">curvas del módulo de Young para tres formulaciones,' },
  { start: 1098.450, end: 1104.813, text: '<font color="#FFFF00">Tg</font> menos treinta, menos doce y menos tres grados Celsius.' },
  { start: 1104.933, end: 1115.200, text: 'El texto enfatiza que los <font color="#FFFF00">compuestos</font> formulados con un polímero conservan las mismas <font color="#FFFF00">propiedades termo-' },
  { start: 1115.320, end: 1119.237, text: 'viscoelásticas</font> que el polímero constituyente.' },
  { start: 1119.357, end: 1120.257, text: '' },
  { start: 1120.377, end: 1127.757, text: 'Cambiemos de tema para definir las nociones de fallo adhesivo y <font color="#FFFF00">fallo cohesivo</font>,' },
  { start: 1127.877, end: 1130.260, text: 'en el campo de los adhesivos.' },
  { start: 1130.380, end: 1137.207, text: 'A la izquierda, cuando la cohesión interna del polímero es mayor que la adhesión a la superficie,' },
  { start: 1137.327, end: 1144.290, text: 'la ruptura se produce en la interfaz: es una <font color="#FFFF00">ruptura del adhesivo</font>.' },
  { start: 1144.410, end: 1147.657, text: 'A la derecha, si la adhesión entre el polímero' },
  { start: 1147.777, end: 1151.157, text: 'y la superficie excede la cohesión del polímero,' },
  { start: 1151.277, end: 1158.773, text: 'la ruptura se produce en el corazón del material: es una <font color="#FFFF00">ruptura cohesiva</font>.' },
  { start: 1158.893, end: 1161.627, text: 'Los diagramas ilustran estos dos modos de' },
  { start: 1161.747, end: 1165.063, text: 'falla mecánica entre dos sustratos sólidos.' },
  { start: 1165.183, end: 1166.083, text: '' },
  { start: 1166.203, end: 1173.430, text: 'Veamos ahora el efecto de la rigidez del polímero, representado por su <font color="#FFFF00">Tg</font>,' },
  { start: 1173.550, end: 1177.600, text: 'en la <font color="#FFFF00">energía de ruptura</font>.' },
  { start: 1177.720, end: 1180.347, text: 'El primer gráfico, a la izquierda,' },
  { start: 1180.467, end: 1194.517, text: 'indica que la <font color="#FFFF00">energía de descomposición</font> del adhesivo disminuye a medida que aumenta la <font color="#FFFF00">temperatura</font> <font color="#FFFF00">transición vítrea</font>.' },
  { start: 1194.637, end: 1196.663, text: 'El segundo, a la derecha,' },
  { start: 1196.783, end: 1208.367, text: 'muestra por el contrario un aumento en la <font color="#FFFF00">energía de</font> <font color="#FFFF00">ruptura</font> cohesiva con la <font color="#FFFF00">Tg</font>.' },
  { start: 1208.487, end: 1216.733, text: 'El gráfico inferior superpone estos dos mecanismos y resalta una <font color="#FFFF00">energía de adhesión</font> óptima,' },
  { start: 1216.853, end: 1220.903, text: 'en el punto de intersección de los dos modos de falla.' },
  { start: 1221.023, end: 1221.923, text: '' },
  { start: 1222.043, end: 1227.377, text: 'Sigamos con el efecto de la <font color="#FFFF00">carboxilación</font> del látex' },
  { start: 1227.497, end: 1233.210, text: 'sobre la cohesión del <font color="#FFFF00">papel estucado</font>, en función de la' },
  { start: 1233.330, end: 1239.647, text: '<font color="#FFFF00">temperatura</font> <font color="#FFFF00">transición vítrea</font>.' },
  { start: 1239.767, end: 1246.347, text: 'Un gráfico representa la resistencia al pelado en seco frente a <font color="#FFFF00">Tg</font>,' },
  { start: 1246.467, end: 1251.583, text: 'para diferentes niveles de <font color="#FFFF00">carboxilación</font>.' },
  { start: 1251.703, end: 1259.283, text: 'Una <font color="#FFFF00">carboxilación</font> mejorada mejora la cohesión del papel cuando el látex es rígido,' },
  { start: 1259.403, end: 1267.167, text: 'es decir en la zona de <font color="#FFFF00">fallo adhesivo</font>, a alta <font color="#FFFF00">Tg</font>.' },
  { start: 1267.287, end: 1276.160, text: 'Por otro lado, a una <font color="#FFFF00">Tg</font> baja, en el dominio de la <font color="#FFFF00">ruptura cohesiva</font>,' },
  { start: 1276.280, end: 1284.130, text: 'la <font color="#FFFF00">carboxilación</font> no tiene ningún efecto significativo sobre la cohesión del papel.' },
  { start: 1284.250, end: 1285.150, text: '' },
  { start: 1285.270, end: 1290.737, text: 'Veamos entonces el efecto del <font color="#FFFF00">tamaño de partícula</font> del' },
  { start: 1290.857, end: 1295.840, text: 'látex en el caso de <font color="#FFFF00">fallo del adhesivo</font>.' },
  { start: 1295.960, end: 1301.340, text: 'Dos diagramas comparativos muestran que cuanto más grandes son las partículas,' },
  { start: 1301.460, end: 1306.710, text: 'más disminuye la superficie de contacto entre el polímero y el pigmento.' },
  { start: 1306.830, end: 1310.497, text: 'El gráfico de la izquierda ilustra la disminución de la' },
  { start: 1310.617, end: 1318.667, text: 'adhesión de energía cuando aumenta el <font color="#FFFF00">tamaño</font> <font color="#FFFF00">partículas</font>.' },
  { start: 1318.787, end: 1323.880, text: 'Esta relación, inversamente proporcional al diámetro de las partículas,' },
  { start: 1324.000, end: 1328.650, text: 'gobierna la resistencia mecánica durante la falla del adhesivo.' },
  { start: 1328.770, end: 1329.670, text: '' },
  { start: 1329.790, end: 1337.990, text: 'Aquí está ahora la transición de una <font color="#FFFF00">ruptura</font> <font color="#FFFF00">cohesiva</font> a una <font' },
  { start: 1338.110, end: 1348.520, text: 'color="#FFFF00">ruptura del adhesivo</font>, por <font color="#FFFF00">plastificación</font> de la interfaz, especialmente en presencia de agua.' },
  { start: 1348.640, end: 1355.287, text: 'Cuando está seco, las fuertes interacciones ácido-base entre los grupos carboxilato y el pigmento' },
  { start: 1355.407, end: 1362.973, text: 'garantizan una alta adhesión. lo que conduce a una <font color="#FFFF00">ruptura de cohesión</font>.' },
  { start: 1363.093, end: 1369.407, text: 'En un ambiente húmedo, la presencia de moléculas de agua en la interfaz debilita la adhesión' },
  { start: 1369.527, end: 1374.977, text: 'y provoca una transición a una <font color="#FFFF00">falla adhesiva</font>.' },
  { start: 1375.097, end: 1380.363, text: 'El gráfico inferior compara los niveles de energía en ambientes secos y húmedos' },
  { start: 1380.483, end: 1385.867, text: 'y resalta la caída general de energía debido a los efectos de la interfaz.' },
  { start: 1385.987, end: 1386.887, text: '' },
  { start: 1387.007, end: 1392.187, text: 'Introduzcamos ahora la equivalencia entre temperatura y velocidad de carga,' },
  { start: 1392.307, end: 1397.423, text: 'según la teoría de <font color="#FFFF00">Williams-Landel-Ferry</font>.' },
  { start: 1397.543, end: 1400.610, text: 'Un gráfico del <font color="#FFFF00">módulo de' },
  { start: 1400.730, end: 1404.330, text: 'Young</font> frente a la temperatura muestra el cambio' },
  { start: 1404.450, end: 1408.050, text: 'de la transición vítrea hacia temperaturas más altas a' },
  { start: 1408.170, end: 1412.553, text: 'medida que la frecuencia aumenta de uno a diez mil hercios.' },
  { start: 1412.673, end: 1418.540, text: 'La ecuación expresa la <font color="#FFFF00">Tg</font> a una frecuencia determinada como' },
  { start: 1418.660, end: 1425.243, text: 'una función logarítmica de la relación entre esta frecuencia y una frecuencia de referencia.' },
  { start: 1425.363, end: 1430.143, text: 'El coeficiente k es cercano a diez para los polímeros convencionales,' },
  { start: 1430.263, end: 1436.380, text: 'como los sistemas de <font color="#FFFF00">estireno-butadieno</font> o los acrilatos.' },
  { start: 1436.500, end: 1437.400, text: '' },
  { start: 1437.520, end: 1440.253, text: 'Ahora combinemos temperatura y frecuencia' },
  { start: 1440.373, end: 1443.823, text: 'para describir el estado físico del polímero.' },
  { start: 1443.943, end: 1450.703, text: 'Un diagrama esquemático divide el comportamiento en tres zonas: un estado rígido de módulo alto,' },
  { start: 1450.823, end: 1457.073, text: 'un estado intermedio y un <font color="#FFFF00">estado de caucho</font> de módulo bajo.' },
  { start: 1457.193, end: 1463.373, text: 'El texto de la derecha recuerda la importancia de definir con precisión el entorno de uso,' },
  { start: 1463.493, end: 1469.190, text: 'en términos de temperatura y frecuencia, para diseñar el polímero apropiado.' },
  { start: 1469.310, end: 1472.710, text: 'La pregunta que se plantea a continuación le invita' },
  { start: 1472.830, end: 1477.413, text: 'a determinar explícitamente estas dos variables de aplicación.' },
  { start: 1477.533, end: 1478.433, text: '' },
  { start: 1478.553, end: 1485.383, text: 'Veamos una aplicación práctica: diseñar látex para <font color="#FFFF00">huecograbado</font>.' },
  { start: 1485.503, end: 1489.417, text: 'A la izquierda, las ilustraciones y una vista en sección' },
  { start: 1489.537, end: 1493.537, text: 'utilizando un microscopio electrónico de barrido en un <font' },
  { start: 1493.657, end: 1497.390, text: 'color="#FFFF00">papel de huecograbado</font> resaltan el' },
  { start: 1497.510, end: 1502.360, text: 'fenómeno de los puntos faltantes en la superficie de la impresión.' },
  { start: 1502.480, end: 1507.813, text: 'Los diagramas del proceso de impresión muestran cómo la falta de compresibilidad' },
  { start: 1507.933, end: 1513.583, text: 'local impide la perfecta transferencia de tinta desde las celdas del cilindro.' },
  { start: 1513.703, end: 1516.903, text: 'El gráfico de la derecha muestra la mejora en la' },
  { start: 1517.023, end: 1520.537, text: 'imprimibilidad con el porcentaje de butadieno, que' },
  { start: 1520.657, end: 1525.173, text: 'aumenta la flexibilidad y compresibilidad dinámica del látex.' },
  { start: 1525.293, end: 1526.193, text: '' },
  { start: 1526.313, end: 1529.027, text: 'Ahora vamos a la emulsión inteligente,' },
  { start: 1529.147, end: 1534.663, text: 'con <font color="#FFFF00">reticulación</font> estimulada por la temperatura.' },
  { start: 1534.783, end: 1538.697, text: 'Los diagramas superiores muestran las etapas del secado,' },
  { start: 1538.817, end: 1547.067, text: 'desde la <font color="#FFFF00">evaporación del agua</font> hasta la deformación hexagonal de las partículas de látex.' },
  { start: 1547.187, end: 1550.120, text: 'Los zooms resaltan distintas funcionalidades' },
  { start: 1550.240, end: 1552.953, text: 'reactivas, como los grupos hidroxilo y' },
  { start: 1553.073, end: 1557.303, text: 'epóxido, transportados por partículas complementarias.' },
  { start: 1557.423, end: 1568.203, text: 'El gráfico inferior muestra el aumento de la <font color="#FFFF00">masa molar</font> y la <font color="#FFFF00">tasa de gelificación</font> con la temperatura,' },
  { start: 1568.323, end: 1576.153, text: 'más allá de la <font color="#FFFF00">Tg</font>, signo de <font color="#FFFF00">reticulación</font> efectiva.' },
  { start: 1576.273, end: 1577.173, text: '' },
  { start: 1577.293, end: 1582.693, text: 'Veamos qué efecto tiene esta <font color="#FFFF00">reticulación</font> estimulada' },
  { start: 1582.813, end: 1588.530, text: 'sobre las propiedades <font color="#FFFF00">viscoelásticas</font> del polímero.' },
  { start: 1588.650, end: 1596.117, text: 'Un gráfico compara el <font color="#FFFF00">módulo</font> <font color="#FFFF00">elástico</font> en función de la' },
  { start: 1596.237, end: 1604.553, text: 'temperatura para un polímero estándar y para un polímero con <font color="#FFFF00">entrecruzamiento</font> estimulado.' },
  { start: 1604.673, end: 1610.073, text: 'El polímero reticulado mantiene una <font color="#FFFF00">meseta de caucho</font>' },
  { start: 1610.193, end: 1615.977, text: 'significativamente más alta a temperaturas superiores a los cien grados Celsius.' },
  { start: 1616.097, end: 1620.697, text: 'Esta mejor resistencia térmica se explica por la formación de enlaces' },
  { start: 1620.817, end: 1625.267, text: 'covalentes entre las cadenas durante el tratamiento térmico.' },
  { start: 1625.387, end: 1626.287, text: '' },
  { start: 1626.407, end: 1628.920, text: 'Ahora comenzamos una nueva sección,' },
  { start: 1629.040, end: 1636.157, text: 'dedicado a la <font color="#FFFF00">estabilidad</font> de los látex en cuanto a flujo y formulación.' },
  { start: 1636.277, end: 1639.190, text: 'Se dirige a los campos de los materiales,' },
  { start: 1639.310, end: 1642.293, text: 'la cosmética y las ciencias agrícolas.' },
  { start: 1642.413, end: 1649.973, text: 'Un friso de ilustraciones presenta los mecanismos clave: <font color="#FFFF00">agregación</font> dendrítica,' },
  { start: 1650.093, end: 1658.657, text: '<font color="#FFFF00">floculación</font> aniónica o catiónica, <font color="#FFFF00">potencial zeta</font> y sinéresis.' },
  { start: 1658.777, end: 1665.243, text: 'Estos fenómenos fisicoquímicos condicionan el control de la <font color="#FFFF00">reología</font>' },
  { start: 1665.363, end: 1671.347, text: 'y la <font color="#FFFF00">estabilidad coloidal</font> de los sistemas en emulsión.' },
  { start: 1671.467, end: 1672.367, text: '' },
  { start: 1672.487, end: 1676.220, text: 'Recordemos primero que la termodinámica indica una <font' },
  { start: 1676.340, end: 1680.723, text: 'color="#FFFF00">inestabilidad</font> de látex y emulsiones.' },
  { start: 1680.843, end: 1685.043, text: 'Un diagrama energético muestra que la fragmentación del sistema' },
  { start: 1685.163, end: 1690.327, text: 'por agitación requiere un elevado aporte de energía, señaló Delta E.' },
  { start: 1690.447, end: 1695.540, text: 'El sistema tiende naturalmente hacia un estado de menor energía, E ref,' },
  { start: 1695.660, end: 1701.377, text: 'lo que hace que el estado disperso sea intrínsecamente inestable con el tiempo.' },
  { start: 1701.497, end: 1706.857, text: 'Se ilustran varios caminos de evolución, reversibles o irreversibles: <font' },
  { start: 1706.977, end: 1709.890, text: 'color="#FFFF00">floculación</font>, <font' },
  { start: 1710.010, end: 1715.637, text: 'color="#FFFF00">sedimentación</font>, <font color="#FFFF00">crema</font>, <font' },
  { start: 1715.757, end: 1725.587, text: 'color="#FFFF00">coalescencia</font>, <font color="#FFFF00">maduración de Ostwald</font> e <font color="#FFFF00">inversión de fases</font>.' },
  { start: 1725.707, end: 1726.607, text: '' },
  { start: 1726.727, end: 1732.640, text: 'Detallemos estos fenómenos de <font color="#FFFF00">inestabilidad</font> de los látex,' },
  { start: 1732.760, end: 1736.943, text: 'clasificándolos en procesos reversibles e irreversibles.' },
  { start: 1737.063, end: 1740.977, text: 'La parte superior reúne los fenómenos reversibles: <font' },
  { start: 1741.097, end: 1746.610, text: 'color="#FFFF00">crema</font>, <font color="#FFFF00">sedimentación</font> y <font' },
  { start: 1746.730, end: 1754.560, text: 'color="#FFFF00">floculación</font>, prestando especial atención al <font color="#FFFF00">agotamiento</font>.' },
  { start: 1754.680, end: 1762.240, text: 'La parte inferior presenta los mecanismos irreversibles: <font color="#FFFF00">maduración de Ostwald</font>,' },
  { start: 1762.360, end: 1768.477, text: '<font color="#FFFF00">coalescencia</font> y <font color="#FFFF00">coagulación</font>.' },
  { start: 1768.597, end: 1773.463, text: 'La evolución de estas degradaciones irreversibles conduce inevitablemente' },
  { start: 1773.583, end: 1777.767, text: 'a una completa separación de fases del sistema coloidal.' },
  { start: 1777.887, end: 1778.787, text: '' },
  { start: 1778.907, end: 1783.153, text: 'Para controlar esta <font color="#FFFF00">estabilidad</font>,' },
  { start: 1783.273, end: 1789.990, text: 'Nos basamos en la <font color="#FFFF00">teoría DLVO</font> aplicada a una dispersión coloidal.' },
  { start: 1790.110, end: 1796.223, text: 'El gráfico muestra la energía potencial de interacción en función de la distancia, con un' },
  { start: 1796.343, end: 1802.123, text: '<font color="#FFFF00">mínimo primario</font>, un <font color="#FFFF00">mínimo</font>' },
  { start: 1802.243, end: 1808.960, text: '<font color="#FFFF00">secundario</font> y una <font color="#FFFF00">barrera energética</font>.' },
  { start: 1809.080, end: 1815.240, text: 'Para evitar una aglomeración irreversible, es necesario aumentar la barrera energética,' },
  { start: 1815.360, end: 1819.077, text: 'mediante mecanismos electrostáticos o entrópicos.' },
  { start: 1819.197, end: 1828.223, text: 'Para evitar la <font color="#FFFF00">floculación</font> reversible, en particular por el <font color="#FFFF00">agotamiento</font>,' },
  { start: 1828.343, end: 1834.260, text: 'se debe reducir la profundidad del <font color="#FFFF00">mínimo secundario</font>.' },
  { start: 1834.380, end: 1835.280, text: '' },
  { start: 1835.400, end: 1841.313, text: 'Volvamos a las hipótesis fundamentales de la <font color="#FFFF00">teoría DLVO</font>,' },
  { start: 1841.433, end: 1845.843, text: 'desarrollada por Derjaguin, Landau, Verwey y Overbeek.' },
  { start: 1845.963, end: 1850.877, text: 'El gráfico de la izquierda muestra la curva de energía potencial total,' },
  { start: 1850.997, end: 1854.847, text: 'suma de las fuerzas repulsivas U R y atractivo U A.' },
  { start: 1854.967, end: 1858.833, text: 'Los supuestos estipulan que la superficie es rígida y está' },
  { start: 1858.953, end: 1862.533, text: 'cargada uniformemente, y que el potencial permanece' },
  { start: 1862.653, end: 1867.817, text: 'constante, sin redistribución de cargas ni variación de contraiones.' },
  { start: 1867.937, end: 1873.563, text: 'Finalmente, el disolvente sólo interviene a través de su constante dieléctrica,' },
  { start: 1873.683, end: 1877.800, text: 'sin reacción química ni hinchamiento de las partículas.' },
  { start: 1877.920, end: 1878.820, text: '' },
  { start: 1878.940, end: 1886.920, text: 'Examinemos ahora la fuerza de atracción por <font color="#FFFF00">agotamiento</font> y la energía potencial asociada,' },
  { start: 1887.040, end: 1891.937, text: 'U D, en el marco de la <font color="#FFFF00">teoría DLVO</font>.' },
  { start: 1892.057, end: 1894.457, text: 'El fenómeno ocurre cuando partículas' },
  { start: 1894.577, end: 1896.910, text: 'de radio a y micelas de tamaño L se' },
  { start: 1897.030, end: 1898.963, text: 'acercan a una distancia entre' },
  { start: 1899.083, end: 1902.667, text: 'partículas R menor que la condición geométrica.' },
  { start: 1902.787, end: 1908.833, text: 'La exclusión de micelas de la zona entre partículas crea una llamada osmótica entrópica,' },
  { start: 1908.953, end: 1913.203, text: 'que induce una fuerza de atracción neta entre partículas.' },
  { start: 1913.323, end: 1918.923, text: 'El <font color="#FFFF00">potencial de agotamiento</font> se expresa como una función' },
  { start: 1919.043, end: 1924.027, text: 'de la presión osmótica Pi y las dimensiones geométricas del sistema.' },
  { start: 1924.147, end: 1925.047, text: '' },
  { start: 1925.167, end: 1933.727, text: 'Ilustremos el <font color="#FFFF00">agotamiento</font> con un ejemplo concreto: un sistema de emulsión de caseína y aceite,' },
  { start: 1933.847, end: 1936.430, text: 'dependiendo de la concentración.' },
  { start: 1936.550, end: 1940.017, text: 'Un gráfico de energía potencial muestra la evolución' },
  { start: 1940.137, end: 1943.137, text: 'del pozo de atracción para concentraciones de' },
  { start: 1943.257, end: 1947.820, text: 'caseína de veinte, cuarenta y sesenta gramos por kilogramo.' },
  { start: 1947.940, end: 1956.900, text: 'A veinte gramos por kilogramo, la <font color="#FFFF00">presión osmótica</font> permanece baja y la dispersión permanece estable,' },
  { start: 1957.020, end: 1960.403, text: 'sin <font color="#FFFF00">agregación</font>.' },
  { start: 1960.523, end: 1963.503, text: 'A cuarenta y sesenta gramos por kilogramo,' },
  { start: 1963.623, end: 1970.157, text: 'el fuerte aumento de la <font color="#FFFF00">presión</font> <font color="#FFFF00">osmótica</font>' },
  { start: 1970.277, end: 1976.790, text: 'profundiza el <font color="#FFFF00">mínimo secundario</font>, dando como resultado la formación' },
  { start: 1976.910, end: 1980.093, text: 'de aglomerados y luego una red floculada.' },
  { start: 1980.213, end: 1981.113, text: '' },
  { start: 1981.233, end: 1983.967, text: 'Pasemos al impacto de la concentración de' },
  { start: 1984.087, end: 1992.670, text: '<font color="#FFFF00">metilcelulosa</font> en la morfología de los <font color="#FFFF00">flóculos</font> dentro del látex.' },
  { start: 1992.790, end: 1998.037, text: 'Una cuadrícula de imágenes microscópicas compara concentraciones crecientes,' },
  { start: 1998.157, end: 2005.273, text: 'desde cero coma uno hasta cero coma cuatro por ciento de <font color="#FFFF00">metilcelulosa</font>.' },
  { start: 2005.393, end: 2011.793, text: 'Las tres series de imágenes permiten visualizar la estructura de la red antes del secado y luego' },
  { start: 2011.913, end: 2014.630, text: 'después del secado lento o rápido.' },
  { start: 2014.750, end: 2019.350, text: 'El aumento de la concentración y la cinética de evaporación modifican' },
  { start: 2019.470, end: 2025.033, text: 'significativamente el tamaño, cohesión y patrón de los agregados formados.' },
  { start: 2025.153, end: 2026.053, text: '' },
  { start: 2026.173, end: 2028.907, text: 'Veamos ahora los orígenes de la repulsión' },
  { start: 2029.027, end: 2033.410, text: 'electrostática en la superficie de las partículas de látex.' },
  { start: 2033.530, end: 2036.397, text: 'Se presentan tres mecanismos principales de' },
  { start: 2036.517, end: 2039.367, text: 'estabilización de carga superficial.' },
  { start: 2039.487, end: 2044.887, text: 'La adsorción de <font color="#FFFF00">tensioactivos</font> aniónicos o catiónicos' },
  { start: 2045.007, end: 2049.057, text: 'proporciona una carga superficial negativa o positiva.' },
  { start: 2049.177, end: 2055.957, text: 'La incorporación de <font color="#FFFF00">comonómeros</font> ionógenos injerta directamente cargas,' },
  { start: 2056.077, end: 2060.373, text: 'como grupos carboxilato, en la superficie del polímero.' },
  { start: 2060.493, end: 2061.393, text: '' },
  { start: 2061.513, end: 2065.580, text: 'Sigamos con el papel esencial de los ácidos ionoméricos <font' },
  { start: 2065.700, end: 2071.417, text: 'color="#FFFF00">comonómeros</font> en la estabilización eléctrica de los látex.' },
  { start: 2071.537, end: 2074.870, text: 'La distribución superficial depende de la relativa' },
  { start: 2074.990, end: 2078.170, text: 'la solubilidad en agua y en la fase orgánica,' },
  { start: 2078.290, end: 2082.807, text: 'mientras que el pKa y la disociación influyen en la cinética.' },
  { start: 2082.927, end: 2085.927, text: 'Una tabla comparativa detalla las propiedades' },
  { start: 2086.047, end: 2089.340, text: 'físicas y químicas de seis ácidos: fumárico,' },
  { start: 2089.460, end: 2094.050, text: 'maleico, itacónico, metacrílico, acrílico y crotónico.' },
  { start: 2094.170, end: 2098.417, text: 'El ácido acrílico destaca como uno de los mejores candidatos,' },
  { start: 2098.537, end: 2103.053, text: 'debido a su miscibilidad en agua y su solubilidad en tolueno.' },
  { start: 2103.173, end: 2104.073, text: '' },
  { start: 2104.193, end: 2111.573, text: 'Veamos ahora la expresión matemática del <font color="#FFFF00">potencial de repulsión electrostática</font>,' },
  { start: 2111.693, end: 2115.790, text: 'U R, en la <font color="#FFFF00">teoría DLVO</font>.' },
  { start: 2115.910, end: 2121.270, text: 'Un diagrama, a la izquierda, muestra la interpenetración y superposición de' },
  { start: 2121.390, end: 2127.353, text: 'capas dobles eléctricas alrededor de dos partículas de radio a, separadas por R.' },
  { start: 2127.473, end: 2133.053, text: 'La ecuación expresa la energía potencial en función de la permitividad del medio,' },
  { start: 2133.173, end: 2139.690, text: 'el potencial superficial de cero psi y el <font color="#FFFF00">tamaño de partícula</font>.' },
  { start: 2139.810, end: 2147.610, text: 'Implica la <font color="#FFFF00">longitud</font> <font color="#FFFF00">Debye</font> lambda y sigue siendo válida para' },
  { start: 2147.730, end: 2154.847, text: 'una relación entre el radio y la <font color="#FFFF00">Longitud de Debye</font> mucho mayor que uno.' },
  { start: 2154.967, end: 2155.867, text: '' },
  { start: 2155.987, end: 2160.633, text: 'Esto resalta la importancia del espesor de la doble capa eléctrica,' },
  { start: 2160.753, end: 2169.517, text: 'o <font color="#FFFF00">longitud</font> <font color="#FFFF00">Adiós</font>, para <font color="#FFFF00">estabilidad</font>.' },
  { start: 2169.637, end: 2173.950, text: 'A la derecha, un diagrama representa la capa rígida de Stern y' },
  { start: 2174.070, end: 2176.317, text: 'la capa difusa de Gouy-Chapman,' },
  { start: 2176.437, end: 2182.887, text: 'con la caída del potencial eléctrico hasta el <font color="#FFFF00">potencial zeta</font>.' },
  { start: 2183.007, end: 2186.607, text: 'La ecuación expresa la caída exponencial del potencial' },
  { start: 2186.727, end: 2191.777, text: 'eléctrico psi de x en función de la distancia x y el parámetro kappa.' },
  { start: 2191.897, end: 2201.477, text: 'El gráfico de la izquierda muestra que reducir el espesor de la doble capa reduce la <font color="#FFFF00">barrera energética</font> Phi max,' },
  { start: 2201.597, end: 2205.847, text: 'que promueve la <font color="#FFFF00">floculación</font>.' },
  { start: 2205.967, end: 2206.867, text: '' },
  { start: 2206.987, end: 2211.833, text: 'Veamos cómo la presencia de iones elimina la repulsión electrostática,' },
  { start: 2211.953, end: 2216.937, text: 'reduciendo la <font color="#FFFF00">longitud de Debye</font> lambda.' },
  { start: 2217.057, end: 2219.457, text: 'La fórmula general expresa lambda en' },
  { start: 2219.577, end: 2223.137, text: 'función de la permitividad, temperatura, también' },
  { start: 2223.257, end: 2227.173, text: 'como la carga y concentración de los iones opuestos.' },
  { start: 2227.293, end: 2231.873, text: 'Para una sal monovalente en agua a veinticinco grados centígrados,' },
  { start: 2231.993, end: 2237.357, text: 'la expresión se simplifica: cero punto tres dividido por la raíz de ci.' },
  { start: 2237.477, end: 2247.370, text: 'Una tabla ilustra el efecto de la <font color="#FFFF00">fuerza</font> <font color="#FFFF00">iónica</font>: cuanto más aumenta la concentración,' },
  { start: 2247.490, end: 2253.453, text: 'más disminuye drásticamente el espesor de la doble capa, de cien a un nanómetro.' },
  { start: 2253.573, end: 2254.473, text: '' },
  { start: 2254.593, end: 2261.040, text: 'Estudiemos ahora el efecto de agregar cationes divalentes <font color="#FFFF00">calcio</font>,' },
  { start: 2261.160, end: 2266.723, text: 'Ca 2 plus, sobre la <font color="#FFFF00">estabilidad</font> de los látex.' },
  { start: 2266.843, end: 2270.937, text: 'Se esquematizan tres estados del sistema: látex estable,' },
  { start: 2271.057, end: 2275.440, text: 'la formación de coagulados y la gelificación de partículas.' },
  { start: 2275.560, end: 2279.693, text: 'Dos imágenes de microscopio muestran que en presencia de <font' },
  { start: 2279.813, end: 2283.147, text: 'color="#FFFF00">cloruro de calcio</font> sin <font' },
  { start: 2283.267, end: 2288.227, text: 'color="#FFFF00">surfactante</font>, el látex se coagula, mientras que' },
  { start: 2288.347, end: 2295.643, text: 'con un diez por ciento de <font color="#FFFF00">surfactante</font>, la dispersión permanece estable.' },
  { start: 2295.763, end: 2300.057, text: 'Parámetros externos, como la temperatura, la agitación y la' },
  { start: 2300.177, end: 2304.623, text: 'presencia de <font color="#FFFF00">surfactantes</font>, influyen' },
  { start: 2304.743, end: 2310.727, text: 'fuertemente en el tipo y la cinética de la <font color="#FFFF00">agregación</font>.' },
  { start: 2310.847, end: 2311.747, text: '' },
  { start: 2311.867, end: 2318.600, text: 'Un <font color="#FFFF00">diagrama de fases</font> ilustra la <font color="#FFFF00">estabilidad</font>' },
  { start: 2318.720, end: 2327.617, text: 'del látex en presencia de cationes <font color="#FFFF00">calcio</font>, dependiendo del contenido de ácido de la superficie.' },
  { start: 2327.737, end: 2336.050, text: 'El gráfico muestra el porcentaje de cloruro de <font color="#FFFF00">calcio</font> en función de la tasa de grupos ácidos,' },
  { start: 2336.170, end: 2339.353, text: 'expresado en microequivalentes por gramo.' },
  { start: 2339.473, end: 2344.567, text: 'Se identifican tres áreas: una zona de gel con bajo contenido de ácido,' },
  { start: 2344.687, end: 2351.670, text: 'una zona intermedia de coagulados o grumos y una zona de <font color="#FFFF00">estabilidad</font>.' },
  { start: 2351.790, end: 2356.457, text: 'El aumento de la densidad del ácido en la superficie de las partículas' },
  { start: 2356.577, end: 2363.427, text: 'amplía el rango de <font color="#FFFF00">estabilidad</font> ante la adición de sales divalentes.' },
  { start: 2363.547, end: 2364.447, text: '' },
  { start: 2364.567, end: 2371.300, text: 'Añadamos ahora la influencia conjunta del <font color="#FFFF00">pH</font> y la concentración de <font' },
  { start: 2371.420, end: 2378.070, text: 'color="#FFFF00">calcio</font> sobre la <font color="#FFFF00">estabilidad</font> de los látex.' },
  { start: 2378.190, end: 2385.150, text: 'Un diagrama representa la concentración de <font color="#FFFF00">calcio</font>, en moles por litro,' },
  { start: 2385.270, end: 2391.833, text: 'frente al <font color="#FFFF00">pH</font>, y define diferentes regiones de estado físico.' },
  { start: 2391.953, end: 2394.153, text: 'A una concentración baja de <font' },
  { start: 2394.273, end: 2397.853, text: 'color="#FFFF00">calcio</font>, el sistema permanece' },
  { start: 2397.973, end: 2401.667, text: 'estable; a valores más elevados, y dependiendo del' },
  { start: 2401.787, end: 2408.263, text: '<font color="#FFFF00">pH</font>, aparecen zonas metaestables, gel o grumos inusuales.' },
  { start: 2408.383, end: 2415.030, text: 'En <font color="#FFFF00">pH</font> ácido y alto contenido de <font color="#FFFF00">calcio</font>,' },
  { start: 2415.150, end: 2424.067, text: 'la <font color="#FFFF00">floculación</font> seguida de una reorganización homogénea permite la fluidificación de la suspensión.' },
  { start: 2424.187, end: 2425.087, text: '' },
  { start: 2425.207, end: 2428.053, text: 'Nos acercamos ahora a una nueva sección,' },
  { start: 2428.173, end: 2432.957, text: 'titulada “Protección de los látex en relación con su aplicación”.' },
  { start: 2433.077, end: 2438.657, text: 'Anuncia el tratamiento de los mecanismos de estabilización y protección coloidal,' },
  { start: 2438.777, end: 2441.293, text: 'de origen osmótico y eléctrico.' },
  { start: 2441.413, end: 2448.820, text: 'Un friso visual, al pie de la página, recuerda las nociones de <font color="#FFFF00">agregación</font>,' },
  { start: 2448.940, end: 2456.637, text: '<font color="#FFFF00">potencial zeta</font>, control reológico y <font color="#FFFF00">agotamiento</font>.' },
  { start: 2456.757, end: 2461.090, text: 'Este capítulo cubre el ajuste de las propiedades de la superficie' },
  { start: 2461.210, end: 2466.793, text: 'para adaptar el comportamiento del látex a las limitaciones de la aplicación.' },
  { start: 2466.913, end: 2467.813, text: '' },
  { start: 2467.933, end: 2473.713, text: 'Volvamos a los orígenes de la <font color="#FFFF00">repulsión electrostática</font>,' },
  { start: 2473.833, end: 2477.750, text: 'esta vez desde el ángulo de la protección del látex.' },
  { start: 2477.870, end: 2484.763, text: 'Se ilustran tres rutas de carga superficial: el <font color="#FFFF00">surfactante</font> aniónico,' },
  { start: 2484.883, end: 2492.533, text: 'el <font color="#FFFF00">surfactante</font> catiónico y el <font color="#FFFF00">comonómero</font> ionógeno.' },
  { start: 2492.653, end: 2498.833, text: 'La adsorción de <font color="#FFFF00">surfactantes</font> proporciona una carga extraíble,' },
  { start: 2498.953, end: 2506.670, text: 'mientras que la incorporación de <font color="#FFFF00">comonómeros</font> crea cargas covalentes permanentes.' },
  { start: 2506.790, end: 2511.923, text: 'Estos mecanismos determinan la <font color="#FFFF00">estabilidad</font> de la' },
  { start: 2512.043, end: 2517.627, text: 'doble capa eléctrica durante los procesos de almacenamiento e implementación.' },
  { start: 2517.747, end: 2522.710, text: 'Pausa de 5 segundos, cambie de diapositiva. Veamos ahora el papel' },
  { start: 2522.830, end: 2527.680, text: 'de las macromoléculas en la superficie de las partículas de látex.' },
  { start: 2527.800, end: 2531.667, text: 'Dos representaciones de partículas rodeadas por cadenas de' },
  { start: 2531.787, end: 2537.103, text: 'polímeros ilustran los diferentes métodos de modificación de superficies.' },
  { start: 2537.223, end: 2542.203, text: 'A la izquierda, la capa macromolecular proviene de la adsorción de <font' },
  { start: 2542.323, end: 2549.040, text: 'color="#FFFF00">tensioactivos</font> no iónicos o del injerto químico de alcohol polivinílico.' },
  { start: 2549.160, end: 2553.340, text: 'A la derecha, La <font color="#FFFF00">estabilización</font>' },
  { start: 2553.460, end: 2557.660, text: '<font color="#FFFF00">estérica</font> se logra utilizando <font' },
  { start: 2557.780, end: 2564.810, text: 'color="#FFFF00">comonómeros</font>, tales como polioxietileno o macrómeros de éster metacrílico.' },
  { start: 2564.930, end: 2565.830, text: '' },
  { start: 2565.950, end: 2572.930, text: 'Detallemos ahora la <font color="#FFFF00">estabilización</font> <font color="#FFFF00">estérica</font>,' },
  { start: 2573.050, end: 2582.680, text: 'a través de dos aportaciones: el <font color="#FFFF00">efecto osmótico</font> y la <font color="#FFFF00">restricción de volumen</font>.' },
  { start: 2582.800, end: 2591.113, text: 'El <font color="#FFFF00">efecto osmótico</font> genera una sobreconcentración local de polímero en la zona de interacción,' },
  { start: 2591.233, end: 2595.883, text: 'provocando una demanda de disolvente que repele las partículas.' },
  { start: 2596.003, end: 2605.003, text: 'La <font color="#FFFF00">restricción de volumen</font> induce una pérdida de entropía conformacional de las macromoléculas hidrofílicas' },
  { start: 2605.123, end: 2607.973, text: 'y crea fuerzas elásticas repulsivas.' },
  { start: 2608.093, end: 2612.027, text: 'La energía libre de la <font color="#FFFF00">estabilización' },
  { start: 2612.147, end: 2616.553, text: 'estérica</font>, Delta G ST, combina el término de mezcla,' },
  { start: 2616.673, end: 2621.617, text: 'Delta G M, y el término de restricción de volumen, Delta G RV.' },
  { start: 2621.737, end: 2622.637, text: '' },
  { start: 2622.757, end: 2626.157, text: 'Hagamos un balance con una tabla comparativa de las' },
  { start: 2626.277, end: 2629.877, text: 'ventajas y desventajas de los tres métodos principales' },
  { start: 2629.997, end: 2633.823, text: 'de estabilización coloidal: electrostático, osmótico' },
  { start: 2633.943, end: 2638.260, text: 'y por <font color="#FFFF00">restricción de volumen</font>.' },
  { start: 2638.380, end: 2642.647, text: 'La estabilización electrostática es insensible a las variaciones' },
  { start: 2642.767, end: 2647.147, text: 'de temperatura y a la calidad del disolvente, pero su principal' },
  { start: 2647.267, end: 2651.917, text: 'punto débil es la extrema sensibilidad a la presencia de iones.' },
  { start: 2652.037, end: 2655.437, text: 'La estabilización osmótica no se ve afectada ni por' },
  { start: 2655.557, end: 2659.023, text: 'la <font color="#FFFF00">fuerza iónica</font> ni por' },
  { start: 2659.143, end: 2662.723, text: 'la temperatura, pero es vulnerable a la elección de' },
  { start: 2662.843, end: 2668.093, text: 'disolventes y competencia con <font color="#FFFF00">surfactantes</font>.' },
  { start: 2668.213, end: 2671.327, text: 'Finalmente, la estabilización mediante <font' },
  { start: 2671.447, end: 2674.647, text: 'color="#FFFF00">restricción de volumen</font> es' },
  { start: 2674.767, end: 2678.813, text: 'insensible a los iones y a la calidad del disolvente, pero' },
  { start: 2678.933, end: 2684.650, text: 'está sujeta a la influencia directa de la temperatura y las tensiones de corte.' },
  { start: 2684.770, end: 2685.670, text: '' },
  { start: 2685.790, end: 2689.923, text: 'Pasemos ahora al modelo de <font color="#FFFF00">agregación de' },
  { start: 2690.043, end: 2695.427, text: 'clústeres</font> o <font color="#FFFF00">DLCA</font> de difusión limitada.' },
  { start: 2695.547, end: 2698.927, text: 'En este proceso, el crecimiento de los agregados' },
  { start: 2699.047, end: 2702.380, text: 'está controlado por la difusión de partículas y se' },
  { start: 2702.500, end: 2706.817, text: 'lleva a cabo por colisión de cúmulos de tamaños similares.' },
  { start: 2706.937, end: 2709.937, text: 'Esta cinética de asociación por pares conduce' },
  { start: 2710.057, end: 2714.107, text: 'a estructuras con una distribución de tamaño estrecha.' },
  { start: 2714.227, end: 2719.540, text: 'El grupo fractal formado sigue la ley de escala M es igual a R g elevado a d,' },
  { start: 2719.660, end: 2726.110, text: 'con una <font color="#FFFF00">dimensión fractal</font> d de aproximadamente un punto ocho.' },
  { start: 2726.230, end: 2727.130, text: '' },
  { start: 2727.250, end: 2737.167, text: 'Continuaremos con el régimen de <font color="#FFFF00">agregación de clústeres</font> o <font color="#FFFF00">RLCA</font> de reacción limitada.' },
  { start: 2737.287, end: 2742.733, text: 'La <font color="#FFFF00">agregación</font> ya no está limitada por la difusión,' },
  { start: 2742.853, end: 2747.703, text: 'sino por la cinética del proceso de aglomeración química o física.' },
  { start: 2747.823, end: 2751.690, text: 'La probabilidad de cruzar la <font color="#FFFF00">barrera' },
  { start: 2751.810, end: 2757.127, text: 'energética</font> E b sigue una ley exponencial de menos E b sobre k B T.' },
  { start: 2757.247, end: 2763.227, text: 'Este régimen conduce a una distribución de tamaño más amplia y agregados más compactos,' },
  { start: 2763.347, end: 2768.863, text: 'de <font color="#FFFF00">dimensión fractal</font> d cerca de dos punto tres.' },


  { start: 2768.864, end:2770.000, text: 'Gracias por su atención. Vaya al capítulo 3.' },

];




const SUBTITLES_IT_CH2 = [
{ start: 1.000, end: 1.999, text: 'Benvenuti nel programma BRIDGE -<font color="#FFFF00"> Bridging Research and Inclusive Digital Education</font>' },

  { start: 2.000, end: 2.467, text: 'Benvenuti al secondo modulo di questa' },
  { start: 2.587, end: 5.500, text: 'presentazione, incentrato sulle proprietà' },
  { start: 5.620, end: 9.203, text: 'chiave dei polimeri in emulsione e dei lattici.' },
  { start: 9.323, end: 14.640, text: 'Questo corso è presentato da Gérard Bacquet per la società ScienceExpert.' },
  { start: 14.760, end: 15.660, text: '' },
  { start: 15.780, end: 20.760, text: 'Partiamo dal fenomeno della <font color="#FFFF00">filmificazione</font>,' },
  { start: 20.880, end: 27.130, text: 'fondamentale per tutte le applicazioni dove è richiesta la formazione di una pellicola.' },
  { start: 27.250, end: 29.650, text: 'Una serie di illustrazioni mostra il' },
  { start: 29.770, end: 32.617, text: 'processo, dall\'impilamento di particelle' },
  { start: 32.737, end: 36.987, text: 'sferiche alla loro deformazione in strutture poliedriche.' },
  { start: 37.107, end: 45.687, text: 'I diagrammi descrivono in dettaglio anche l\'<font color="#FFFF00">evaporazione</font> dell\'<font color="#FFFF00">acqua</font>,' },
  { start: 45.807, end: 55.657, text: 'le <font color="#FFFF00">forze capillari</font> e la <font color="#FFFF00">coalescenza</font> delle catene polimeriche su scala particellare.' },
  { start: 55.777, end: 56.677, text: '' },
  { start: 56.797, end: 61.330, text: 'Vediamo ora le fasi successive di trasformazione delle particelle di' },
  { start: 61.450, end: 66.100, text: 'lattice in una <font color="#FFFF00">pellicola continua</font>.' },
  { start: 66.220, end: 76.133, text: 'Tutto inizia con l\'<font color="#FFFF00">evaporazione dell\'</font> <font color="#FFFF00">acqua</font> e il suo assorbimento da parte del supporto,' },
  { start: 76.253, end: 79.903, text: 'che riunisce le particelle in una pila compatta.' },
  { start: 80.023, end: 86.537, text: 'Sotto l\'azione delle <font color="#FFFF00">forze</font> <font color="#FFFF00">capillari</font>,' },
  { start: 86.657, end: 92.707, text: 'le sfere si deformano gradualmente e adottano una struttura poliedrica a nido d\'ape.' },
  { start: 92.827, end: 100.273, text: 'Infine, l\'<font color="#FFFF00">interdiffusione</font> delle catene polimeriche alle interfacce garantisce la' },
  { start: 100.393, end: 108.843, text: 'completa <font color="#FFFF00">coalescenza</font> e la formazione del <font color="#FFFF00">film omogeneo</font> finale.' },
  { start: 108.963, end: 109.863, text: '' },
  { start: 109.983, end: 116.363, text: 'Per descrivere questa asciugatura ci affidiamo al <font color="#FFFF00">modello Croll</font>,' },
  { start: 116.483, end: 124.267, text: 'che distingue tre fasi nella velocità di asciugatura di una <font color="#FFFF00">pellicola di lattice</font>.' },
  { start: 124.387, end: 128.767, text: 'Durante la prima fase si forma in superficie uno strato poroso,' },
  { start: 128.887, end: 135.137, text: 'sopra uno strato di transizione più concentrato ed uno strato umido che rimane intatto.' },
  { start: 135.257, end: 139.570, text: 'Nella fase due, lo strato umido iniziale è scomparso e l\'<font' },
  { start: 139.690, end: 142.557, text: 'color="#FFFF00">acqua rimanente è scomparsa' },
  { start: 142.677, end: 147.927, text: 'l\'evaporazione</font> proviene direttamente dallo strato di transizione.' },
  { start: 148.047, end: 149.360, text: 'Nella terza fase,' },
  { start: 149.480, end: 160.577, text: 'lo strato di transizione scompare a sua volta: la pellicola è quindi completamente asciutta e pronta per la fase di <font color="#FFFF00">coalescenza</font>.' },
  { start: 160.697, end: 161.597, text: '' },
  { start: 161.717, end: 165.963, text: 'Questo modello è stato validato teoricamente e cineticamente,' },
  { start: 166.083, end: 169.200, text: 'per le fasi uno e due dell\'evaporazione.' },
  { start: 169.320, end: 175.727, text: 'Un grafico, a sinistra, mostra l\'evoluzione nel tempo della frazione volumetrica solida,' },
  { start: 175.847, end: 177.563, text: 'divisa in tre fasi.' },
  { start: 177.683, end: 179.063, text: 'Per la prima fase,' },
  { start: 179.183, end: 187.213, text: 'il tasso di perdita d\'acqua è costante: dipende solo dalla superficie di evaporazione e dal flusso evaporativo.' },
  { start: 187.333, end: 190.313, text: 'Per la fase due, la cinetica dipende dalla' },
  { start: 190.433, end: 193.880, text: 'concentrazione di acqua in superficie, che riduce' },
  { start: 194.000, end: 199.583, text: 'gradualmente la velocità di essiccazione in funzione dello spessore del film.' },
  { start: 199.703, end: 200.603, text: '' },
  { start: 200.723, end: 204.037, text: 'Consideriamo ora la fase tre dell\'essiccazione,' },
  { start: 204.157, end: 210.207, text: 'incentrata sulla deformazione delle particelle e sull\'espulsione dell\'acqua residua.' },
  { start: 210.327, end: 217.373, text: 'Le <font color="#FFFF00">forze capillari</font> favoriscono la deformazione delle particelle elastiche,' },
  { start: 217.493, end: 221.277, text: 'mentre le tensioni elastiche interne si oppongono.' },
  { start: 221.397, end: 223.957, text: 'Un diagramma, in alto a sinistra,' },
  { start: 224.077, end: 234.060, text: 'mostra la differenza nella <font color="#FFFF00">pressione capillare</font> creata dai menischi dell\'acqua tra le sfere di lattice in contatto.' },
  { start: 234.180, end: 236.113, text: 'Una tabella riassume la <font' },
  { start: 236.233, end: 239.233, text: 'color="#FFFF00">pressione capillare</font> in' },
  { start: 239.353, end: 242.820, text: 'funzione del raggio delle particelle e del numero di' },
  { start: 242.940, end: 248.970, text: 'sfere in contatto: le pressioni sono molto elevate per le particelle più piccole.' },
  { start: 249.090, end: 249.990, text: '' },
  { start: 250.110, end: 253.977, text: 'Questa distorsione è stata osservata nel lavoro di tesi di' },
  { start: 254.097, end: 258.660, text: 'François Magnin, sostenuto presso l\'Università di Parigi 6.' },
  { start: 258.780, end: 261.760, text: 'Riguardano la morfologia su scale diverse,' },
  { start: 261.880, end: 265.663, text: 'di film di lattice bidispersi dopo l\'essiccazione.' },
  { start: 265.783, end: 271.250, text: 'Un\'immagine al microscopio a forza atomica mostra la deformazione delle particelle' },
  { start: 271.370, end: 276.887, text: 'sferiche in una rete di cellule poliedriche che misurano duecento nanometri.' },
  { start: 277.007, end: 277.907, text: '' },
  { start: 278.027, end: 282.740, text: 'Torniamo alla modellazione dell\'equilibrio meccanico della fase tre,' },
  { start: 282.860, end: 289.110, text: 'tra <font color="#FFFF00">forze capillari</font> deformanti e vincoli elastici opposti.' },
  { start: 289.230, end: 294.343, text: 'La <font color="#FFFF00">forza capillare</font> favorisce la deformazione,' },
  { start: 294.463, end: 303.247, text: 'mentre la risposta L\'elasticità delle particelle è descritta dalla <font color="#FFFF00">teoria del contatto di Hertz</font>.' },
  { start: 303.367, end: 307.347, text: 'Per ottenere la <font color="#FFFF00">coalescenza</font>,' },
  { start: 307.467, end: 314.783, text: 'la <font color="#FFFF00">forza capillare</font> deve prevalere sulla resistenza meccanica del polimero.' },
  { start: 314.903, end: 317.370, text: 'L\'ultimo criterio indica che il <font' },
  { start: 317.490, end: 321.290, text: 'color="#FFFF00">modulo di taglio</font> del polimero deve' },
  { start: 321.410, end: 325.257, text: 'rimanere al di sotto di un valore limite, proporzionale' },
  { start: 325.377, end: 331.427, text: 'alla tensione interfacciale e inversamente proporzionale al raggio della particella.' },
  { start: 331.547, end: 332.447, text: '' },
  { start: 332.567, end: 340.613, text: 'Questo ci porta alla <font color="#FFFF00">temperatura</font> <font color="#FFFF00">formazione minima del film</font>,' },
  { start: 340.733, end: 347.183, text: 'parametro chiave delle condizioni di <font color="#FFFF00">coalescenza</font> del lattice.' },
  { start: 347.303, end: 349.283, text: 'Su banco termico verticale,' },
  { start: 349.403, end: 356.537, text: 'la pellicola è trasparente e perfettamente <font color="#FFFF00">coalescenza</font> alla massima luminosità' },
  { start: 356.657, end: 361.687, text: 'temperature, mentre a basse temperature diventa opaco e polveroso.' },
  { start: 361.807, end: 368.007, text: 'La <font color="#FFFF00">coalescenza</font> è possibile solo se particelle e acqua coesistono' },
  { start: 368.127, end: 374.177, text: 'e se il <font color="#FFFF00">modulo di taglio</font> rimane sufficientemente basso.' },
  { start: 374.297, end: 383.010, text: 'Se la temperatura di asciugatura è inferiore alla <font color="#FFFF00">temperatura di formazione della pellicola</font> minima,' },
  { start: 383.130, end: 388.580, text: 'la pellicola non può <font color="#FFFF00">coalescere</font> correttamente.' },
  { start: 388.700, end: 389.600, text: '' },
  { start: 389.720, end: 396.120, text: 'Vediamo ora l\'influenza della <font color="#FFFF00">dimensione delle particelle</font> su questa' },
  { start: 396.240, end: 403.623, text: '<font color="#FFFF00">temperatura minima</font> <font color="#FFFF00">formazione della pellicola</font>.' },
  { start: 403.743, end: 410.503, text: 'Un primo grafico, a sinistra, mostra la caduta del <font color="#FFFF00">modulo di taglio</font>' },
  { start: 410.623, end: 417.203, text: 'in corrispondenza della <font color="#FFFF00">transizione vetrosa</font>, che segna il passaggio' },
  { start: 417.323, end: 424.240, text: 'dallo <font color="#FFFF00">stato vetroso</font> allo <font color="#FFFF00">stato gommoso</font>.' },
  { start: 424.360, end: 428.320, text: 'Un secondo grafico, a destra, illustra l\'aumento della' },
  { start: 428.440, end: 432.307, text: 'temperatura minima di <font color="#FFFF00">formazione del' },
  { start: 432.427, end: 438.457, text: 'film</font> con il raggio delle particelle, da trenta a centocinquanta nanometri.' },
  { start: 438.577, end: 443.043, text: 'Le fiale dimostrano che una dimensione delle particelle più piccola' },
  { start: 443.163, end: 447.563, text: 'promuove la <font color="#FFFF00">coalescenza</font> a temperature' },
  { start: 447.683, end: 452.980, text: 'più basse, aumentando le <font color="#FFFF00">forze capillari</font>.' },
  { start: 453.100, end: 454.000, text: '' },
  { start: 454.120, end: 456.300, text: 'Apriamo ora una nuova sezione,' },
  { start: 456.420, end: 461.870, text: 'dedicata alle proprietà meccaniche dei polimeri in emulsione e dei lattici.' },
  { start: 461.990, end: 469.637, text: 'Queste proprietà riguardano i materiali <font color="#FFFF00">compositi</font> e molte applicazioni industriali:' },
  { start: 469.757, end: 472.700, text: 'vernici, carta, tessuti o colle.' },
  { start: 472.820, end: 475.647, text: 'Un fregio illustrato, a fondo pagina,' },
  { start: 475.767, end: 481.750, text: 'ricorda le fasi microstrutturali di deformazione e organizzazione delle particelle.' },
  { start: 481.870, end: 482.770, text: '' },
  { start: 482.890, end: 486.070, text: 'Cominciamo con gli stati fisici del polimero,' },
  { start: 486.190, end: 492.107, text: 'in base alla sua <font color="#FFFF00">massa molare</font> e alla sua temperatura.' },
  { start: 492.227, end: 496.140, text: 'Un primo <font color="#FFFF00">diagramma di fase</font>,' },
  { start: 496.260, end: 500.240, text: 'a sinistra, unisce la temperatura e la massa molare media' },
  { start: 500.360, end: 504.970, text: 'ponderale, e delimita le zone vetrose, gommoso e liquido.' },
  { start: 505.090, end: 510.583, text: 'Un secondo grafico, a destra, mostra il calo del <font color="#FFFF00">modulo' },
  { start: 510.703, end: 516.617, text: 'di</font> <font color="#FFFF00">Giovane</font> con la temperatura, dal passaggio dallo' },
  { start: 516.737, end: 524.433, text: '<font color="#FFFF00">stato vetroso</font> allo <font color="#FFFF00">stato gommoso</font>, quindi fluido.' },
  { start: 524.553, end: 530.200, text: 'Alle basse temperature il polimero presenta un modulo elastico elevato e costante:' },
  { start: 530.320, end: 534.437, text: 'questo è lo <font color="#FFFF00">stato vetroso</font>.' },
  { start: 534.557, end: 538.603, text: 'Oltre la <font color="#FFFF00">transizione vetrosa</font>,' },
  { start: 538.723, end: 549.173, text: 'la <font color="#FFFF00">lastra di gomma</font> ha valori di modulo compresi tra dieci alla potenza di quattro e dieci alla potenza di sei megapascal.' },
  { start: 549.293, end: 554.587, text: 'A temperature più elevate, una transizione finale porta allo stato fluido,' },
  { start: 554.707, end: 559.223, text: 'descritto da specifiche proprietà reologiche pseudoplastiche.' },
  { start: 559.343, end: 560.243, text: '' },
  { start: 560.363, end: 566.697, text: 'Vediamo ora l\'effetto delle principali variabili sul <font color="#FFFF00">comportamento termo-' },
  { start: 566.817, end: 570.267, text: 'viscoelastico</font> dei polimeri statistici.' },
  { start: 570.387, end: 579.033, text: 'Un grafico rappresenta l\'evoluzione del <font color="#FFFF00">modulo elastico</font> del lattice in funzione della temperatura,' },
  { start: 579.153, end: 584.603, text: 'per diverse formulazioni di <font color="#FFFF00">stirene-butadiene</font>.' },
  { start: 584.723, end: 594.570, text: 'Il <font color="#FFFF00">modulo di Young</font> può essere modulato regolando la <font color="#FFFF00">temperatura di transizione vetrosa</font>,' },
  { start: 594.690, end: 599.207, text: 'grazie al rapporto tra <font color="#FFFF00">monomeri</font>.' },
  { start: 599.327, end: 610.573, text: 'Il livello della <font color="#FFFF00">lastra di gomma</font> dipende dalla <font color="#FFFF00">massa molare</font> o dal <font color="#FFFF00">tasso di gel</font>,' },
  { start: 610.693, end: 615.277, text: 'qui confrontato per tassi del trenta e del settanta per cento.' },
  { start: 615.397, end: 616.297, text: '' },
  { start: 616.417, end: 622.417, text: 'Confrontiamo ora le curve sperimentali di <font color="#FFFF00">viscoelasticità</font> con' },
  { start: 622.537, end: 627.987, text: 'i modelli meccanici di Maxwell e <font color="#FFFF00">Voigt-Kelvin</font>.' },
  { start: 628.107, end: 632.307, text: 'I diagrammi in alto illustrano il <font color="#FFFF00">modello' },
  { start: 632.427, end: 636.787, text: 'Maxwell</font>, in serie, e il <font color="#FFFF00">modello' },
  { start: 636.907, end: 643.317, text: 'Voigt-Kelvin</font>, in parallelo, per descrivere le componenti elastiche e viscose.' },
  { start: 643.437, end: 647.750, text: 'A sinistra, la trama della <font color="#FFFF00">conservazione' },
  { start: 647.870, end: 651.537, text: 'il modulo</font> G\' rispetto alla temperatura mostra la' },
  { start: 651.657, end: 655.590, text: 'transizione tra lo <font color="#FFFF00">stato</font> <font' },
  { start: 655.710, end: 661.027, text: 'color="#FFFF00">vetroso</font> e il plateau gommoso per diversi polimeri.' },
  { start: 661.147, end: 668.060, text: 'A destra, il grafico <font color="#FFFF00"><font color="#FFFF00">perdita</font> G\'\' del modulo</font>' },
  { start: 668.180, end: 676.363, text: 'evidenzia i picchi di dissipazione di energia caratteristici della <font color="#FFFF00">transizione vetrosa</font>.' },
  { start: 676.483, end: 677.383, text: '' },
  { start: 677.503, end: 681.617, text: 'Passiamo all\'<font color="#FFFF00">equazione di Fox</font>,' },
  { start: 681.737, end: 693.920, text: 'che permette di calcolare la <font color="#FFFF00">temperatura di transizione</font> <font color="#FFFF00">vetrosa</font> teorica di un <font color="#FFFF00">copolimero</font>.' },
  { start: 694.040, end: 705.220, text: 'Esprime l\'inverso della <font color="#FFFF00">Tg</font> complessiva come la somma ponderata delle frazioni di massa di ciascun <font color="#FFFF00">monomero</font>,' },
  { start: 705.340, end: 710.257, text: 'divisa per la rispettiva <font color="#FFFF00">Tg</font> in Kelvin.' },
  { start: 710.377, end: 712.910, text: 'Una tabella riassume le temperature di' },
  { start: 713.030, end: 715.230, text: 'transizione vetrosa di vari <font' },
  { start: 715.350, end: 718.597, text: 'color="#FFFF00">omopolimeri</font> comuni, dal' },
  { start: 718.717, end: 723.967, text: 'polibutadiene a meno centododici gradi al PMMA a centotto gradi Celsius.' },
  { start: 724.087, end: 724.987, text: '' },
  { start: 725.107, end: 728.887, text: 'Ora affrontiamo questa equazione con la realtà: ecco i' },
  { start: 729.007, end: 731.273, text: 'dati per novantanove lattici <font' },
  { start: 731.393, end: 737.157, text: 'color="#FFFF00">stirene-butadiene</font>, rispetto alla curva di Fox teorica.' },
  { start: 737.277, end: 743.010, text: 'Il grafico presenta la <font color="#FFFF00">temperatura di transizione vetrosa</font>' },
  { start: 743.130, end: 749.847, text: 'in funzione della percentuale in massa di stirene nel <font color="#FFFF00">copolimero</font>.' },
  { start: 749.967, end: 754.367, text: 'La formula applicata alle frazioni di massa di butadiene e stirene' },
  { start: 754.487, end: 759.403, text: 'consente di aggiustare con precisione la linea di tendenza teorica.' },
  { start: 759.523, end: 764.950, text: 'I punti sperimentali, provenienti da vari processi e produttori industriali,' },
  { start: 765.070, end: 768.320, text: 'mostrano un ottimo accordo con il modello.' },
  { start: 768.440, end: 769.340, text: '' },
  { start: 769.460, end: 776.860, text: 'Diamo quindi un\'occhiata all\'impatto delle <font color="#FFFF00">forze di Keesom</font> e del momento di dipolo' },
  { start: 776.980, end: 783.497, text: 'dei legami secondari sulla <font color="#FFFF00">temperatura di transizione vetrosa</font>.' },
  { start: 783.617, end: 790.197, text: 'Una tabella presenta l\'aumento del <font color="#FFFF00">Tg</font> secondo lo schema sostituito,' },
  { start: 790.317, end: 795.967, text: 'dal polietilene a meno centodieci gradi al PTFE a centoventitré gradi Celsius.' },
  { start: 796.087, end: 801.647, text: 'Un grafico, in basso a sinistra, mostra la crescente correlazione tra la <font' },
  { start: 801.767, end: 806.500, text: 'color="#FFFF00">temperatura di</font> <font color="#FFFF00">transizione' },
  { start: 806.620, end: 812.917, text: 'vetrosa</font> e il <font color="#FFFF00">momento dipolare</font>, espresso in Debye.' },
  { start: 813.037, end: 819.037, text: 'La formula per l\'energia di interazione di Keesom conferma che il rafforzamento dei legami' },
  { start: 819.157, end: 825.473, text: 'dipolari secondari aumenta direttamente la <font color="#FFFF00">Tg</font> del polimero.' },
  { start: 825.593, end: 826.493, text: '' },
  { start: 826.613, end: 833.680, text: 'Vediamo ora l\'influenza delle transizioni termiche sui materiali <font color="#FFFF00">termoformati</font>' },
  { start: 833.800, end: 838.850, text: 'e <font color="#FFFF00">compositi</font> a base di lattice SB e SBAn.' },
  { start: 838.970, end: 843.370, text: 'Un grafico confronta l\'evoluzione del modulo di taglio in funzione' },
  { start: 843.490, end: 845.957, text: 'della temperatura per i sistemi <font' },
  { start: 846.077, end: 853.460, text: 'color="#FFFF00">stirene-butadiene</font> e <font color="#FFFF00">stirene-butadiene-acrilonitrile</font>.' },
  { start: 853.580, end: 862.960, text: 'L\'aggiunta di <font color="#FFFF00">acrilonitrile</font> modifica la pendenza di transizione e allarga la zona di rammollimento meccanico,' },
  { start: 863.080, end: 866.330, text: 'grazie alle interazioni polari introdotte.' },
  { start: 866.450, end: 873.383, text: 'Gli esempi di applicazione finali mostrano pannelli decorativi <font color="#FFFF00">termoformati</font>' },
  { start: 873.503, end: 879.020, text: 'ed elementi tessili strutturati per il design degli interni automobilistici.' },
  { start: 879.140, end: 880.040, text: '' },
  { start: 880.160, end: 884.607, text: 'Diamo ora un\'occhiata alla concentrazione di pigmento in volume,' },
  { start: 884.727, end: 889.357, text: 'chiamata <font color="#FFFF00">CVP</font>, o PVC in inglese.' },
  { start: 889.477, end: 895.677, text: 'La sua formula lo definisce come il rapporto tra il volume combinato di pigmenti e riempitivi' },
  { start: 895.797, end: 898.247, text: 'e il volume totale dei solidi.' },
  { start: 898.367, end: 905.347, text: 'Tre diagrammi illustrano i regimi di formulazione secondo il <font color="#FFFF00">CVP</font> critico,' },
  { start: 905.467, end: 909.717, text: 'a seconda della presenza o assenza di legante in eccesso.' },
  { start: 909.837, end: 914.750, text: 'Quando il <font color="#FFFF00">CVP</font> supera il valore critico, la' },
  { start: 914.870, end: 919.850, text: 'quantità di legante diventa insufficiente, il che provoca la comparsa di' },
  { start: 919.970, end: 925.353, text: '<font color="#FFFF00">porosità</font> e vuoti all\'interno della pellicola.' },
  { start: 925.473, end: 926.373, text: '' },
  { start: 926.493, end: 938.740, text: 'Questa <font color="#FFFF00">porosità</font> ci porta al <font color="#FFFF00">modulo</font> <font color="#FFFF00">de Young</font> dei <font color="#FFFF00">compositi</font> porosi,' },
  { start: 938.860, end: 947.110, text: 'un argomento che è tornato ampiamente studiato con l\'emergere della <font color="#FFFF00">produzione additiva</font>.' },
  { start: 947.230, end: 952.230, text: 'Un grafico mette a confronto diversi modelli teorici che descrivono il calo' },
  { start: 952.350, end: 960.533, text: 'del <font color="#FFFF00">modulo elastico</font> in funzione della <font color="#FFFF00">porosità</font> del volume.' },
  { start: 960.653, end: 969.387, text: 'Il <font color="#FFFF00">modello Bert</font> esprime il rapporto dei moduli in funzione della <font color="#FFFF00">porosità</font>' },
  { start: 969.507, end: 977.003, text: 'relativo, la <font color="#FFFF00">porosità</font> massima e un fattore di concentrazione dello stress.' },
  { start: 977.123, end: 980.323, text: 'Questo fattore K varia a seconda della geometria' },
  { start: 980.443, end: 983.890, text: 'delle inclusioni: zero virgola settantacinque per' },
  { start: 984.010, end: 988.173, text: 'particelle piatte come l\'argilla, e due per le sfere.' },
  { start: 988.293, end: 989.193, text: '' },
  { start: 989.313, end: 996.027, text: 'Applichiamo queste nozioni di <font color="#FFFF00">porosità</font> e rigidità ad un caso pratico:' },
  { start: 996.147, end: 999.730, text: 'la <font color="#FFFF00">carta patinata</font>.' },
  { start: 999.850, end: 1006.143, text: 'Un primo grafico, a sinistra, mostra la diminuzione polinomiale del modulo relativo E\' su' },
  { start: 1006.263, end: 1011.780, text: 'E\' zero in funzione della frazione di <font color="#FFFF00">porosità</font>.' },
  { start: 1011.900, end: 1020.680, text: 'Una tabella riassume l\'evoluzione della <font color="#FFFF00">porosità</font> e dei <font color="#FFFF00">moduli di Young</font>,' },
  { start: 1020.800, end: 1027.297, text: 'vetrosi e gommosi, in funzione della percentuale di particelle di polistirolo e lattice.' },
  { start: 1027.417, end: 1031.777, text: 'Il grafico principale, a destra, conferma il calo dei moduli' },
  { start: 1031.897, end: 1035.363, text: 'vetrosi E\'v e dei moduli gommosi E\'c quando la <font' },
  { start: 1035.483, end: 1041.133, text: 'color="#FFFF00">porosità</font> aumenta dal venticinque al trentuno per cento.' },
  { start: 1041.253, end: 1046.527, text: 'Due vignette, in basso, collegano il Rigidità Taber al peso depositato,' },
  { start: 1046.647, end: 1053.897, text: 'nonché alla <font color="#FFFF00">porosità</font> misurata mediante densità ottica con gli inchiostri.' },
  { start: 1054.017, end: 1056.530, text: 'Pausa 5 secondi, cambio diapositiva' },
  { start: 1056.650, end: 1059.183, text: 'Vediamo ora il comportamento meccanico' },
  { start: 1059.303, end: 1064.353, text: 'Materiali <font color="#FFFF00">compositi</font> contenenti polimeri.' },
  { start: 1064.473, end: 1069.207, text: 'Una tabella comparativa mostra che la <font color="#FFFF00">temperatura' },
  { start: 1069.327, end: 1074.127, text: 'di transizione</font> <font color="#FFFF00">vetrosa</font> del composito' },
  { start: 1074.247, end: 1078.760, text: 'rimane la stessa di quella del solo lattice, sebbene il suo <font' },
  { start: 1078.880, end: 1084.930, text: 'color="#FFFF00">modulo</font> <font color="#FFFF00">elastico</font> sia più elevato.' },
  { start: 1085.050, end: 1089.183, text: 'Un grafico di analisi meccanica dinamica illustra le curve del' },
  { start: 1089.303, end: 1093.817, text: 'modulo di <font color="#FFFF00">Young per tre formulazioni, <font' },
  { start: 1093.937, end: 1099.633, text: 'color="#FFFF00">Tg</font> meno trenta, meno dodici e meno tre gradi Celsius.' },
  { start: 1099.753, end: 1109.753, text: 'Il testo sottolinea che i <font color="#FFFF00">compositi</font> formulati con un polimero mantengono le stesse <font color="#FFFF00">proprietà termo-' },
  { start: 1109.873, end: 1113.457, text: 'viscoelastiche</font> del polimero costituente.' },
  { start: 1113.577, end: 1114.477, text: '' },
  { start: 1114.597, end: 1119.130, text: 'Cambiamo argomento per definire le nozioni di cedimento adesivo e di' },
  { start: 1119.250, end: 1124.547, text: '<font color="#FFFF00">rottura coesiva</font>, nel campo degli adesivi.' },
  { start: 1124.667, end: 1131.227, text: 'A sinistra, quando la coesione interna del polimero è maggiore dell\'adesione alla superficie,' },
  { start: 1131.347, end: 1138.843, text: 'la rottura avviene all\'interfaccia: si tratta di una <font color="#FFFF00">rottura dell\'adesivo</font>.' },
  { start: 1138.963, end: 1142.077, text: 'A destra, se l’adesione tra il polimero e la' },
  { start: 1142.197, end: 1145.243, text: 'superficie supera la coesione del polimero,' },
  { start: 1145.363, end: 1152.327, text: 'la rottura avviene nel cuore della materia: è una <font color="#FFFF00">rottura coesiva</font>.' },
  { start: 1152.447, end: 1155.247, text: 'I diagrammi illustrano queste due modalità' },
  { start: 1155.367, end: 1158.817, text: 'di guasto meccanico tra due substrati solidi.' },
  { start: 1158.937, end: 1159.837, text: '' },
  { start: 1159.957, end: 1167.450, text: 'Vediamo ora l\'effetto della rigidità del polimero, rappresentato dalla sua <font color="#FFFF00">Tg</font>,' },
  { start: 1167.570, end: 1171.553, text: 'sull\'<font color="#FFFF00">energia di rottura</font>.' },
  { start: 1171.673, end: 1173.967, text: 'Il primo grafico, a sinistra,' },
  { start: 1174.087, end: 1187.537, text: 'indica che l\'<font color="#FFFF00">energia di rottura</font> dell\'adesivo diminuisce all\'aumentare della <font color="#FFFF00">temperatura</font> <font color="#FFFF00">transizione vetrosa</font>.' },
  { start: 1187.657, end: 1189.417, text: 'Il secondo, a destra,' },
  { start: 1189.537, end: 1200.653, text: 'mostra al contrario un aumento dell\'<font color="#FFFF00">energia di</font> <font color="#FFFF00">rottura</font> coesiva con la <font color="#FFFF00">Tg</font>.' },
  { start: 1200.773, end: 1209.420, text: 'Il grafico in basso sovrappone questi due meccanismi ed evidenzia un\'<font color="#FFFF00">energia di adesione</font> ottimale,' },
  { start: 1209.540, end: 1213.857, text: 'nel punto di intersezione delle due modalità di cedimento.' },
  { start: 1213.977, end: 1214.877, text: '' },
  { start: 1214.997, end: 1220.330, text: 'Continuiamo con l\'effetto della <font color="#FFFF00">carbossilazione</font> del' },
  { start: 1220.450, end: 1226.163, text: 'lattice sulla coesione della <font color="#FFFF00">carta patinata</font>, a seconda' },
  { start: 1226.283, end: 1233.133, text: 'della <font color="#FFFF00">temperatura</font> <font color="#FFFF00">transizione vetrosa</font>.' },
  { start: 1233.253, end: 1240.433, text: 'Un grafico rappresenta la resistenza alla pelatura a secco rispetto alla <font color="#FFFF00">Tg</font>,' },
  { start: 1240.553, end: 1245.537, text: 'per diversi livelli di <font color="#FFFF00">carbossilazione</font>.' },
  { start: 1245.657, end: 1253.637, text: 'La maggiore <font color="#FFFF00">carbossilazione</font> migliora la coesione della carta quando il lattice è rigido,' },
  { start: 1253.757, end: 1261.987, text: 'vale a dire nella zona di <font color="#FFFF00">cedimento adesivo</font>, ad alta <font color="#FFFF00">Tg</font>.' },
  { start: 1262.107, end: 1270.580, text: 'D\'altra parte, a <font color="#FFFF00">Tg</font> basso, nel dominio della <font color="#FFFF00">rottura coesiva</font>,' },
  { start: 1270.700, end: 1278.083, text: 'la <font color="#FFFF00">carbossilazione</font> non ha effetti significativi sulla coesione della carta.' },
  { start: 1278.203, end: 1279.103, text: '' },
  { start: 1279.223, end: 1285.023, text: 'Vediamo poi l\'effetto della <font color="#FFFF00">dimensione delle particelle</font> di' },
  { start: 1285.143, end: 1290.193, text: 'lattice in caso di <font color="#FFFF00">rottura dell\'adesivo</font>.' },
  { start: 1290.313, end: 1294.847, text: 'Due diagrammi comparativi mostrano che quanto più le particelle sono' },
  { start: 1294.967, end: 1301.017, text: 'grandi tanto più diminuisce la superficie di contatto tra il polimero e il pigmento.' },
  { start: 1301.137, end: 1305.070, text: 'Il grafico a sinistra illustra il decadimento dell\'adesione' },
  { start: 1305.190, end: 1312.907, text: 'energetica quando la <font color="#FFFF00">dimensione</font> <font color="#FFFF00">particelle</font> aumenta.' },
  { start: 1313.027, end: 1318.320, text: 'Questa relazione, inversamente proporzionale al diametro delle particelle,' },
  { start: 1318.440, end: 1323.157, text: 'governa la resistenza meccanica durante la rottura dell\'adesivo.' },
  { start: 1323.277, end: 1324.177, text: '' },
  { start: 1324.297, end: 1331.963, text: 'Ecco ora il passaggio da una <font color="#FFFF00">rottura</font> <font color="#FFFF00">coesiva</font> ad una <font' },
  { start: 1332.083, end: 1342.560, text: 'color="#FFFF00">rottura dell\'adesivo</font>, per <font color="#FFFF00">plastificazione</font> dell\'interfaccia, soprattutto in presenza di acqua.' },
  { start: 1342.680, end: 1351.440, text: 'Una volta essiccate, le forti interazioni acido-base tra i gruppi carbossilato e il pigmento garantiscono un\'elevata adesione,' },
  { start: 1351.560, end: 1356.543, text: 'il che porta a una <font color="#FFFF00">disgregazione coesa</font>.' },
  { start: 1356.663, end: 1363.043, text: 'In un ambiente umido, la presenza di molecole d\'acqua sull\'interfaccia indebolisce l\'adesione' },
  { start: 1363.163, end: 1368.880, text: 'e provoca una transizione al <font color="#FFFF00">rottura dell\'adesivo</font>.' },
  { start: 1369.000, end: 1374.333, text: 'Il grafico in basso confronta i livelli di energia in ambienti secchi e umidi ed' },
  { start: 1374.453, end: 1380.103, text: 'evidenzia il calo energetico complessivo dovuto agli effetti dell\'interfaccia.' },
  { start: 1380.223, end: 1381.123, text: '' },
  { start: 1381.243, end: 1386.290, text: 'Introduciamo ora l\'equivalenza tra temperatura e velocità di caricamento,' },
  { start: 1386.410, end: 1391.660, text: 'secondo la teoria di <font color="#FFFF00">Williams-Landel-Ferry</font>.' },
  { start: 1391.780, end: 1394.847, text: 'Un grafico del <font color="#FFFF00">modulo di' },
  { start: 1394.967, end: 1398.433, text: 'Young</font> in funzione della temperatura mostra lo' },
  { start: 1398.553, end: 1402.220, text: 'spostamento della transizione vetrosa verso temperature' },
  { start: 1402.340, end: 1407.523, text: 'più elevate man mano che la frequenza aumenta da uno a diecimila hertz.' },
  { start: 1407.643, end: 1413.043, text: 'L\'equazione esprime la <font color="#FFFF00">Tg</font> ad una data frequenza come' },
  { start: 1413.163, end: 1419.347, text: 'funzione logaritmica del rapporto tra questa frequenza e una frequenza di riferimento.' },
  { start: 1419.467, end: 1423.913, text: 'Il coefficiente k è vicino a dieci per i polimeri convenzionali,' },
  { start: 1424.033, end: 1429.617, text: 'come i sistemi <font color="#FFFF00">stirene-butadiene</font> o gli acrilati.' },
  { start: 1429.737, end: 1430.637, text: '' },
  { start: 1430.757, end: 1433.557, text: 'Ora combiniamo temperatura e frequenza per' },
  { start: 1433.677, end: 1436.793, text: 'descrivere lo stato fisico del polimero.' },
  { start: 1436.913, end: 1443.473, text: 'Un diagramma schematico divide il comportamento in tre zone: uno stato rigido ad alto modulo,' },
  { start: 1443.593, end: 1449.777, text: 'uno stato intermedio e uno <font color="#FFFF00">stato di gomma</font> a basso modulo.' },
  { start: 1449.897, end: 1456.503, text: 'Il testo, a destra, ricorda l\'importanza di definire con precisione l\'ambiente di utilizzo,' },
  { start: 1456.623, end: 1462.453, text: 'in termini di temperatura e frequenza, per progettare il polimero appropriato.' },
  { start: 1462.573, end: 1465.840, text: 'La domanda posta in fondo ti invita a determinare' },
  { start: 1465.960, end: 1470.010, text: 'esplicitamente queste due variabili dell\'applicazione.' },
  { start: 1470.130, end: 1471.030, text: '' },
  { start: 1471.150, end: 1479.313, text: 'Diamo un\'occhiata a un\'applicazione pratica: progettazione di lattice per <font color="#FFFF00">rotocalco</font>.' },
  { start: 1479.433, end: 1482.813, text: 'A sinistra, illustrazioni e una vista in sezione' },
  { start: 1482.933, end: 1486.267, text: 'eseguita al microscopio elettronico a scansione su' },
  { start: 1486.387, end: 1490.387, text: '<font color="#FFFF00">carta per rotocalco</font> in evidenza' },
  { start: 1490.507, end: 1495.023, text: 'il fenomeno dei punti mancanti sulla superficie della stampa.' },
  { start: 1495.143, end: 1500.277, text: 'Gli schemi del processo di stampa mostrano come la mancanza di comprimibilità' },
  { start: 1500.397, end: 1506.447, text: 'locale impedisca il perfetto trasferimento dell\'inchiostro dalle celle del cilindro.' },
  { start: 1506.567, end: 1509.833, text: 'Il grafico a destra mostra il miglioramento della' },
  { start: 1509.953, end: 1513.400, text: 'stampabilità con la percentuale di butadiene, che' },
  { start: 1513.520, end: 1518.303, text: 'aumenta la flessibilità e la comprimibilità dinamica del lattice.' },
  { start: 1518.423, end: 1519.323, text: '' },
  { start: 1519.443, end: 1522.290, text: 'Passiamo ora all\'emulsione intelligente,' },
  { start: 1522.410, end: 1527.860, text: 'con <font color="#FFFF00">reticolazione</font> stimolata dalla temperatura.' },
  { start: 1527.980, end: 1531.760, text: 'I diagrammi in alto mostrano le fasi dell\'asciugatura,' },
  { start: 1531.880, end: 1539.930, text: 'dall\'<font color="#FFFF00">evaporazione dell\'acqua</font> alla deformazione esagonale delle particelle di lattice.' },
  { start: 1540.050, end: 1542.250, text: 'Gli zoom evidenziano funzionalità' },
  { start: 1542.370, end: 1544.883, text: 'reattive distinte, come idrossile e' },
  { start: 1545.003, end: 1549.567, text: 'gruppi epossidici, trasportati da particelle complementari.' },
  { start: 1549.687, end: 1560.333, text: 'Il grafico in basso mostra l\'aumento della <font color="#FFFF00">massa molare</font> e della <font color="#FFFF00">velocità di gel</font> con la temperatura,' },
  { start: 1560.453, end: 1568.150, text: 'oltre la <font color="#FFFF00">Tg</font>, segno di un\'efficace <font color="#FFFF00">reticolazione</font>.' },
  { start: 1568.270, end: 1569.170, text: '' },
  { start: 1569.290, end: 1574.890, text: 'Vediamo quale effetto ha questa <font color="#FFFF00">reticolazione</font> stimolata' },
  { start: 1575.010, end: 1580.327, text: 'sulle proprietà <font color="#FFFF00">viscoelastiche</font> del polimero.' },
  { start: 1580.447, end: 1587.913, text: 'Un grafico confronta il <font color="#FFFF00">modulo</font> <font color="#FFFF00">elastico</font> in funzione di' },
  { start: 1588.033, end: 1595.950, text: 'temperatura per un polimero standard e per un polimero con <font color="#FFFF00">reticolazione</font> stimolata.' },
  { start: 1596.070, end: 1601.737, text: 'Il polimero reticolato mantiene un <font color="#FFFF00">altopiano della gomma</font>' },
  { start: 1601.857, end: 1607.440, text: 'significativamente più elevato a temperature superiori a cento gradi Celsius.' },
  { start: 1607.560, end: 1611.693, text: 'Questa migliore resistenza termica si spiega con la formazione' },
  { start: 1611.813, end: 1616.597, text: 'di legami covalenti tra le catene durante il trattamento termico.' },
  { start: 1616.717, end: 1617.617, text: '' },
  { start: 1617.737, end: 1619.983, text: 'Iniziamo ora una nuova sezione,' },
  { start: 1620.103, end: 1627.020, text: 'dedicato alla <font color="#FFFF00">stabilità</font> dei lattici nel flusso e nella formulazione.' },
  { start: 1627.140, end: 1629.720, text: 'Si rivolge ai settori dei materiali,' },
  { start: 1629.840, end: 1632.890, text: 'dei cosmetici e delle scienze agricole.' },
  { start: 1633.010, end: 1640.703, text: 'Un fregio di illustrazioni presenta i meccanismi chiave: <font color="#FFFF00">aggregazione</font> dendritica,' },
  { start: 1640.823, end: 1649.520, text: '<font color="#FFFF00">flocculazione</font> anionica o cationica, <font color="#FFFF00">potenziale zeta</font> e sineresi.' },
  { start: 1649.640, end: 1656.307, text: 'Questi fenomeni fisico-chimici condizionano il controllo della <font color="#FFFF00">reologia</font>' },
  { start: 1656.427, end: 1662.210, text: 'e la <font color="#FFFF00">stabilità colloidale</font> dei sistemi di emulsione.' },
  { start: 1662.330, end: 1663.230, text: '' },
  { start: 1663.350, end: 1667.883, text: 'Ricordiamo innanzitutto che la termodinamica indica una fondamentale' },
  { start: 1668.003, end: 1673.187, text: '<font color="#FFFF00">instabilità</font> dei lattici e delle emulsioni.' },
  { start: 1673.307, end: 1678.173, text: 'Un diagramma energetico mostra che la frammentazione del sistema mediante' },
  { start: 1678.293, end: 1683.723, text: 'agitazione richiede un elevato apporto di energia, ha osservato Delta E.' },
  { start: 1683.843, end: 1688.490, text: 'Il sistema tende naturalmente verso uno stato energetico più basso,' },
  { start: 1688.610, end: 1693.973, text: 'E ref, che rende lo stato disperso intrinsecamente instabile nel tempo.' },
  { start: 1694.093, end: 1699.920, text: 'Sono illustrati diversi percorsi di evoluzione, reversibili o irreversibili: <font' },
  { start: 1700.040, end: 1703.087, text: 'color="#FFFF00">flocculazione</font>, <font' },
  { start: 1703.207, end: 1709.300, text: 'color="#FFFF00">sedimentazione</font>, <font color="#FFFF00">mantecatura</font>, <font' },
  { start: 1709.420, end: 1719.050, text: 'color="#FFFF00">coalescenza</font>, <font color="#FFFF00">maturazione Ostwald</font> e <font color="#FFFF00">inversione di fase</font>.' },
  { start: 1719.170, end: 1720.070, text: '' },
  { start: 1720.190, end: 1726.637, text: 'Vediamo nel dettaglio questi fenomeni di <font color="#FFFF00">instabilità</font> dei lattici,' },
  { start: 1726.757, end: 1730.740, text: 'classificati in processi reversibili e irreversibili.' },
  { start: 1730.860, end: 1737.353, text: 'La parte superiore riunisce i fenomeni reversibili: <font color="#FFFF00">scrematura</font>,' },
  { start: 1737.473, end: 1743.587, text: '<font color="#FFFF00">sedimentazione</font> e <font color="#FFFF00">flocculazione</font>,' },
  { start: 1743.707, end: 1748.957, text: 'con particolare attenzione all\'<font color="#FFFF00">esaurimento</font>.' },
  { start: 1749.077, end: 1756.437, text: 'La parte inferiore presenta i meccanismi irreversibili: <font color="#FFFF00">maturazione Ostwald</font>,' },
  { start: 1756.557, end: 1762.673, text: '<font color="#FFFF00">coalescenza</font> e <font color="#FFFF00">coagulazione</font>.' },
  { start: 1762.793, end: 1767.527, text: 'L\'evoluzione di queste degradazioni irreversibili porta inevitabilmente' },
  { start: 1767.647, end: 1772.030, text: 'ad una completa separazione di fase del sistema colloidale.' },
  { start: 1772.150, end: 1773.050, text: '' },
  { start: 1773.170, end: 1777.483, text: 'Per controllare questa <font color="#FFFF00">stabilità</font>,' },
  { start: 1777.603, end: 1784.587, text: 'ci basiamo sulla <font color="#FFFF00">teoria DLVO</font> applicata ad una dispersione colloidale.' },
  { start: 1784.707, end: 1787.240, text: 'Il grafico mostra l\'energia potenziale' },
  { start: 1787.360, end: 1790.340, text: 'di interazione in funzione della distanza,' },
  { start: 1790.460, end: 1803.557, text: 'con un <font color="#FFFF00">minimo primario</font>, un <font color="#FFFF00">minimo</font> <font color="#FFFF00">secondario</font> e una <font color="#FFFF00">barriera energetica</font>.' },
  { start: 1803.677, end: 1809.657, text: 'Per evitare agglomerazioni irreversibili è necessario aumentare la barriera energetica,' },
  { start: 1809.777, end: 1813.493, text: 'attraverso meccanismi elettrostatici o entropici.' },
  { start: 1813.613, end: 1823.173, text: 'Per prevenire la <font color="#FFFF00">flocculazione</font> reversibile, in particolare mediante <font color="#FFFF00">esaurimento</font>,' },
  { start: 1823.293, end: 1829.677, text: 'la profondità del <font color="#FFFF00">minimo secondario</font> dovrebbe essere ridotta.' },
  { start: 1829.797, end: 1830.697, text: '' },
  { start: 1830.817, end: 1836.463, text: 'Torniamo alle ipotesi fondamentali della <font color="#FFFF00">teoria DLVO</font>,' },
  { start: 1836.583, end: 1840.793, text: 'sviluppata da Derjaguin, Landau, Verwey e Overbeek.' },
  { start: 1840.913, end: 1845.693, text: 'Il grafico a sinistra mostra la curva dell\'energia potenziale totale,' },
  { start: 1845.813, end: 1849.463, text: 'somma delle forze repulsive U R e attraente U A.' },
  { start: 1849.583, end: 1853.183, text: 'Le ipotesi stabiliscono che la superficie sia rigida e' },
  { start: 1853.303, end: 1857.483, text: 'caricata uniformemente e che il potenziale rimanga costante,' },
  { start: 1857.603, end: 1862.320, text: 'senza ridistribuzione delle cariche o variazione dei controioni.' },
  { start: 1862.440, end: 1867.800, text: 'Infine, il solvente interviene solo attraverso la sua costante dielettrica,' },
  { start: 1867.920, end: 1872.103, text: 'senza reazione chimica o rigonfiamento delle particelle.' },
  { start: 1872.223, end: 1873.123, text: '' },
  { start: 1873.243, end: 1881.157, text: 'Esaminiamo ora la forza di attrazione per <font color="#FFFF00">esaurimento</font> e l\'energia potenziale associata,' },
  { start: 1881.277, end: 1886.107, text: 'U D, nel quadro della <font color="#FFFF00">teoria DLVO</font>.' },
  { start: 1886.227, end: 1888.960, text: 'Il fenomeno si verifica quando particelle' },
  { start: 1889.080, end: 1891.547, text: 'di raggio a e micelle di dimensione L' },
  { start: 1891.667, end: 1894.667, text: 'avvicinarsi ad una distanza interparticellare' },
  { start: 1894.787, end: 1897.837, text: 'R inferiore alla condizione geometrica.' },
  { start: 1897.957, end: 1904.270, text: 'L\'esclusione delle micelle dalla zona interparticellare crea un richiamo osmotico entropico,' },
  { start: 1904.390, end: 1908.573, text: 'che induce una forza attrattiva netta tra le particelle.' },
  { start: 1908.693, end: 1914.027, text: 'Il <font color="#FFFF00">potenziale di esaurimento</font> è espresso in funzione' },
  { start: 1914.147, end: 1919.330, text: 'della pressione osmotica Pi e delle dimensioni geometriche del sistema.' },
  { start: 1919.450, end: 1920.350, text: '' },
  { start: 1920.470, end: 1928.963, text: 'Illustriamo l\'<font color="#FFFF00">esaurimento</font> con un esempio concreto: un sistema di emulsione di caseina e olio,' },
  { start: 1929.083, end: 1931.600, text: 'a seconda della concentrazione.' },
  { start: 1931.720, end: 1935.320, text: 'Un grafico dell\'energia potenziale mostra l\'evoluzione' },
  { start: 1935.440, end: 1938.973, text: 'del pozzo di attrazione per concentrazioni di caseina' },
  { start: 1939.093, end: 1943.257, text: 'di venti, quaranta e sessanta grammi per chilogrammo.' },
  { start: 1943.377, end: 1952.270, text: 'A venti grammi per chilogrammo, la <font color="#FFFF00">pressione osmotica</font> rimane bassa e la dispersione rimane stabile,' },
  { start: 1952.390, end: 1956.040, text: 'senza <font color="#FFFF00">aggregazione</font>.' },
  { start: 1956.160, end: 1960.873, text: 'A quaranta e sessanta grammi per chilogrammo, il forte aumento della' },
  { start: 1960.993, end: 1963.927, text: '<font color="#FFFF00">pressione</font> <font' },
  { start: 1964.047, end: 1967.647, text: 'color="#FFFF00">osmotica</font> approfondisce il <font' },
  { start: 1967.767, end: 1976.310, text: 'color="#FFFF00">minimo secondario</font>, dando luogo alla formazione di agglomerati, quindi di una rete flocculata.' },
  { start: 1976.430, end: 1977.330, text: '' },
  { start: 1977.450, end: 1983.717, text: 'Passiamo all\'impatto della concentrazione di <font color="#FFFF00">metilcellulosa</font> sulla' },
  { start: 1983.837, end: 1989.353, text: 'morfologia dei <font color="#FFFF00">fiocchi</font> all\'interno del lattice.' },
  { start: 1989.473, end: 1994.520, text: 'Una griglia di immagini microscopiche confronta concentrazioni crescenti,' },
  { start: 1994.640, end: 2002.157, text: 'dallo zero virgola uno allo zero virgola quattro per cento di <font color="#FFFF00">metilcellulosa</font>.' },
  { start: 2002.277, end: 2009.123, text: 'Le tre serie di immagini permettono di visualizzare la struttura della rete prima dell\'essiccazione,' },
  { start: 2009.243, end: 2012.493, text: 'quindi dopo l\'essiccazione lenta o rapida.' },
  { start: 2012.613, end: 2019.793, text: 'L\'aumento della concentrazione e la cinetica di evaporazione modificano significativamente la dimensione,' },
  { start: 2019.913, end: 2023.763, text: 'la coesione e la struttura degli aggregati formati.' },
  { start: 2023.883, end: 2024.783, text: '' },
  { start: 2024.903, end: 2027.503, text: 'Vediamo ora le origini della repulsione' },
  { start: 2027.623, end: 2032.073, text: 'elettrostatica sulla superficie delle particelle di lattice.' },
  { start: 2032.193, end: 2035.327, text: 'Vengono presentati tre principali meccanismi di' },
  { start: 2035.447, end: 2038.697, text: 'stabilizzazione della carica superficiale.' },
  { start: 2038.817, end: 2044.150, text: 'L\'adsorbimento di <font color="#FFFF00">tensioattivi</font> anionici o cationici' },
  { start: 2044.270, end: 2048.253, text: 'fornisce una carica superficiale negativa o positiva.' },
  { start: 2048.373, end: 2055.087, text: 'L\'incorporazione di <font color="#FFFF00">comonomeri</font> ionogeni innesta direttamente cariche,' },
  { start: 2055.207, end: 2059.570, text: 'come gruppi carbossilato, sulla superficie del polimero.' },
  { start: 2059.690, end: 2060.590, text: '' },
  { start: 2060.710, end: 2064.977, text: 'Continuiamo con il ruolo essenziale degli acidi ionomerici <font' },
  { start: 2065.097, end: 2070.747, text: 'color="#FFFF00">comonomeri</font> nella stabilizzazione elettrica dei lattici.' },
  { start: 2070.867, end: 2073.733, text: 'La distribuzione superficiale dipende dalla' },
  { start: 2073.853, end: 2076.587, text: 'solubilità relativa in acqua e nella fase' },
  { start: 2076.707, end: 2081.403, text: 'organica, mentre pKa e dissociazione influenzano la cinetica.' },
  { start: 2081.523, end: 2084.723, text: 'Una tabella comparativa descrive in dettaglio le' },
  { start: 2084.843, end: 2088.670, text: 'proprietà fisiche e chimiche di sei acidi: fumarico,' },
  { start: 2088.790, end: 2093.380, text: 'maleico, itaconico, metacrilico, acrilico e crotonico.' },
  { start: 2093.500, end: 2097.813, text: 'L\'acido acrilico si distingue come uno dei migliori candidati,' },
  { start: 2097.933, end: 2103.050, text: 'grazie alla sua miscibilità in acqua e alla sua solubilità in toluene.' },
  { start: 2103.170, end: 2104.070, text: '' },
  { start: 2104.190, end: 2111.703, text: 'Vediamo ora l\'espressione matematica del <font color="#FFFF00">potenziale di repulsione elettrostatica</font>,' },
  { start: 2111.823, end: 2115.920, text: 'U R, nella <font color="#FFFF00">teoria DLVO</font>.' },
  { start: 2116.040, end: 2118.067, text: 'Un diagramma, a sinistra,' },
  { start: 2118.187, end: 2126.950, text: 'mostra la compenetrazione e sovrapposizione di doppi strati elettrici attorno a due particelle di raggio a, separate da R.' },
  { start: 2127.070, end: 2132.717, text: 'L\'equazione esprime l\'energia potenziale in funzione della permettività del mezzo,' },
  { start: 2132.837, end: 2140.553, text: 'del potenziale superficiale pari a zero psi e della <font color="#FFFF00">dimensione delle particelle</font>.' },
  { start: 2140.673, end: 2147.940, text: 'Coinvolge la lambda <font color="#FFFF00">lunghezza</font> <font color="#FFFF00">Debye</font> e rimane valida' },
  { start: 2148.060, end: 2155.643, text: 'per un rapporto tra il raggio e il <font color="#FFFF00">Lunghezza del debito</font> molto maggiore di uno.' },
  { start: 2155.763, end: 2156.663, text: '' },
  { start: 2156.783, end: 2161.630, text: 'Ciò evidenzia l\'importanza dello spessore del doppio strato elettrico,' },
  { start: 2161.750, end: 2170.580, text: 'o <font color="#FFFF00">lunghezza</font> <font color="#FFFF00">Debye</font>, per la <font color="#FFFF00">stabilità</font>.' },
  { start: 2170.700, end: 2175.213, text: 'A destra, un diagramma rappresenta lo strato rigido di Stern e lo' },
  { start: 2175.333, end: 2179.847, text: 'strato diffuso di Gouy-Chapman, con il decadimento del potenziale' },
  { start: 2179.967, end: 2184.617, text: 'elettrico fino al <font color="#FFFF00">potenziale zeta</font>.' },
  { start: 2184.737, end: 2188.870, text: 'L\'equazione esprime il decadimento esponenziale del potenziale' },
  { start: 2188.990, end: 2194.107, text: 'elettrico psi di x in funzione della distanza x e del parametro kappa.' },
  { start: 2194.227, end: 2204.007, text: 'Il grafico a sinistra mostra che riducendo lo spessore del doppio strato si abbassa la <font color="#FFFF00">barriera energetica</font> Phi max,' },
  { start: 2204.127, end: 2208.577, text: 'che favorisce la <font color="#FFFF00">flocculazione</font>.' },
  { start: 2208.697, end: 2209.597, text: '' },
  { start: 2209.717, end: 2214.563, text: 'Vediamo come la presenza di ioni scherma la repulsione elettrostatica,' },
  { start: 2214.683, end: 2219.667, text: 'riducendo la <font color="#FFFF00">lunghezza di Debye</font> lambda.' },
  { start: 2219.787, end: 2222.253, text: 'La formula generale esprime lambda in' },
  { start: 2222.373, end: 2225.467, text: 'funzione della permettività, temperatura,' },
  { start: 2225.587, end: 2229.770, text: 'nonché la carica e la concentrazione degli ioni opposti.' },
  { start: 2229.890, end: 2236.003, text: 'Per un sale monovalente in acqua a venticinque gradi Celsius l\'espressione si semplifica:' },
  { start: 2236.123, end: 2239.573, text: 'zero virgola tre diviso per la radice di c i.' },
  { start: 2239.693, end: 2249.320, text: 'Una tabella illustra l\'effetto della <font color="#FFFF00">forza</font> <font color="#FFFF00">ionica</font>: più la concentrazione aumenta,' },
  { start: 2249.440, end: 2255.670, text: 'più lo spessore del doppio strato diminuisce drasticamente, da cento a un nanometro.' },
  { start: 2255.790, end: 2256.690, text: '' },
  { start: 2256.810, end: 2263.257, text: 'Studiamo ora l\'effetto dell\'aggiunta di cationi bivalenti <font color="#FFFF00">calcio</font>,' },
  { start: 2263.377, end: 2268.540, text: 'Ca 2 plus, sulla <font color="#FFFF00">stabilità</font> dei lattici.' },
  { start: 2268.660, end: 2272.887, text: 'Sono schematizzati tre stati del sistema: lattice stabile,' },
  { start: 2273.007, end: 2277.257, text: 'formazione di coagulati e gelificazione delle particelle.' },
  { start: 2277.377, end: 2279.777, text: 'Due immagini al microscopio mostrano' },
  { start: 2279.897, end: 2285.030, text: 'che in presenza di <font color="#FFFF00">cloruro di calcio</font> senza <font' },
  { start: 2285.150, end: 2289.243, text: 'color="#FFFF00">tensioattivo</font>, il lattice coagula,' },
  { start: 2289.363, end: 2297.060, text: 'mentre con il dieci per cento di <font color="#FFFF00">tensioattivo</font>, la dispersione rimane stabile.' },
  { start: 2297.180, end: 2301.940, text: 'parametri esterni, come la temperatura, l\'agitazione e la presenza' },
  { start: 2302.060, end: 2306.773, text: 'di <font color="#FFFF00">tensioattivi</font>, influenzano fortemente' },
  { start: 2306.893, end: 2311.810, text: 'il tipo e la cinetica di <font color="#FFFF00">aggregazione</font>.' },
  { start: 2311.930, end: 2312.830, text: '' },
  { start: 2312.950, end: 2320.083, text: 'Un <font color="#FFFF00">diagramma di fase</font> illustra quindi la <font color="#FFFF00">stabilità</font>' },
  { start: 2320.203, end: 2328.700, text: 'del lattice in presenza di cationi <font color="#FFFF00">calcio</font>, a seconda del contenuto di acido superficiale.' },
  { start: 2328.820, end: 2337.533, text: 'Nel grafico è riportata la percentuale di cloruro di <font color="#FFFF00">calcio</font> in funzione del tasso dei gruppi acidi,' },
  { start: 2337.653, end: 2340.770, text: 'espresso in microequivalenti per grammo.' },
  { start: 2340.890, end: 2346.183, text: 'Vengono identificate tre aree: una zona di gel a basso contenuto di acido,' },
  { start: 2346.303, end: 2352.753, text: 'una zona intermedia di grumi o grumi e una zona di <font color="#FFFF00">stabilità</font>.' },
  { start: 2352.873, end: 2357.407, text: 'L\'aumento della densità dell\'acido sulla superficie delle particelle' },
  { start: 2357.527, end: 2364.577, text: 'amplia il range di <font color="#FFFF00">stabilità</font> di fronte all\'aggiunta di sali bivalenti.' },
  { start: 2364.697, end: 2365.597, text: '' },
  { start: 2365.717, end: 2372.317, text: 'Aggiungiamo ora l\'influenza congiunta del <font color="#FFFF00">pH</font> e della concentrazione di' },
  { start: 2372.437, end: 2379.087, text: '<font color="#FFFF00">calcio</font> sulla <font color="#FFFF00">stabilità</font> dei lattici.' },
  { start: 2379.207, end: 2386.033, text: 'Un diagramma traccia la concentrazione di <font color="#FFFF00">calcio</font>, in moli per litro,' },
  { start: 2386.153, end: 2392.670, text: 'rispetto al <font color="#FFFF00">pH</font> e definisce diverse regioni dello stato fisico.' },
  { start: 2392.790, end: 2395.123, text: 'A una bassa concentrazione di <font' },
  { start: 2395.243, end: 2398.623, text: 'color="#FFFF00">calcio</font>, il sistema rimane' },
  { start: 2398.743, end: 2402.123, text: 'stabile; a valori più alti e a seconda del <font' },
  { start: 2402.243, end: 2407.873, text: 'color="#FFFF00">pH</font> compaiono aree metastabili, gel o grumi insoliti.' },
  { start: 2407.993, end: 2414.773, text: 'A <font color="#FFFF00">pH</font> acido e ad alto contenuto di <font color="#FFFF00">calcio</font>,' },
  { start: 2414.893, end: 2424.210, text: 'la <font color="#FFFF00">flocculazione</font> seguita da una riorganizzazione omogenea consente la fluidificazione della sospensione.' },
  { start: 2424.330, end: 2425.230, text: '' },
  { start: 2425.350, end: 2429.397, text: 'Ci stiamo ora avvicinando ad una nuova sezione, intitolata' },
  { start: 2429.517, end: 2434.033, text: '“Protezione dei lattici in relazione alla loro applicazione”.' },
  { start: 2434.153, end: 2439.800, text: 'Annuncia il trattamento dei meccanismi di stabilizzazione e protezione colloidale,' },
  { start: 2439.920, end: 2442.570, text: 'di origine osmotica ed elettrica.' },
  { start: 2442.690, end: 2449.830, text: 'Un fregio visivo, a fondo pagina, richiama le nozioni di <font color="#FFFF00">aggregazione</font>,' },
  { start: 2449.950, end: 2458.047, text: '<font color="#FFFF00">potenziale zeta</font>, controllo reologico e <font color="#FFFF00">depauperamento</font>.' },
  { start: 2458.167, end: 2462.833, text: 'Questo capitolo tratta la regolazione delle proprietà della superficie' },
  { start: 2462.953, end: 2468.137, text: 'per adattare il comportamento del lattice ai vincoli dell\'applicazione.' },
  { start: 2468.257, end: 2469.157, text: '' },
  { start: 2469.277, end: 2474.990, text: 'Torniamo alle origini della <font color="#FFFF00">repulsione elettrostatica</font>,' },
  { start: 2475.110, end: 2479.560, text: 'questa volta dal punto di vista della protezione in lattice.' },
  { start: 2479.680, end: 2487.173, text: 'Sono illustrati tre percorsi di carica superficiale: il <font color="#FFFF00">tensioattivo</font> anionico,' },
  { start: 2487.293, end: 2494.877, text: 'il <font color="#FFFF00">tensioattivo</font> cationico e il <font color="#FFFF00">comonomero</font> ionico.' },
  { start: 2494.997, end: 2501.243, text: 'L\'adsorbimento di <font color="#FFFF00">tensioattivi</font> fornisce una carica rimovibile,' },
  { start: 2501.363, end: 2508.547, text: 'mentre l\'incorporazione di <font color="#FFFF00">comonomeri</font> crea cariche covalenti permanenti.' },
  { start: 2508.667, end: 2513.667, text: 'Questi meccanismi determinano la <font color="#FFFF00">stabilità</font> del' },
  { start: 2513.787, end: 2519.237, text: 'doppio strato elettrico durante i processi di stoccaggio e implementazione.' },
  { start: 2519.357, end: 2520.603, text: 'Pausa 5 secondi,' },
  { start: 2520.723, end: 2528.173, text: 'cambia diapositiva Vediamo ora il ruolo delle macromolecole sulla superficie delle particelle di lattice.' },
  { start: 2528.293, end: 2532.760, text: 'Due rappresentazioni di particelle circondate da catene polimeriche' },
  { start: 2532.880, end: 2537.463, text: 'illustrare i diversi metodi di modificazione della superficie.' },
  { start: 2537.583, end: 2542.497, text: 'A sinistra, lo strato macromolecolare deriva dall\'adsorbimento di <font' },
  { start: 2542.617, end: 2549.200, text: 'color="#FFFF00">tensioattivi</font> non ionici o dall\'innesto chimico di alcol polivinilico.' },
  { start: 2549.320, end: 2553.700, text: 'A destra, La <font color="#FFFF00">stabilizzazione</font> <font' },
  { start: 2553.820, end: 2558.420, text: 'color="#FFFF00">sterica</font> si ottiene utilizzando specifici <font' },
  { start: 2558.540, end: 2565.503, text: 'color="#FFFF00">comonomeri</font>, come i macromeri di poliossietilene o di esteri metacrilici.' },
  { start: 2565.623, end: 2566.523, text: '' },
  { start: 2566.643, end: 2574.223, text: 'Vediamo ora nel dettaglio la <font color="#FFFF00">stabilizzazione</font> <font color="#FFFF00">sterica</font>,' },
  { start: 2574.343, end: 2583.707, text: 'attraverso due contributi: l\'<font color="#FFFF00">effetto osmotico</font> e la <font color="#FFFF00">restrizione di volume</font>.' },
  { start: 2583.827, end: 2592.607, text: 'L\'<font color="#FFFF00">effetto osmotico</font> genera una concentrazione eccessiva locale di polimero nella zona di interazione,' },
  { start: 2592.727, end: 2597.443, text: 'provocando una richiesta di solvente che respinge le particelle.' },
  { start: 2597.563, end: 2605.563, text: 'La <font color="#FFFF00">restrizione di volume</font> induce una perdita di entropia conformazionale delle macromolecole' },
  { start: 2605.683, end: 2608.933, text: 'idrofile e crea forze elastiche repulsive.' },
  { start: 2609.053, end: 2613.053, text: 'L\'energia libera della <font color="#FFFF00">stabilizzazione' },
  { start: 2613.173, end: 2616.800, text: 'sterica</font>, Delta G ST, combina il termine di' },
  { start: 2616.920, end: 2622.910, text: 'miscelazione, Delta G M, e il termine di restrizione di volume, Delta G RV.' },
  { start: 2623.030, end: 2623.930, text: '' },
  { start: 2624.050, end: 2627.317, text: 'Facciamo il punto con una tabella comparativa dei' },
  { start: 2627.437, end: 2630.903, text: 'vantaggi e degli svantaggi dei tre principali metodi' },
  { start: 2631.023, end: 2635.050, text: 'di stabilizzazione colloidale: elettrostatico, osmotico' },
  { start: 2635.170, end: 2639.620, text: 'e dalla <font color="#FFFF00">limitazione del volume</font>.' },
  { start: 2639.740, end: 2643.207, text: 'La stabilizzazione elettrostatica è insensibile alle' },
  { start: 2643.327, end: 2647.507, text: 'variazioni di temperatura e alla qualità del solvente, ma il' },
  { start: 2647.627, end: 2652.810, text: 'suo maggior punto debole è l\'estrema sensibilità alla presenza di ioni.' },
  { start: 2652.930, end: 2656.530, text: 'La stabilizzazione osmotica non è influenzata né dalla' },
  { start: 2656.650, end: 2659.983, text: '<font color="#FFFF00">forza ionica</font> né dalla' },
  { start: 2660.103, end: 2664.017, text: 'temperatura, ma è vulnerabile alla scelta dei solventi e' },
  { start: 2664.137, end: 2668.920, text: 'alla concorrenza con i <font color="#FFFF00">tensioattivi</font>.' },
  { start: 2669.040, end: 2671.953, text: 'Infine, la stabilizzazione mediante <font' },
  { start: 2672.073, end: 2675.140, text: 'color="#FFFF00">restrizione di volume</font> è' },
  { start: 2675.260, end: 2678.973, text: 'insensibile agli ioni e alla qualità del solvente, ma' },
  { start: 2679.093, end: 2684.610, text: 'è soggetta all\'influenza diretta della temperatura e degli sforzi di taglio.' },
  { start: 2684.730, end: 2685.630, text: '' },
  { start: 2685.750, end: 2690.350, text: 'Passiamo ora all\'<font color="#FFFF00">aggregazione di cluster</font>' },
  { start: 2690.470, end: 2695.520, text: 'a diffusione limitata o al modello <font color="#FFFF00">DLCA</font>.' },
  { start: 2695.640, end: 2699.087, text: 'In questo processo, la crescita degli aggregati è' },
  { start: 2699.207, end: 2702.340, text: 'controllata dalla diffusione delle particelle e' },
  { start: 2702.460, end: 2706.910, text: 'avviene mediante collisione di ammassi di dimensioni simili.' },
  { start: 2707.030, end: 2710.297, text: 'Queste cinetiche di associazione a coppie portano' },
  { start: 2710.417, end: 2714.667, text: 'a strutture con una distribuzione dimensionale ristretta.' },
  { start: 2714.787, end: 2721.167, text: 'Il cluster frattale formato segue la legge di scala M uguale a R g elevato alla potenza di d,' },
  { start: 2721.287, end: 2727.203, text: 'con una <font color="#FFFF00">dimensione frattale</font> d di circa un punto otto.' },
  { start: 2727.323, end: 2728.223, text: '' },
  { start: 2728.343, end: 2737.993, text: 'Continuiamo con il regime di <font color="#FFFF00">aggregazione di cluster</font> o <font color="#FFFF00">RLCA</font> a reazione limitata.' },
  { start: 2738.113, end: 2743.627, text: 'L\'<font color="#FFFF00">aggregazione</font> non è più limitata dalla diffusione,' },
  { start: 2743.747, end: 2748.597, text: 'ma dalla cinetica del processo di agglomerazione chimica o fisica.' },
  { start: 2748.717, end: 2752.983, text: 'La probabilità di attraversare la <font color="#FFFF00">barriera' },
  { start: 2753.103, end: 2758.353, text: 'energetica</font> E b segue una legge esponenziale di meno E b su k B T.' },
  { start: 2758.473, end: 2764.787, text: 'Questo regime porta ad una distribuzione dimensionale più ampia e ad aggregati più compatti,' },
  { start: 2764.907, end: 2770.490, text: 'di <font color="#FFFF00">dimensione frattale</font> vicina a due virgola tre.' },

  { start: 2770.491, end: 2774.000, text: 'Grazie per la vostra attenzione. Andate al capitolo 3.' },
];


